// lib/data/books_data.dart
//
// ═══════════════════════════════════════════════════════════════════════════
// TO ADD YOUR REAL CONTENT:
//   Replace the `content` strings below with your actual Granth text.
//   Each BookPage has a `title` (shown as header) and `content` (body text).
//   You can use Devanagari (Hindi), English, or mixed text.
// ═══════════════════════════════════════════════════════════════════════════

class BookPage {
  final String title;
  final String content;
  const BookPage({required this.title, required this.content});
}

class BookData {
  final String id;
  final String title;
  final String subtitle;
  final List<BookPage> pages;
  const BookData({
    required this.id,
    required this.title,
    required this.subtitle,
    required this.pages,
  });
}

class BooksData {
  static const List<BookData> all = [_book1, _book2, _book3];

  // ── Book 1 ─────────────────────────────────────────────────────────────
  static const _book1 = BookData(
    id: 'granth_1',
    title: 'प्रियतम काव्य',
    subtitle: 'प्रथम ग्रंथ',
    pages: [
      BookPage(
        title: 'प्रथम शतक',
        content: '''ललिताम्बामयीं ध्येयां रामदत्तापदाभिधाम् । 
आत्मस्वरूपिणीं साध्वीं वन्देऽहं धर्ममातरम्॥१॥ राधा ॥
कृष्णस्वरूपिणीं वन्दे हनुमद्गुप्तसन्ततिम्। 
नित्यां धर्मस्वसारं वै मञ्जुश्यामां सहोदराम्॥२॥ कृष्ण ॥

इन धुँधली आँखों से सब कुछ मैं देख नहीं पाती, प्रियतम ! 
सपना-सा विश्व बने तुमको मैं प्यार न दे पायी, प्रियतम !
था खेल मनोहर वह, जिसमें गुरुदेव बने तुम थे, प्रियतम ! 
करने बैठी हूँ अब पूजा प्राणों में व्यथा लिये, प्रियतम॥१॥ 

हूँ वही, जिसे कहकर 'मेरे प्राणों की रानी', हे प्रियतम ! 
थे पकड़ लिये वे हाथ, लगी मिंहदी जिनमें थी, हे प्रियतम ! 
पर भग्न हुआ-सा था गृह वह, जिसमें रहती बाला, प्रियतम ! 
थी तम से परिपूरित रजनी, जब तुम आये थे, हे प्रियतम॥२॥

दीपक तक नहीं वहाँ था, कुछ कण थे रज के बिखरे, प्रियतम ! 
गोबर-मिट्टी से यद्यपि थी अवनी लीपी-पोती, प्रियतम ! 
थे सब कपाट टूटे गवाक्ष के तथा द्वार के भी, प्रियतम ! 
वह पवन धूलि भरकर दुकूल में लाया करता था, प्रियतम॥३॥

उस कच्चे घर में रहकर भी निर्मल थी वह बाला, प्रियतम ! 
था सका नहीं छू उसे एक कण बाहर से आया, प्रियतम ! 
थी छिपी शक्ति उसमें सहस्र पावक-पुञ्जों की, हे प्रियतम ! 
सामर्थ्य नहीं थी कहीं किसी में, जो दूषित कर दे, प्रियतम॥४॥

उस पथसे जो जाते, पाते पर देख भग्न गृह ही, प्रियतम !
अवकाश कहाँ किसको था, जो भीतर जाकर देखे, प्रियतम !
है मात्र खण्डहर ही, प्रायः सबके मनमें आता, प्रियतम ! 
वे थे राही, था लगा ध्यान उनका पथपर अपने, प्रियतम॥५॥

दल तथाकथित राजाओं का, ऋषियों का, मुनियों का, प्रियतम !
कुछ सिद्धों का भी आता था एवं गन्धर्वों का, प्रियतम !
पड़ती उसपर जो दृष्टि कहीं उनकी पैनी-सी, हे प्रियतम !
वह भवन वस्तु बनता विराग अथवा विनोद की ही, प्रियतम॥६॥

कुछ थे विहङ्ग उसमें अवश्य, पर थे वे सब सोये, प्रियतम !
थे नीड़ सभी के भिन्न-भिन्न, सहचरी साथ में थी, प्रियतम !
उनका था वह संसार अलग, वे थे भूले उसमें, प्रियतम !
है कौन यहाँ बाला बसती, वे क्या कैसे जानें, प्रियतम॥७॥

वह रात नहीं थी चार पहर वाली, जो मिट जाती, प्रियतम !
हैं सब कहते अनादि उसको, जो पण्डित सच्चे हैं, प्रियतम !
होता है उसका अन्त उसी के जीवन में, बस, हे प्रियतम !
जो रूप अनिर्वचनीय तथा अद्भुत-अचिन्त्य देखे, प्रियतम॥८॥

इसलिये विहङ्गम सोये थे, पर थी जगती बाला, प्रियतम ! 
थी नींद नहीं आयी क्षणभर भी जीवनमें उसके, प्रियतम ! 
झरती रहती आँखें, ज्वाला हृत्तलमें थी जलती, प्रियतम ! 
था पास नहीं कोई उसके, जो अश्रु पोंछ दे, हे प्रियतम॥९॥

रहते कुञ्चित् काले हरदम थे केश खुले उसके, प्रियतम !
भीगा रहता परिधान नील नयनों की धारा से, प्रियतम !
उन जीर्ण हुए वातायन के रन्ध्रों से लगकर, हे प्रियतम !
देखा करती थी निर्निमेष लोचन से अम्बर को, प्रियतम॥१०॥

भ्रम होता सहसा उसे कभी, रवि उदित हो चुका, हे प्रियतम ! 
सुनने लगती कलरव खग का, भ्रमरों का गुञ्जन, हे प्रियतम ! 
स्वर चातक का 'पी कहाँ' तथा कोयल की 'कू-कू', हे प्रियतम ! 
श्रवणों में आकर लग जाती होने प्रतीति दिन की, प्रियतम॥११॥

आशा की बेलि हरी होती, वे आयें आज कहीं, प्रियतम !
मिलने का फिर अनुभव करती, रस-सरिता में बहती, प्रियतम !
उठता वह बोल पहरुआ खग इतने में धीरे से, प्रियतम !
जगकर उस सपने से बाला रोने लगती थी, हे प्रियतम॥१२॥

थी राजा की पुत्री बाला, स्वर्णिम दिन थे देखे, प्रियतम ! 
माता उसकी थी रानी, वह दृगपुतरी थी जिसकी, प्रियतम ! 
उसकी थी एक बहिन छोटी, प्राणों की छाया थी, प्रियतम ! 
उसका था एक बड़ा भाई, प्राणों का सहचर था, प्रियतम॥१३॥

अगणित सहेलियाँ थीं उसकी, प्राणों की धारा थी, प्रियतम ! 
दासी-दासों का था समूह, थी प्राण बनी उनके, प्रियतम ! 
अगणित कुटुम्बिजन थे उसके, प्राणों की ऊर्मि हुए, प्रियतम ! 
पशु-पक्षी तक के प्राणों में वह थी निवास करती, प्रियतम॥१४॥

उद्यानों में, आरामों में विहगी-सी थी फिरती, प्रियतम !
महलों में चञ्चल चपला-सी हँसकर खेला करती, प्रियतम !
अपलक सब देखा करते थे क्रीड़ा-शैशव उसकी, प्रियतम ! 
न्योछावर जो न हुआ उसपर, था नहीं कहीं कोई, प्रियतम॥१५॥

है बात एक दिन की, जब वह थी वर्ष सात की, हे प्रियतम ! 
मन में आया, जाऊँ वनमें मैं पुष्प चयन करने, प्रियतम ! 
उत्तर की ओर मनोहर था वन एक विशाल घना, प्रियतम ! 
कल-कलनिनादिनी के तट पर शोभा का आकर, हे प्रियतम॥१६॥

रहते थे मानो सदा वहीं ऋतुराज-शरद दोनों, प्रियतम !
पर था निषेध उस कानन में सबके जाने का, हे प्रियतम !
अनुमति राजा की लेकर ही कोई जाता था, हे प्रियतम !
नृपको अपनी कुलदेवी के दर्शन होते उसमें, प्रियतम॥१७॥

अतएव पूर्णिमा जब आती तिथि तथा अमावस की, प्रियतम ! 
थी उस वन की देती फेरी जो प्रजा राज की थी, प्रियतम ! 
उनमें जिसकी अतिशय निष्ठा देवी की होती थी, प्रियतम ! 
उसको दर्शन हो जाता था प्रत्यक्ष दिव्य उनका, प्रियतम॥१८॥

अतुलित पवित्रता का अनुभव तो सबको ही होता, प्रियतम! 
सब आ-आकर अपनी-अपनी बातें कहते वे थे, प्रियतम !
नृपतनया ने थी सुनी वहीं उनसे वनकी गाथा, प्रियतम ! 
उत्कण्ठित अतः हई वह थी जाने के लिये वहाँ, प्रियतम॥१९॥

वह जननी से आकर बोली पीयूष भरे स्वर में, प्रियतम ! 
'कुछ फूल बीन लाऊँ मैं री ! उस वन से' और हँसी, प्रियतम ! 
भर आँखें रानी की आयीं, सुनकर फिर जब देखी, प्रियतम ! 
कैशोरवयस की लाली-सी नवमुख पर पुत्री के, प्रियतम॥२०॥

लोचन के आगे नाच उठी रानी के जीवन की, प्रियतम ! 
घटना प्राचीन, नवीन वधू थी बनी वहीं आयीं, प्रियतम ! 
वह थी सुहाग की रात, मौन थे आर्यपुत्र बैठे, प्रियतम ! 
वे थीं बैठी, था झुका हुआ सिर उनके चरणों में, प्रियतम॥२१॥

जीवनसंगिनी अलौकिक थी सुन्दरी मिली, फिर था, प्रियतम ! 
दोनों में ही नवयौवन का उन्मेष; किंतु दोनों, प्रियतम !
हो गये विरत उन विषयों के उन्मादी भोगों से, प्रियतम !
जागा अन्तस्तल में सहसा ज्योतिर्मय भाव, अहो ! प्रियतम॥२२॥

हम दोनों अभी इसी क्षण से हो चुके समर्पित हैं, प्रियतम !
जो कृपामयी त्रिभुवनजननी हैं, उनके श्रीपदमें, प्रियतम !
किंकरी और किंकर हम हैं दोनों विक्रीत हुए, प्रियतम !
केवल उनकी ही सेवा अब जीवन पर्यन्त करें, प्रियतम॥२३॥

उनका आदेश भले जब हो, तब एक पुत्र बस, हो, प्रियतम ! 
जो परम्परा का नृपकुल की निर्वाह वीर कर दे, प्रियतम ! 
पश्चात् सदा के लिये लीन हम हों श्री-पद-नख में, प्रियतम ! 
आदर्श रखें हम, जिसे प्रजा अपनाकर सुखी बने, प्रियतम॥२४॥

इस निश्चय को लेकर उनने कुछ मास बिताये थे, प्रियतम !
आयी जब रात सदाशिव की उस बार शिशिर ऋतु में, प्रियतम !
आदर से दम्पति ने ली थी दीक्षा सद्गुरु ऋषि से, प्रियतम !
निगमागमसम्मत ली शिक्षा आराधन-पद्धति की, प्रियतम॥२५॥

हरिशयनी निशा मनोहर थी, अर्चन आरम्भ हुआ, प्रियतम !
थी त्रिपुरसुन्दरीकी प्रतिमा प्रासाद-कक्ष में ही, प्रियतम !
अद्भुत सुवर्ण से विरचित थी, फिर था प्रभाव ऐसा, प्रियतम !
हो जाता नमित स्वतः सबका सिर मन्दिर-परिसर में, प्रियतम॥२६॥

हो कहीं चित्त की वृत्ति, किंतु आते ही सीमा में, प्रियतम !
चाहे कोई कैसा भी हो, भावित होता सहसा, प्रियतम ! 
विस्मृत सब कुछ होकर समाधि मानो लग जाती थी, प्रियतम ! 
प्रहरी ही होश कराता यह कहकर 'दर्शन कर लो', प्रियतम॥२७॥

लेकर अञ्जलि में पुष्प, तथा पङ्किल लोचन से, हे प्रियतम ! 
जाकर जब अर्पित कर देता अपने को श्रीपद में, प्रियतम ! 
होता था भान तभी उसको अग्रिम कर्तव्यों का, प्रियतम ! 
वे अहो ! न जाने कब से थीं राजित देवी कुल की, प्रियतम॥२८॥ 

युवराज रूप में ही जब थे वे वर्तमान राजा, प्रियतम !
ऋषितुल्य पितृचरणों की ले अनुमति ली थी उनने, प्रियतम !
अपने ऊपर सँभाल पूरी देवी की सेवा की, प्रियतम !
उसके पहले भूदेवों के द्वारा अर्चन होता, प्रियतम॥२९॥

श्रद्धापूरित मन से यद्यपि युवराज पूछते थे, प्रियतम ! 
भूदेवों से कुलदेवी का इतिवृत्त पुराना, हे प्रियतम ! 
हँसकर पर वे कह देते थे- 'हे वत्स बाट देखो, प्रियतम !
ये जगजननी बतलायेंगी, जो बतलाना होगा', प्रियतम॥३०॥

फिर सभी व्यवस्था सेवा की क्रमशः भूदेवों ने, प्रियतम ! 
अतिशय विनम्र युवराज कुशल मतिमान धीर को ही, प्रियतम ! 
दी सौंप और मंगलमय कर सिर पर रखकर उसके, प्रियतम ! 
'तेरी जय हो' कहकर सहसा अन्तर्हित सभी हुए, प्रियतम॥३१॥

तब से हो गये वर्ष सत्तर, नौ मास और दिन दो, प्रियतम ! 
अविराम भाव-संवलित हुए, नृपने की थी अर्चा, प्रियतम ! 
संबोधन 'सहधर्मिणि' का भी अक्षरशः सत्य घटा, प्रियतम ! 
रानी के जीवन में भी, है तुलना न कहीं जिसकी, प्रियतम॥३२॥

अब पुनः वही हरिशयनी की रजनी थी उजियारी, प्रियतम !
सर्वथा निरभ्र गगन था, सब हँसते-से थे तारे, प्रियतम !
अन्तरसत्वा थी रानी फिर मन्त्री की पत्नी भी, प्रियतम !
थीं हुई त्रिपुरसुन्दरी तुष्ट बहुकाल-अर्चना से, प्रियतम॥३३॥

नौ मास और कुछ दिन पहले इस देवशयन से ही, प्रियतम ! 
प्रत्यक्ष महादेवी का था दर्शन-सौभाग्य मिला, प्रियतम ! 
रानी को, फिर समानशीला मन्त्री की दारा को, प्रियतम ! 
थीं हँसी महामाया एवं कह गयी स्वयं यह थीं, प्रियतम॥३४॥

'आये वह राजपुत्र, इससे पहले गृह मन्त्री का, प्रियतम ! 
मेरी क्रीड़ा की भूमि बने, आरम्भ करूँ मैं ही, प्रियतम ! 
जो प्रथम कृत्य रंगस्थल का है नटी किया करती, प्रियतम ! 
फिर हो लीला होती है जो चिन्मयी कदाचित् ही' प्रियतम॥३५॥

उत्सव था आज नृपतिपुर में अवनीशभवन में भी, प्रियतम !
थी देर घड़ी आधी की ही होने में मध्यनिशा, प्रियतम !
नीराजन लिये खड़े नृप थे, रानी थीं पास खड़ी, प्रियतम !
थीं महात्रिपुरसुन्दरी अहो ! सचमुच अलसायी-सी, प्रियतम॥३६॥ 

दौड़ी आयी थी कहने यह दासी मन्दिर में ही, प्रियतम !
हैं प्रसव-वेदना-सी अनुभव कर रहीं सचिव-गृहणी, प्रियतम ! 
श्री-प्रतिमा के दृग-कमल अहो ! क्षणभर के लिये हिले, प्रियतम ! 
संकेत मिला था रानी को जाने के लिये वहीं, प्रियतम॥३७॥

छूकर वे श्रीपदनख को थीं चल पड़ीं तुरन्त तथा, प्रियतम ! 
पहुँची उस सदन कक्ष में थीं जैसे, बस, भान हुआ, प्रियतम ! 
है ज्योति अंशुमाली की सच फैली सर्वत्र वहाँ, प्रियतम ! 
दासी की आँखें बन्द हुईं, भीतर वह जा न सकी, प्रियतम॥३८॥

मीलितनयना ध्यानस्थ हई मन्त्री की जाया की, प्रियतम !
गोदी में प्रगट जगन्माता हो गयी अचानक थीं, प्रियतम 
अप्रतिम सुन्दरी नवजाता कन्या का वेष लिये, प्रियतम !
केवल रानी ही देख सकीं अद्भुत उस घटना को, प्रियतम॥३९॥

क्षणभर में फिर उसपर निर्मल आवरण एक आया, प्रियतम !
वे नाल आदि वस्तुएँ सभी निर्मित हो गयीं वहाँ, प्रियतम ! 
रो उठी बालिका भी वह अब इस भाँति उधर मानो, प्रियतम ! 
नारायण निद्रित हुए, इधर वे नारायणी जगीं, प्रियतम॥४०॥

कन्या के मुखमण्डल पर थी मोहनता श्री-सी ही, प्रियतम ! 
अङ्गों में भी वैसी ही थी दुःसह-सी प्रभा भरी, प्रियतम !
रोना उसका उस समय अहो ! श्रुति-मधुर तन्त्ररव था, प्रियतम ! 
दर्शक आनन्दविमूढ़ हुए, खिल उठी प्रकृति सारी, प्रियतम॥४१॥

आयी श्रावण कृष्णा की थी फिर तीज वार बुध था, प्रियतम ! 
रवि के अस्ताचल जाने में घटिका थी पाँच बची, प्रियतम ! 
नादित धौंसे के शुभरव से प्रासाद हुआ सहसा, प्रियतम ! 
नृप-तनय-जन्म का मंगलमय संवाद मिला सबको, प्रियतम॥४२॥

नृपबालक के गोरे मुख की शोभा किस भाँति कहूँ, प्रियतम !
देखी जिनने, बोले न कभी, बोले वे, लख न सके, प्रियतम ! 
दो भुजा और नीलिमा मात्र आवृत कर माया से, प्रियतम ! 
सचमुच वे मधुसूदन ही थे आये शिशु-वेष धरे, प्रियतम॥४३॥

दो पर्वत की द्रोणी में थी फैली जो राजपुरी, प्रियतम ! 
बाइस दिन तक कण-कण में था उसके कम्पन सुख का, प्रियतम ! 
रत्नों की ज्योति रात में थी इङ्गित करती, मानो, प्रियतम ! 
नृपतनय-अमात्यसुता के शुभ निर्मल भावी यश का, प्रियतम॥४४॥

महरानी और सचिवगृहणी, दोनों सहोदरा थीं, प्रियतम ! 
थी चाह बहिन की, हो उत्सव, नृपसुत आ जाय तभी, प्रियतम ! 
नृप-कुल-देवी की भी रुचि थी ऐसी ही, इसीलिये, प्रियतम ! 
थी उत्समयी वह नित्य सुखद अँधियारी तीज बनी, प्रियतम॥४५॥

बीता फिर वर्ष और आयी भादों शुक्ला षष्ठी, प्रियतम !
रविवासर था, थे भानु उदित दो घड़ी हुए पहले, प्रियतम !
रानी की एक बहिन जो थी मौसेरी नाते में, प्रियतम !
शारदा सही जो थी, उसको कन्या थी एक हुई, प्रियतम॥४६॥

जो महात्रिपुरसुन्दरी अघटघटनापटीयसी हैं, प्रियतम ! 
चिन्मयी ज्योति उनकी ही थी कन्या बनकर आयी, प्रियतम !
होने वाली लीला जो थी, जिसमें थीं नटी बनी, प्रियतम ! 
वे स्वयं, सचिव के गृह उसका सम्विद्-पट उठा वहाँ, प्रियतम॥४७॥

वह था संयोग, महारानी मिलने आयी थीं, हे प्रियतम ! 
भगिनी से, प्रेरित होकर ही कुलदेवी के द्वारा, प्रियतम ! 
गोदी में तेरह मास तथा सत्रह दिन का शिशु था, प्रियतम ! 
मंगलमय चरण पड़े जब थे उनके उस पत्तन में, प्रियतम॥४८॥

रानी की अनुजा भी उनके थी साथ लिये पुत्री, प्रियतम ! 
दोनों के ही समक्ष अभिनव था दृश्य खुला पहला, प्रियतम ! 
क्रीड़ारत वे दोनों शिशु थे, हाथों में हाथ लिये, प्रियतम ! 
तीनों बहिनें बैठी प्रमुदित थीं देख रही उनको, प्रियतम॥४९॥

इतने में ही मानो सहस्र उग उठे दिवाकर थे, प्रियतम !
रानी की बहिन तीसरी के उर-उदर-लोचनों में, प्रियतम !
हो गयी प्रभा परिणत तुरन्त बालिका-रूपमें थी, प्रियतम !
फिर सरक अङ्क से पड़ी और शिशुओं में जा बैठी, प्रियतम॥५०॥
 
सीमाविहीन अचरज में थीं डूबी तीनों बहिनें, प्रियतम !
है स्वप्न-घटित घटना, अथवा हो रही सत्य यह है, प्रियतम ! 
बन गया असम्भव था निर्णय कर लेना वहाँ इसे, प्रियतम ! 
जड़िमा प्रत्येक रोम में थी तीनों के भर आयी, प्रियतम॥५१॥

यन्त्रित-से हुए, उधर शिशु वे थे खेल लगे करने, प्रियतम ! 
शाखा-चन्द्रमा-न्याय से ही अभिराम दृश्य कह दूँ, प्रियतम !
दृग नचा-नचाकर तीनों ही क्रमशः माताओं के, प्रियतम ! 
कण्ठों से लगकर झूल उठे हँस-हँसकर मृदुल हँसी, प्रियतम॥५२॥

'मेरी मैया है, अहो ! नहीं, मेरी मैया यह है' प्रियतम ! 
अप्रतिम मधुर वाणी यह थी तुतलायी गूँज उठी, प्रियतम ! 
केवल अलिन्द में नहीं, भूत-भावी त्रिभुवन जन के, प्रियतम ! 
प्राणों में जो हैं जुड़े हुए तुम नित्य नीलघन से, प्रियतम॥५३॥

आखिर जब बात परस्पर यह तीनों की तीनों ही, प्रियतम ! 
मैया हैं, तीनों शिशुओंने ली मान फुल्ल दृग से, प्रियतम ! 
मधुमय, अनन्त सुखमय, पावन कौतुक वह बदल गया, प्रियतम ! 
आँखें बदली माताओं की सुन करके क्रन्दन-सा, प्रियतम॥५४॥

वैसी ही माया फैल गयी, वैसी प्रतीति सबको, प्रियतम ! 
होने लग गयी, लोकवत् ही मानो वह जन्मी थी, प्रियतम ! 
आनन्दसिन्धु उमड़ा, सब कुछ जन्मोचित कृत्य हुए, प्रियतम ! 
विस्मित वे किन्तु तीन जननी रह-रहकर हो जातीं, प्रियतम॥५५॥

पूनो तक रानी वहीं रही परिवाके दिन सहसा, प्रियतम ! 
शङ्कित सब हुए, नगर न कहीं हो जाय नष्ट कल ही, प्रियतम ! 
नररूप बने मनुजादों का दल था आने वाला, प्रियतम ! 
अतएव महारानीने दी यह राय, 'सभी चल दो', प्रियतम॥५६॥

‘सर्वथा असम्भव है उनसे भिड़कर हम जयी बनें, प्रियतम !
है नगर निरापद केवल वह मेरा ही भूतल में, प्रियतम !
अनुकम्पा है जगदम्बा की, साहस न किसी में है, प्रियतम !
जो करें अनिष्ट वहाँ के लघु उन कीट-भृङ्ग का भी, प्रियतम॥५७॥

इसलिये तुरन्त वहीं लेकर सबको जाऊँगी मैं, प्रियतम ! 
आबाल-वृद्ध पशु-पक्षी तक कर दें प्रस्थान सभी, प्रियतम !
भय करें न तनिक, कहीं पथ में वे ध्वंस करें हमको, प्रियतम !
हैं सदय जगन्माता मुझपर, रक्षा कर लेंगी वे’, प्रियतम॥५८॥

गति एकमात्र थी यही चले वे प्रातःसे पहले, प्रियतम ! 
सामान शकट में भर जितना सम्भव था भर लेना, प्रियतम ! 
लेंगे सम्भाल आकर फिर यदि सम्भव होगा आना, प्रियतम ! 
ऐसा निश्चय करके होकर निर्मोही जड़धन से, प्रियतम॥५९॥

इस भाँति विदा करके सबको, सबके पीछे रानी, प्रियतम ! 
कहकर 'जय देवि दयामयि जय जगदम्बे, जय ललिते', प्रियतम ! 
सुविशाल एक रथ में दोनों बहिनों को शिशुओं को, प्रियतम ! 
ले साथ चलीं निर्भय मानो भगवती जा रही हों, प्रियतम॥६०॥

वे अहो ! न जाने कैसे थे पहुँचे सब-के-सब ही, प्रियतम ! 
केवल दो घड़ी लगी एवं दीखी वह राजपुरी, प्रियतम ! 
सन्मुख जैसे स्वागत सबका हँस-हँसकर थी करती, प्रियतम ! 
सीमापर खड़े महाराजा थे मंगलकलश लिये, प्रियतम॥६१॥

विभुता का हुआ प्रकाश सत्य अद्भुत उस नृपपुर में, प्रियतम !
सुन्दर-से-सुन्दर पृथक-पृथक सबको आवास मिला, प्रियतम !
सपने में भी उन सबको जो सुख-सुविधा थी न मिली, प्रियतम ! 
वह मिली, वहाँ वे भूल गये पहले निवासथल को, प्रियतम॥६२॥

अवसान वर्ष का हुआ, पुनःआयी पावसऋतु थी, प्रियतम !
अष्टमी भाद्र शुक्ला की थी, रानी थी पीहर में, प्रियतम !
मध्याह्न हुआ था नहीं अभी, थी देर दण्ड दो की, प्रियतम !
थे अचक महाराजा पहुँचे अपने श्वसुरालयमें, प्रियतम॥६३॥

था उदर महारानी का फिर तेजोमय परम बना, प्रियतम ! 
हेमन्त-सम्पदा से जब थी भूषित यह धरा हुई, प्रियतम ! 
नौ मास पूर्व था मार्गशीर्ष, अष्टमी शुक्ल की थी, प्रियतम !
प्रातः की वेला थी, रानी देवी-मन्दिर में थीं, प्रियतम॥६४॥

श्री-प्रतिमा के पद पर जो थी कुसुमावलि पड़ी उसे, प्रियतम ! 
कर में ले, दृग से छुला-छुला अपसारित थीं करती, प्रियतम ! 
थे नहीं अभी राजा आये अर्चन के लिये वहाँ, प्रियतम ! 
कर रही अकेली रानी थीं पूजा की तैयारी, प्रियतम॥६५॥

दीखा यह अकस्मात् उनको, हँस पड़ीं महादेवी, प्रियतम ! 
फिर अहो ! उरस्थल उनका था क्रमशः खुलता जाता, प्रियतम ! 
अञ्चल वह परदा-सा होकर बायें-दायें सरका, प्रियतम ! 
बन गया द्वार उससे निकली मनको हरने वाली, प्रियतम॥६६॥

सुन्दरी अनिर्वचनीय एक कन्या गोरी-भोरी, प्रियतम ! 
रानीके कुन्तल की लट को कर में लेकर बोली, प्रियतम ! 
‘री मैया !’ अहा ! सुधास्यन्दी स्वर था कितना मीठा, प्रियतम ! 
रानी में चेतनता न रही बाहर की किञ्चित् भी, प्रियतम॥६७॥

भीतर की आँख किंतु उनकी थी देख रही घटना, प्रियतम ! 
देखी उनने जो थी, उसका संकेत भले कर दूँ, प्रियतम ! 
द्रुम एक परम रमणीय खड़ा पुष्पित कदम्ब का था, प्रियतम ! 
थी नित्य किशोरी एक, और था एक किशोर वहाँ, प्रियतम॥६८॥

उन दोनों की ही ओर दृष्टि करके जगदम्बा थीं, प्रियतम ! 
कहती- हे सती ! आज करले दर्शन मेरे उर का, प्रियतम ! 
सच्चिदानन्द, असमोर्ध्व और जो भगवत्ता काभी, प्रियतम ! 
है सार-मूल मधुरिमा, यही नीली-पीलीद्युति है, प्रियतम॥६९॥

रसमय, सम्विद्, केवल, अद्वय, जो नील-पीतमय है, प्रियतम ! 
यह नित्य हृदय मेरा, जिसमें हूँ लीन हुई रहती, प्रियतम ! 
लीलारस पीता हुआ नित्य जो युग्मरूप में है, प्रियतम ! 
रहकर दो, नित्य एक जो है, दृग-विषय हुआ वह है, प्रियतम॥७०॥

यह नित्यकिशोरी ही तुझसे बोली थी,‘री मैया !’ प्रियतम ! 
पीयेगी दूध सुधामय यह तेरे पयोधरों का, प्रियतम ! 
यह नित्यकिशोर किंतु तेरी जो प्राणसखी वह है, प्रियतम !
उसका पी लेगा दूध, तभी आयेगी यह पीने, प्रियतम॥७१॥

यह नित्य समाया रहता है उसके प्राणों में ही, प्रियतम ! 
यह नित्य समायी रहती है तेरे ही प्राणों में, प्रियतम ! 
तुम दोनों भूल गयी हो यह इनकी ही इच्छा से, प्रियतम ! 
अब याद करा देती हूँ मैं, जय हो तुम दोनों की ! प्रियतम॥७२॥

“दिव्यातिदिव्य सौरभ अनुपम तेरे इन केशों से, प्रियतम !
हो रहा यहाँ प्रसरित अब है, आ चुके नृपति भी हैं, प्रियतम ! 
संकल्प पवित्र और उनके मन में यह जाग उठा, प्रियतम ! 
सन्तति हो एक पुनः ऐसी सुरभित अलकों वाली, प्रियतम॥७३॥

अनुभूति किंतु अपनी यह तुम राजा से मत कहना, प्रियतम ! 
रोने जब फूट-फूटकर वे रजनीमें आज लगें, प्रियतम ! 
कहकर ‘रानी हे ! पतन हुआ, मेरा व्रत नष्ट हुआ’ प्रियतम !
इतना-सा तब कहना-‘जाकर जगजननी से पूछो’ प्रियतम॥७४॥

दूँगी मैं बता दिखा बातें आगेकी, पीछेकी प्रियतम ! 
प्रेरित मत किंतु, भला, करना, वे कहें पुनः उनको, प्रियतम ! 
सुख की प्रतिपल नवीन लहरें प्लावित तेरे, नृप के, प्रियतम ! 
प्राणों को नित्य करें सच है वाणी त्रिकाल मेरी” प्रियतम॥७५॥

इतने में दृश्य तिरोहित यह हो गया, जगीं रानी, प्रियतम ! 
अर्चन में योग न दे पायीं, उसदिन पगली-सी थीं, प्रियतम ! 
था प्रथम पहर जब बीत गया उसदिन की रजनी का, प्रियतम !
रानी-नृप शयन-भवनमें थे हो भावमग्न बैठे, प्रियतम॥७६॥

राजा के तनके कण-कण में ऐसी थी ज्योति भरी, प्रियतम !
वाणी क्या जिसे कहे, मन भी छू पाया नहीं कभी, प्रियतम !
थे नयन निमीलित-उन्मीलित रह-रहकर हो जाते, प्रियतम !
प्राणों में उनके सम्वेदन कैसा था, तुम जानो, प्रियतम॥७७॥

दक्षिण कर रानी के उरपर, सिर पर कर वाम तथा, प्रियतम ! 
भावाभिभूत नृपने जैसे था रखा यन्त्रवत् ही, प्रियतम ! 
संक्रमित उसी क्षण तेजपुञ्ज रानी के अङ्गों में, प्रियतम ! 
हो गया, तुरन्त सिमटकर फिर उदरस्थल में जागा, प्रियतम॥७८॥

संज्ञाविहीन अवनीश हुए रानी की गोदी में, प्रियतम !
थे पड़े तीस पल तक, जगकर वैसे ही फिर रोये, प्रियतम ! 
उन महिमामयी जगत्रय की जननी ने तब उनको, प्रियतम !
दिखला दी भूत-भविष्यत् की घटना, वे मुग्ध हुए, प्रियतम॥७९॥

उसका ही था परिणाम, नृपति थे अकस्मात् आये, प्रियतम ! 
जाया-जन्मस्थल में स्वागत करने के लिये अहा ! प्रियतम !
असमोर्ध्व महामहिमामय के प्राणों की देवी का, प्रियतम ! 
बेटी हो उनकी प्रगट अभी होनेवाली जो थीं, प्रियतम॥८०॥

केवल नृप नहीं, धराके जो मस्तकमणि मुनिगण थे, प्रियतम !
जो स्वर्लोकों के, भुवर्लोक, पन्नगतल तक के थे, प्रियतम !
प्रेरित हो अन्तर्यामी से दौड़े आये सब थे, प्रियतम !
जैसे थे प्रायः वैसे ही, कुछ रूप धरे भी थे, प्रियतम॥८१॥

थे तपन गगनमें चमक रहे, जन-सुखद अतीव बने, प्रियतम ! 
अवनी प्रतिपल ही थी धारण कर रही नयी सुषमा, प्रियतम ! 
वर्षाऋतु थी, पर सलिल वहाँ सर-सरित-निर्झरों का, प्रियतम ! 
दो घड़ी हुई, था बना अतुल उज्ज्वलतम मोती-सा, प्रियतम॥८२॥

शीतल-सुगन्ध-मन्थर समीर छू-छूकर के सबको, प्रियतम !
कानों में था कहता मानो,‘देखो ! धीरे-धीरे’, प्रियतम !
‘रसलहर एक-से-एक बड़ी इस भावसिन्धु में है, प्रियतम !
आनेवाली, तुम अवगाहन निरवधि करते रहना’ प्रियतम॥८३॥

थे अश्व किरणमाली-रथ के जब ठीक मध्य नभ में, प्रियतम !
आये, बस, उसी सन्धिपर थी आयी कन्या नृप की, प्रियतम ! 
मंगलमय परम जुड़े जब थे कालोचित योग सभी, प्रियतम !
रसराज और जब महाभाव दोनों थे एक हुए, प्रियतम॥८४॥

कोई न चितेरा हुआ यहाँ, आगे न कभी होगा, प्रियतम ! 
जो चित्र सलोनी नृप की उस बेटी का सही लिखे, प्रियतम ! 
लोचन जिनके हों तुम मेरे प्राणाधिक के पदकी, प्रियतम !
नख-चन्द्र-चन्द्रिका से भासित, वे देख भले ही लें, प्रियतम॥८५॥

दो बार अहो ! वह मुख-शोभा, फिर वह उमंगधारा, प्रियतम ! 
प्राणों में जो थी उमड़ चली, देखी जिनने उनके, प्रियतम ! 
एवं उसका प्रकाश बाहर कैसे था हुआ वहाँ, प्रियतम ! 
निर्लज्ज हुई उस ओर, भला, किञ्चित् कह आयी हूँ, प्रियतम॥८६॥

अब तो इतना-सा कहूँ, अहा ! उन दिव्य अतिथियों ने, प्रियतम ! 
रानी ने, बहिनों ने, अगणित चर-अचर लोचनों ने, प्रियतम ! 
कन्या को, रस के प्लावन को देखा, बस, देखा था, प्रियतम !
था काल मकर, रानी लौटीं पीहर से ले पुत्री, प्रियतम॥८७॥

अब गये पचीस महीने, शुभ दिन सात, अष्टमीसे, प्रियतम ! 
प्रातः से लेकर जब नूतन होता प्रभात फिर था, प्रियतम !
उन आठों पहरों में प्रतिपल नृप-नगरों में जो थीं, प्रियतम !
भावों की नव तरंग उठती, संभव है क्या कहना, प्रियतम॥८८॥

जो हो, इतने दिन की जब वह हो चुकी लाडिली थी, प्रियतम !
थे महीपाल के प्राणोपम जो एक धर्म भाई, प्रियतम !
‘गोपेश’ अहो ! जिनकी पदवी विख्यात भुवन में थी, प्रियतम !
हो रहा शरद्पूनों का था उत्सव उनके गृह में, प्रियतम॥८९॥

जिस दिन वह नृपति-तनूजा थी अवनीतल पर आयी, प्रियतम !
उसके ही पंद्रह दिवस ठीक पहले उस रजनी में, प्रियतम ! 
उन गोपवर्य को महामहिम ऐसा था पुत्र हुआ, प्रियतम !
जो था अहीर-कुल-उजियारा, सबके दृग का तारा, प्रियतम॥९०॥

तबसे उन धर्म भाइयों ने निश्चय था किया यही, प्रियतम ! 
ये शरद्, बसन्त, सभी ऋतु में होते उत्सव जो हैं, प्रियतम ! 
आगे अब हम सर्वदा करें दोनों कुल मिलकर ही, प्रियतम ! 
वे भले वनस्थलमें हों या नृपभवन किसी में हों, प्रियतम॥९१॥

इसलिये नृपति थे सपरिवार आये अहीरपुर में, प्रियतम !
आयी थी प्रजा और तो क्या, दस दिन वय का शिशु भी, प्रियतम ! 
मानो नृपपुर उठ आया था पूरा-का-पूरा ही, प्रियतम ! 
उन गोप-नगर-नर-नारी का उत्साह निराला था, प्रियतम॥९२॥

गोपेश और अवनीश अभी नारायण विग्रह का, प्रियतम !
चौंसठ उपचारों से अर्चन करके कृतकृत्य हुए, प्रियतम ! 
उद्दाम नृत्य के सहित अहो ! थे नाम गान करते, प्रियतम !
स्वर में स्वर सभी मिलाकर थे वैसे ही पुरवासी, प्रियतम॥९३॥

बीती ही थी वह अर्धनिशा, पल पाँच हुए, बस, थे, प्रियतम ! 
गोपेशपुत्र को ले आयीं रानीकी बहिन वहाँ, प्रियतम !
चञ्चल बालक वह उतर पड़ा जल्दी से गोदी से, प्रियतम ! 
भयहीन सदा वह था, झटसे घुस पड़ा भीड़ में, हे प्रियतम॥९४॥

वह नृपतिपुत्रको ‘श्रीभैया’ सम्बोधित था करता, प्रियतम ! 
गोपेश-वसन को खींच चपल कर से, हँसकर बोला, प्रियतम ! 
‘बाबा ! भेजा है मैया ने मुझको, तुमसे कह दूँ, प्रियतम ! 
श्रीभैया को है एक हुई छोटी फिर बहिन अभी’ प्रियतम॥९५॥

उस बालक की वाणी में था टोना-सा भरा सदा, प्रियतम !
वह भाव-समाधि अहो ! सबकी टूटी निमेष में ही, प्रियतम !
नारायण का वह शारदीय उत्सव उन नरपति की, प्रियतम !
कन्या की महा बधाई में परिणत हो गया वहाँ, प्रियतम॥९६॥

इस भाँति महारानी क्षण में मानो हों घटी अभी, प्रियतम !
इन उपर्युक्त घटनाओं को थीं देख गयी फिर से, प्रियतम !
‘मैया ! क्या है तू सोच रही’, कहकर जब पुत्री ने, प्रियतम !
उनके अञ्चल को खींचा था, टूटा तब सच, सपना, प्रियतम॥९७॥

पुत्री के अधर-कपोलों पर वत्सलता के रस से, प्रियतम ! 
पूरित वह चिह्न अनेक बार अङ्कित कर फिर अपनी, प्रियतम !
छोटी बेटी को, सखियों को, जो वहाँ बड़ी की थीं, प्रियतम !
वैसे ही रस देकर, लेकर सबको थीं वे आयीं, प्रियतम॥९८॥

अर्चन-मन्दिर में राजा थे ध्यानस्थ हुए बैठे, प्रियतम !
रानी ने बतला दी उनको दुहिता की जो रुचि थी, प्रियतम !
झर-झरकर लगे नयन बहने, नरपाल निहाल हुए, प्रियतम !
मानसतल में वह बात जगी देवी की कही हुई, प्रियतम॥९९॥

‘होकर जब सात वर्ष की यह हँसकर इच्छा कर ले, प्रियतम !
मेरे वन में आने की, तब समझो, यह खेलेगी, प्रियतम ! 
वह खेल अनन्तकालतक जो त्रिभुवन थिर-जङ्गम को, प्रियतम ! 
पावनतर, पावनतम कर-कर, निधि नित्य बने सबकी’, प्रियतम॥१००॥

गद्गद् थी गिरा, नृपति ने थी दी अनुमति जाने की, प्रियतम ! 
सबको भूषण परिधानों से रानी ने सजा दिया, प्रियतम ! 
वे चलीं तुरन्त उसी वन में प्रसरित सच हो जैसे, प्रियतम ! 
हो तरल पुराण नित्य कवि के नव मन की सुन्दरता, प्रियतम॥१०१॥

''',
      ),
      BookPage(
        title: 'द्वितीय शतक',
        content: '''पूरब की शिखरावलि-मण्डित गिरि था सीमा रचता, प्रियतम ! 
कानन से जुड़ी प्रतीची में प्रसरित नीली सरिता, प्रियतम ! 
सुविशाल राजपथ उत्तर में द्रुमजालों से छाया, प्रियतम ! 
चलकर कोसों तक छू लेता उस शैल रत्नमय को, प्रियतम॥१०२॥

निर्झर झरकर पर्वतसे लघु था स्रोत एक बहता, प्रियतम !
चञ्चल-सा संगम था उसका श्यामा तरंगिणी से, प्रियतम ! 
उस वन के दक्षिण में रहकर कल-कल करता, हँसता, प्रियतम ! 
पावस में भी उसकी धारा मुक्ता बिखेरती थी, प्रियतम॥१०३॥

पगडंडी सभी दिशाओं में सीधी-टेढ़ी जाती, प्रियतम !
रमणीय तृणों से, गुल्मों से हो जाती लुप्त कहीं, प्रियतम !
सौरभ के दानी पुष्पों से लोभित होकर भौंरा, प्रियतम !
गा-गाकर था उड़ता, करता गुञ्जित अरण्य को, हे प्रियतम॥१०४॥ 

पक्षी-समूह का कलरव था संकेतदान करता, प्रियतम !
काननवासिनी तरुणियों को रसपाठ पढ़ाता था, प्रियतम !
जीवन की धारा किधर मुड़े, भावी क्या है किसकी, प्रियतम ! 
सच्चा प्रतीक इसका वह था, आदर वे सब करतीं, प्रियतम॥१०५॥

उस वनके किसी चतुष्पद में हिंसा की वृत्ति न थी, प्रियतम ! 
दिन-रात परस्पर निर्भय वे सुखसे घूमा करते, प्रियतम ! 
उनमें मुनियों की दृष्टि अहो ! थी स्वतः उतर आयी, प्रियतम ! 
मानो एकात्म भाव मन में वे लिये हुए सब थे, प्रियतम॥१०६॥

जो दरी एक-से-एक बढ़ी शोभा में गिरि की थी, प्रियतम !
उसमें वे जब करने लगते विश्राम आँख मूँदे, प्रियतम !
उनकी नीरवता अचपलता संचारित कर देती, प्रियतम !
पूरी अटवी के प्राणों में मुद्रा समाधि-जैसी, प्रियतम॥१०७॥

उस ओर शैल के कण-कणमें मानो चेतनता थी, प्रियतम !
वह खड़ा सतत देखा करता ऊँचा सिर किये हुए, प्रियतम ! 
क्या है उस वन में, कहाँ किसे क्या आवश्यकता है, प्रियतम ! 
फिर वहीं खड़े रहकर ही वह सबको सँभाल लेता, प्रियतम॥१०८॥

अक्षत तो एक ओर रहती वह वीरवधूटी भी, प्रियतम !
फिर भी था यथासमय देता सबको आहार भला, प्रियतम ! 
जिसकी जिसपर चलती रुचि थी, उसके समीप रखता, प्रियतम !
उसका इच्छित फल और उसे सुख से वह भर देता, प्रियतम॥१०९॥

वह करे प्रौढ़ जनगण का ही आदर, यह बात नहीं, प्रियतम ! 
शिशुतक को नीलम, लाल और पुखराज राशि देता, प्रियतम ! 
समता, धीरता, प्यार-वितरण निरुपम था शैल लिये, प्रियतम ! 
उसके दृग में ही आँख मिला वन का वह चित्र लिखूँ, प्रियतम॥ ११०॥

ललिता कुञ्जका वर्णन –
तरुसे रूठी-सी लता जहाँ अवनीपर थी फूली, प्रियतम ! 
द्रुम कर-पल्लव से छू उसकी बाँहें, झुककर कहता, प्रियतम ! 
प्रेमिल आँखों का ही भ्रम है, थी छाया ही उरमें, प्रियतम ! 
इन शशि-सुमनावलि की झलमल रह-रहकर जो करती,प्रियतम॥१११॥A
यत्र उज्ज्वल सत्त्वमयी अमृता निम्बं समाश्लिष्य प्रसरति॥११२॥B
वटं शंखालु इत्याख्या वल्लरी।॥११३॥D
करीराणां मूलदेशे श्यामाकतृणराशिः।॥११४॥E
कामिनी प्रजापति की क्रीड़ा वनदेवी से कहती, प्रियतम ! 
रजनीगन्धा अपना अनुभव शुचि गन्धवाह से, हे प्रियतम ! 
थी बात कुमुदिनी बतलाती हिमकर से उस अलि की, प्रियतम ! 
जो मत्त हुआ बँधकर सुख से था सुप्त कोष में, हे प्रियतम॥११५॥G
सूर्यमुखी स्वात्मवृत्तं अंशुमालिनं प्रति विज्ञापयति॥११६॥AA
अमला प्रवाहिणी म्लान एक पति को थी खोज रही, प्रियतम ! 
जब मिला नहीं, तब वह दीना पीछेकी ओर मुड़ी, प्रियतम ! 
पर दरी महीधर की बोली- 'री ! यहाँ कृष्णवर्णा’, प्रियतम ! 
दूती है तुमको जोह रही', जामिली अतः उससे, प्रियतम॥११७॥BB
चन्दनादिनवतरुनिर्मितनवनिकुञ्जवलि।॥११८॥DD
पनसादिदशवृक्षैर्विरचितदशकुञ्जपंक्तिः।॥११९॥GG
यत्र कालरूपो रविरपि कल्पद्रुमस्य छायायां प्रतिष्ठितायाः देवी प्रतिमायाः पादपीठं उपाश्रितो वर्तते।॥१२०॥A
तस्य उज्ज्वलनीलमणिवत् प्रकाशदानम्।॥१२१॥BB
श्रीफलकुञ्जं प्रति प्रदक्षिणत्वाचरणं च।॥१२२॥D
विशाखा कुञ्जका वर्णनः -
कुसुमित कचनार, अगस्त्य तथा सहिजन, अशोक के, हे प्रियतम !
गुच्छों से थे सुन्दर उरोज भूषित थल-पद्मा के, प्रियतम !
धरणी के वक्षःस्थल पर था वह पारिजात लिखता, प्रियतम !
कुछ चित्र विचित्र मनोहर, विधु था देख मुग्ध जिसको, प्रियतम॥१२३॥
यत्र वृक्षाणां निसर्गतः एव वल्लीदासत्वाचरणम्॥१२४॥
आम्रनिकुञ्जावलिः।॥१२५॥
बीजपूरकुञ्जपंक्तिः।॥१२६॥
कदलीवनम्।॥१२७॥
दाड़िमनिकुञ्जावलिः।॥१२८॥
कन्दुक क्रीड़ास्थली।॥१२९॥
मणिमयविश्रामगृहं।॥१३०॥
चित्रा कुञ्जका वर्णन -
लजवन्ती करती थी छिपकर अभिसार तरणि रहते, प्रियतम !
मधुपावलि का उड़ना लखकर थी भ्रमित हुई उससे, प्रियतम ! 
हैं एक नहीं, शत लक्ष बने मेरे प्राणाधिक वे, प्रियतम !
मूँदी उसने जब आँख, लगा, वे छोड़ गये मुझको, प्रियतम॥१३१॥
शतपत्रवनम्।॥१३२॥
तुलसीकाननम्।॥१३३॥
दूर्वाक्षेत्रम्।॥१३४॥
पूगपंक्तिः।॥१३५॥
तालावलिः।॥१३६॥
खर्जूरश्रेणी।॥१३७॥
कर्णिकारवनम्।॥१३८॥
इन्दुलेखा कुञ्जका वर्णन –
उन कुन्द बहिन के गालों पर थे कण न ओस के वे, प्रियतम !
मैं अङ्ग सजाकर यह अपना ठगती हूँ अपने को, प्रियतम !
वे आयेंगे, है सपना ही, यह टूटेगा क्षणमें, प्रियतम !
‘है प्रेम दम्भ मेरा’, वह थी इस चिन्ता से रोती, प्रियतम॥१३९॥
आम्रातकावलिः।॥१४०॥
तिन्तिड़ीवनम्।॥१४१॥
करौंदाइत्याख्याद्रुमाः।॥१४२॥
दमनकवनम्।॥१४३॥
वैजयन्तीकाननम्।॥१४४॥
शिंशपाश्रेणीः।॥१४५॥
उत्पलवनम्।॥१४६॥

चम्पकलता कुञ्जका वर्णन –
चम्पा पीले फूलों की थी साड़ी पहने गाती, प्रियतम !
वह राग, सुना था नहीं वहाँ जो कभी किसीने भी, प्रियतम !
मोहिनी शक्ति उसमें अवश्य कुछ भरी अनोखी थी, प्रियतम !
प्रणयी मिलिन्द् था एक हुआ मिटकर विधान विधि का, प्रियतम॥१४७॥
मधुकपंक्तिः।॥१४८॥
गन्धराजवनम्।॥१४९॥
किंशुकश्रेणी।॥१५०॥
इंगुदनिकुञ्जावलिः।॥१५१॥
पाटलजम्बुद्रुमाः।॥१५२॥
मन्दारावलिः।॥१५३॥
बर्बरीवनम्।॥१५४॥

रंगदेवी कुञ्जका वर्णन -
थी रंग-बिरंगे वर्णों में मल्लिका खिली ऐसी, प्रियतम !
जो लुप्त बुद्धि कर देती थी नभ में उड़ते मुनि की, प्रियतम !
उनकी तो बात दूर, मोहित पालक वह था उनका, प्रियतम !
ऐसा कि आजतक हाल नहीं कोई बतला पाया, प्रियतम॥१५५॥
शमीसमूहः।॥१५६॥
आमलकद्रुमाः।॥१५७॥
अर्कवनम्।॥१५८॥
नीपपंक्तिः।॥१५९॥
शिरीषश्रेणी।॥१६०॥
कपित्थकुञ्जावलिः।॥१६१॥
जम्बीरवनम्।॥१६२॥

तुङ्गविद्या कुञ्जका वर्णन—
मालती-लता सद्यों पर थी फूली इठलाती-सी, प्रियतम !
सुनकर समीर की साँय-साँय उत्कण्ठित थी होती, प्रियतम !
वे ही होंगे, प्यारा जब पर था नहीं दीखता, हे प्रियतम !
वह बात झूमकर यूथी से करती रह-रहकर थी, प्रियतम॥१६३॥
अश्वत्थश्रेणी।॥१६४॥
प्लक्षवनम्।॥१६५॥
तगरइत्याख्यद्रुमाः।॥१६६॥
सालावलिः।॥१६७॥
देवदारुवनम्।॥१६८॥
भूर्जवनम्।॥१६९॥
जालकावलिः।॥१७०॥

सुदेवी कुञ्जका वर्णन -
थी जपा खड़ी अवनत-मुख हो, आँखों में थी लाली, प्रियतम !
था पास खड़ा नीला तमाल दीनता-व्यथा कहता, प्रियतम !
पुरवैया से परिचालित हो, वह पुनः-पुनः झुकता, प्रियतम !
जाती थी पश्चिम में पर, वह संध्या होते रोती, प्रियतम॥१७१॥
उदुम्बरपंक्तिः।॥१७२॥
बदरीवनम्।॥१७३॥
वानीरनिकुञ्जावलिः।॥१७४॥
वेणुवनम्।॥१७५॥
अर्जुनसमूहः।॥१७६॥
यत्र अशेषोद्भिज्जजातीयप्राणिनां सन्निवेशः।॥१७७॥
यथावसरं यथास्थानं आविर्भावः तिरोभावश्च।॥१७८॥

राधा कुण्डका वर्णन - 
लहरें सर में धारा सी थीं क्रमशः उठती-गिरती, प्रियतम ! 
चञ्चल मराल होकर उनसे भामिनी मराली से, प्रियतम ! 
कहता- ‘प्यारी ! देखो, ये हैं दे रही पाद्य तुमको, प्रियतम ! 
फिर अर्घ्य-आचमन भी, पूजा स्वीकार करो इनकी, प्रियतम॥१७९॥

अपने प्राणों के रस से ये तुमको नहलाती हैं, प्रियतम !
अपने प्राणों की सत्ता का परिधान धराती हैं, प्रियतम !
चारों कूलों के द्रुम से जो हैं गुच्छ सुमन आते, प्रियतम !
इनमें उनका ही आभूषण तुमको पहनाती हैं, प्रियतम॥१८०॥

उरपर बिखरे पराग की हैं अर्पित सुगन्ध करती, प्रियतम !
उरपर विकसित सरोज लेकर ये फूल चढ़ाती हैं, प्रियतम !
अतिशय उमंग की किरणों से आकर्षित हो, इनका, प्रियतम ! 
उर भाप-सदृश उड़कर जो है बनता है धूप वही, प्रियतम॥१८१॥

इनके भीतर दिन में जो हैं दिनकर की परछाँही, प्रियतम !
रजनी में तारक-शशधर की, वे ही हैं दीप भला, प्रियतम ! 
हृत्पद्मकर्णिका के भीतर उज्ज्वलरस-वर्ण लिये, प्रियतम !
जो वस्तु सुसञ्चित है, उससे नैवेद्य निवेदन है, प्रियतम॥१८२॥
उज्ज्वल जल लेकर पुनः अहो ! आचमन कराती हैं, प्रियतम !
उन अरुण उत्पलों के दल से रचती तमोल ये हैं, प्रियतम !
उज्ज्वलरस नित्य उरस्थल का है तर्पणीय उनका, प्रियतम !
जो रागभरा स्वर है उरका, मधुरस्तव है इनका, प्रियतम॥१८३॥

अपने स्वरूप में नित्य अहो ! ये सभी दिशाओं में, प्रियतम ! 
जो घूम रही हैं, इनका शत वह है प्रणाम ही तो' प्रियतम ! 
इनके रहस्यमय अर्चन के उपचार मनोहर हैं, प्रियतम ! 
यों था प्रतिदिन वरटानायक मनुहार-गीत गाता, प्रियतम॥१८४॥

सुनकर यह गीत भामिनी थी उसकी विमुग्ध होती, प्रियतम ! 
देकर अपनी नीरव सम्मति नायक पर झुक पड़ती, प्रियतम ! 
दोनों ही कण्ठ मिलाकर थे लहरों में धँस पड़ते, प्रियतम ! 
आनन्दमत्त होकर लहरें कूलों से टकरातीं, प्रियतम॥१८५॥

भीतर-ही-भीतर उनके थे दोनों चलते रहते, प्रियतम ! 
ले टोह, नीर-बिहगी-दल था ऊपर-ऊपर चलता, प्रियतम ! 
वह दाँव-पेंच दोनों दल में सुन्दर जो चल पड़ता, प्रियतम ! 
उसके चित्रण की तूली वह जा पड़ी नीलसर में, प्रियतम॥१८६॥

कृष्णकुण्ड का वर्णन-
था श्यामनीर से भरा एक गम्भीर सरोवर, हे प्रियतम ! 
पा सका न कोई थाह, थके करके प्रयास योगी, प्रियतम ! 
जो श्वास रोक सकते थे युग-युग तक बूड़े उसमें, प्रियतम ! 
वे भी हारे, निकले उदास, इतना अगाध जल था, प्रियतम॥१८७॥
वह पुञ्ज समग्र ईशता का जो, धर्म और यश का, प्रियतम ! 
श्री-ज्ञान-विराग-सत्य का है उसके कण-कण में था, प्रियतम ! 
उसके जल से वल्लरियाँ थीं वन की सींची जाती, प्रियतम ! 
लगते थे फूल और उनमें निरुपम सौरभ वाले, प्रियतम॥१८८॥

उसका जल छूते ही तन का सब रंग बदल जाता, प्रियतम ! 
पीनेवाली कण एक इतर सब राग भूल जाती, प्रियतम ! 
उसको निहारते ही आँखें होती थीं श्याममयी, प्रियतम ! 
जो भी फिर कहीं कभी दीखे, नीला-नीला लगता, प्रियतम॥१८९॥

जिसके कानों में भी उसकी चर्चा थी पड़ जाती, प्रियतम ! 
उसको उसके अतिरिक्त बात कोई न सुहाती थी, प्रियतम !
लेकर समीर सौरभ उसका जाता था जहाँ-जहाँ, प्रियतम ! 
सब जीव वहाँ के उसपर थे न्योछावर हो जाते, प्रियतम॥१९०॥

निर्माण पीतमणि से उसके चारों कूलों का था, प्रियतम !
प्रतिदिन जल बढ़ धारा बनकर था चार बार बहता, प्रियतम !
पहले उत्तर की ओर वेग उसका ऐसा होता, प्रियतम ! 
मानो श्रीफल की कुञ्जों को खण्डित कर छोडेगा, प्रियतम॥१९१॥

पूरबमें, अग्निकोणमें फिर चलता प्रवाह जब था, प्रियतम ! 
होती उसकी गति यों, जैसे जाता हो सुख देने, प्रियतम ! 
कोई आयी हो दिनमें ही करके अभिसार, उसे, प्रियतम ! 
या उधर बिलखती हो कोई प्रोषितपतिका, उसको, प्रियतम॥१९२॥

दक्षिण में जब चलता, लगता, कोई मधूक-मधु पी, प्रियतम ! 
अपने तन का सब भान भुला, चल रहा भटकता हो, प्रियतम ! 
टकराकर उन-उन तरुओं से किञ्चित् रुक-सा जाता, प्रियतम ! 
अन्तश्चेतनावृत्ति फिर भी पथ थी दिखला देती, प्रियतम॥१९३॥

पश्चिम में बढ़ते ही होता अतिशय बेहाल भला, प्रियतम ! 
पीले मणियों की किरणें थीं उसको समझाती-सी, प्रियतम ! 
‘मैं तो उरमें ही हूँ’ धीरज आता न किंतु तब भी, प्रियतम ! 
यों घूम-घूम वन में भरता पल-पल नव-नव सुषमा, प्रियतम॥१९४॥

सूर्यकुण्ड का वर्णन-
थे मूर्त हुए अन्यत्र वहाँ वे पुनः किरणमाली, प्रियतम ! 
हीरकमय विग्रह बनकर थे पूजित अरण्य जन से, प्रियतम ! 
मन्दिर के आगे कुण्ड एक था भरा हुआ जल से, प्रियतम ! 
विकसित-सरोज से बना रम्य रहता सब ऋतुओं में, प्रियतम॥१९५॥

ऐसे कुछ कौशलसे रचना मन्दिर की थी जिससे, प्रियतम ! 
होतीं उपलब्ध सदा ऋतुएँ सब उसके कक्षों में, प्रियतम ! 
एवं कोई भी क्यों न भला कितना ही सजग रहे, प्रियतम ! 
आते ही कोई मोड़, उसे दिग्भ्रम हो ही जाता, प्रियतम॥१९६॥

रवि-विग्रह की विशेषता यह सबको लक्षित होती, प्रियतम ! 
प्रतिदिन जबतक दिनकर नभ में ऊपर उठते रहते, प्रियतम ! 
तबतक पुखराजराशि उसके नख से झरती रहती, प्रियतम ! 
ज्यों ढले उधर वे, रत्न इधर पानी बनने लगते, प्रियतम॥१९७॥
आराधन के भी समय तथा यह चमत्कार होता, प्रियतम ! 
अर्चक के प्राण-देह-मन थे तेजोमय बन जाते, प्रियतम ! 
सत्ता उतने क्षण बच रहती उस तूर्य नित्य रस की, प्रियतम ! 
पूजा जिसने-जिसने की थी, सबका अनुभव यह था, प्रियतम॥१९८॥

जावटग्रामका वर्णन 
छोटा-सा ग्राम एक अद्भुत कासार-तीर पर था, प्रियतम ! 
थे रत्नजटित सब गृह उसमें बसनेवालों के, हे प्रियतम !
देवी के कृपापात्र वे थे, निर्भय थे सभी सदा, प्रियतम !
राजा-सा जीवन था उनका, पर शीलवान वे थे, प्रियतम॥१९९॥ 

जो सिद्धि पवित्र तन्त्र एवं मन्त्रों से मिलती है, प्रियतम ! 
भूषित उससे प्रायः तरुणी थीं सभी गाँववाली, प्रियतम ! 
जीवनभर का यह किन्तु अहो ! उनके व्रत निश्चल था, प्रियतम ! 
मैं कभी स्वसुख के लिये नहीं उपयोग करूँ इसका, प्रियतम॥२००॥

ऐसी थी प्रीति परस्पर जो, वे एक दूसरी के, प्रियतम !
सुख के निमित्त मर मिटने को प्रस्तुत हरदम रहतीं, प्रियतम ! 
सबके ही प्राण सभीमें, सच, रहते थे स्यूत हुए, प्रियतम ! 
अन्यत्र न था वह सखीपना, है नहीं, न होगा ही, प्रियतम॥२०१॥

कानन की उन कुञ्जों में वे दिन में घूमा करतीं, प्रियतम !
नीली-सरिता-तट पर उनका रजनी-बिहार होता, प्रियतम !
ऐसी माया थी देवी की, कोई न जान पाता, प्रियतम ! 
है गाँव-सरोवर किधर कहाँ, वे नाम धरे क्या हैं, प्रियतम॥२०२॥
''',
      ),
      BookPage(
        title: 'तृतीय शतक',
        content: '''मन्थरगति से चलती, हँसती आयी नृप की पुत्री, प्रियतम !
सोने की पुतली-सी, सब थीं घेरे सहचरियाँ, हे प्रियतम ! 
किरणें बिखेर सुन्दरता की, सब ओर खड़ी वह थी, प्रियतम ! 
वन के समक्ष उत्तर मुख हो, भोली चितवनवाली, प्रियतम॥२०३॥

थे गाल-भालपर रहे व्यक्त हो श्रमकण मोती-से, प्रियतम !
शीतल बयार झुर-झुर करती थी व्यस्त पोंछने में, प्रियतम !
मखमल-सी कोमल दूब हरी लहराती थी हिलती, प्रियतम !
मनुहार धरा मानो करती, ‘री ! नेक बैठ जा तू’, प्रियतम॥२०४॥

थी त्वरा नृपतिकन्या में पर, कैसे विश्राम करे, प्रियतम !
आकर्षित था करता वह वन कमनीय दूर से ही, प्रियतम ! 
तितली सी उड़ती जा पहुँची भीतर वह सीमा के, प्रियतम ! 
मिंहदी  की झाड़ी के पथ से उन सबको साथ लिये, प्रियतम॥२०५॥

शुभ शकुन बताते खञ्जन को पहले उसने देखा, प्रियतम ! 
जो सबसे अधिक सयानी थी सखियों में, वह बोली, प्रियतम ! 
‘अप्रतिम यहाँ कोई मंगल निश्चय होगा, सखि री’, प्रियतम ! 
मनमें नृपकन्या के इससे उत्कण्ठा और बढ़ी, प्रियतम॥२०६॥ 

इतने में उड़ आया कपोत अभिनन्दन करने, हे प्रियतम ! 
वह कण्ठ फुलाकर लगा नृत्य अपना दिखलाने, हे प्रियतम !
‘पीहू’ करके आया मयूर, उसने तानी छतरी, प्रियतम ! 
सुन्दर अत्यन्त एक शुक था, प्रणिपात किया उसने, प्रियतम॥२०७॥

आया वह नीलकण्ठ, अपनी ग्रीवा नीची करके, प्रियतम ! 
मुख नृपदुहिता की ओर किये चल पड़ा गुड़क करके, प्रियतम ! 
आयी बट-तीतर की टोली, रचना कर मण्डल की, प्रियतम ! 
आगत उन सभी अतिथियों की करती प्रदक्षिणा थी, प्रियतम॥२०८॥

वे रंग-बिरंगे कितने थे क्रमशः विहङ्ग आये, प्रियतम ! 
उनकी गणना करके कैसे, क्या बतलाऊँ तुमको, प्रियतम ! 
नानापन अहो ! प्रकृति में जो है, नित्य सृष्ट होता, प्रियतम ! 
मानो वह सभी विहग बनकर आया स्वागत करने, प्रियतम॥२०९॥

हँस-हँसकर नृपतिनन्दिनी थी उनको निहार लेती, प्रियतम ! 
कहती सहेलियों से फिर थी, ‘री ! क्या दूँ मैं इनको, प्रियतम ! 
जो प्यार लिये ये आये हैं, वह इनकी ही निधि है, प्रियतम ! 
मेरा भी रोम-रोम इनपर, है न्योछावर अब तो, प्रियतम॥२१०॥

भाषा मैं नहीं जानती हूँ इनकी, क्या बात करूँ, प्रियतम ! 
कोई तुममें से भले मुझे बतलाओ तनिक कला’, प्रियतम ! 
इतना कहते ही कीर वही उड़कर सम्मुख आया, प्रियतम ! 
सुस्पष्ट मानवी-सी सुमधुर बोली में बोल उठा, प्रियतम॥२११॥

‘तुम कहो, राजनन्दिनि ! जो भी चाहो कहना हमसे, प्रियतम ! 
हम तो निहाल सब होंगे ही, भर सुधा श्रवणपुट में, प्रियतम ! 
अविछिन्न काल से सुखमय यह वनवास हमारा है, प्रियतम ! 
कानों में भरा अमिय-रस यह सागर बन उमड़ेगा’, प्रियतम॥२१२॥

विस्मयसे कुछ पल नृपपुत्री अपलक चुपचाप रही, प्रियतम ! 
देखा फिर बड़ी सहेली को, अद्भुत उस तोते को, प्रियतम !
कुछ सोच सखी बोली- ‘शुक है प्रतिपालित कहीं हुआ, प्रियतम ! 
अनुकरणशील यह जाति सदा खग की होती ही है’, प्रियतम॥२१३॥

उत्तर से नृपति-तनूजा को सन्तोष न किंतु हुआ, प्रियतम ! 
बोली, ‘री ! फिर इसने कैसे मेरा परिचय जाना, प्रियतम !
तू पता लगा किसके घर यह है पला और इसकी, प्रियतम ! 
प्रतिभा स्वभावगत है या यह है रटी हुई विद्या’, प्रियतम॥२१४॥

सहचरी सोचती रही, कीर फिरसे वह बोल उठा, प्रियतम ! 
अवनी को अरुण चञ्चु से छू, दृग घुमा-घुमा रस से, प्रियतम ! 
‘हे राजकुमारी ! नित्य दास-दासी हैं हम उनके, प्रियतम ! 
कालिमा-गौरपननिरुपम है निरवधि तनमें जिनके, प्रियतम॥२१५॥

जब जितना हमें पढ़ाते हैं वे, तब उतना-सा ही, प्रियतम !
होता है ज्ञान उदय, हम तो हैं यन्त्र सभी उनके, प्रियतम !
यह देवि ! पाँवड़ा बिछा हुआ दृग का है स्वागत में, प्रियतम ! 
हैं भाग बड़े हम सबके, जो तुम यहाँ पधारी हो’, प्रियतम॥२१६॥

अब रही न विस्मय की सीमा, राजा की बेटी के, प्रियतम ! 
शुक को निहारकर पुनः पुनः उत्तरकी ओर बढ़ी, प्रियतम !
प्राकृतिक, एक-से-एक बड़ा रमणीय दृश्य आता, प्रियतम ! 
आँखें उसकी टिक जाती थीं, रह-रहकर वह रुकती, प्रियतम॥२१७॥

बाहर-बाहर से इस वन की जिनने दी थी फेरी, प्रियतम !
उनका वर्णन सुन्दरता का इसकी, शतगुणित हुआ, प्रियतम !
उस राजकुमारी के मनमें अब था पछतावा-सा, प्रियतम !
खेली मैं और-और वनमें, क्यों यहाँ नहीं आयी, प्रियतम॥२१८॥

सुकुमारी अब वह थकी हुई दीखी सहचरियों को, प्रियतम ! 
चलती-चलती अविराम फँसी बातों में, शोभा में, प्रियतम ! 
कर सकीं उसे यद्यपि सखियाँ सम्मत कठिनाई से, प्रियतम ! 
आकर पर वह फिर बैठ गयी वट-तरु की छाया में, प्रियतम॥२१९॥

था शुक भी साथ-साथ आया, डाली पर जा बैठा, प्रियतम ! 
बतलाने लगा रहस्यभरा वह मानचित्र वन का प्रियतम !
क्या-क्या वस्तुएँ अवश्य यहाँ हैं दर्शनीय इसका, प्रियतम !
नृपपुत्री के समक्ष वर्णन आकर्षक कर बैठा, प्रियतम॥२२०॥

सुन रही ध्यान देकर वह थी प्रत्येक बात शुक की, प्रियतम ! 
सुनते-सुनते तोते के प्रति बढ़ गयी प्रीति उसकी, प्रियतम ! 
बोली, ‘रे कीर ! बैठ जा तू आकर समीप मेरे, प्रियतम ! 
दोनों हाथों से छू-छूकर मैं प्यार करूँ तुझको’, प्रियतम॥२२१॥

पड़ते न पलक पड़ते तोता बड़भागी उड़ आया, प्रियतम ! 
कर-पल्लव पर आसीन हुआ, उस नृपतिनन्दिनी के, प्रियतम ! 
प्राणों के रस से वह उसको अभिषिक्त लगी करने, प्रियतम ! 
आँखें पल-पल शुक की मुँदतीं, मानो समाधि लगती, प्रियतम॥२२२॥

अनुजा सहोदरा दौड़ी, तरु था एक पास में ही, प्रियतम ! 
टप-टप कर चूते थे मीठे फल पके हुए उससे, प्रियतम ! 
अञ्जलि में भरकर ले आयी फल चार-पाँच पल में, प्रियतम ! 
दे दिया बहिन को, बहिन लगी रखने शुक के मुख में, प्रियतम॥२२३॥

इतना आदर पाकर बोला वह कीर नम्रता से, प्रियतम !
‘हे देवि ! चलो पथ दिखलाऊँ मैं इस वन का तुमको’, प्रियतम ! 
कोने-कोने से परिचित हूँ, इसमें ही रमा हुआ, प्रियतम ! 
स्वीकार करो अतिशय नगण्य सेवा तुम यह मेरी, प्रियतम॥२२४॥

पहले, महीपनन्दिनि ! चलकर इस वायुकोण-पथ से, प्रियतम ! 
देखो उस दिव्य सरोवर को, अनुपम सुमिष्ट जल है, प्रियतम ! 
प्रत्यक्ष महामाया की है, कुछ शक्ति भरी जल में, प्रियतम ! 
पीते ही आँख बदलकर हैं दर्शन विचित्र होते, प्रियतम॥२२५॥

फूले सरोज का चित्र नित्य है एक लिखा उसमें, प्रियतम ! 
है मध्यदेश में बिन्दु एक, नीले अरविन्दों का, प्रियतम ! 
उसको पिङ्गल नीरज निर्मित घेरे त्रिकोण फिर है, प्रियतम ! 
है अरुण कुञ्ज का अष्टकोण डाले उसपर घेरा, प्रियतम॥२२६॥

पीतारुण अरविन्दों के हैं दो फिर दशकोण बने, प्रियतम ! 
क्रमशः आकृति में बड़े, सतत नव-नव शोभावाले, प्रियतम !
उनको घेरे है एक बड़ा श्यामल सरोरुहों का, प्रियतम ! 
नव नित्य चतुर्दशकोण अहो ! सौरभ से भरा हुआ, प्रियतम॥२२७॥

स्वदलों की अनुकृति धरते, अब सित नवल अम्बुरुह के, प्रियतम !
हैं बने अष्टदल दिनकर की किरणें बिखेरते-से, प्रियतम ! 
उनको भी लिये हुए उरमें, उज्ज्वल कमलों के वे, प्रियतम ! 
सोलह दल हैं अदभुत, शशि की शोभा हरनेवाले, प्रियतम॥२२८॥

चतुरस्र मनोहर पद्मोंका विरचित है अब ऐसा, प्रियतम ! 
जो सात रंग पल-पल में है क्रमशः धारण करता, प्रियतम ! 
आँखें उससे जुड़ते ही यह विभ्रम-सा होता है, प्रियतम !
पावस,बसन्त ऋतु,शरद,शिशिर,आतप,हिम में क्या है,प्रियतम॥२२९॥ 

उस नील सरोज-बिन्दु पर जब पड़ती रवि-किरणें हैं, प्रियतम !
ऊपर से मध्य गगन से, तब घटती यह घटना है, प्रियतम !
भौंरे सब इस वन के तत्क्षण उड़कर आ जाते हैं, प्रियतम !
मिलकर असंख्य वे रचते हैं सुन्दर वितान काला, प्रियतम॥२३०॥

अचरज है, सब मँडराते हैं ऊपर वे नभ में ही, प्रियतम !
नीचे क्षणभर भी उतर नहीं आते फूलों पर हैं, प्रियतम ! 
यह तीस पलों का दृश्य अहो ! प्रतिदिन ही होता है, प्रियतम ! 
मध्याह्न बीतते ही फिर हैं, सब-के-सब उड़ जाते, प्रियतम॥२३१॥

ज्यों तथा उतरने लगता है यह तरणि अस्तगिरि में, प्रियतम ! 
‘गूँ-गूँ’ करता दक्षिण पथ से है एक मधुप आता, प्रियतम ! 
कुछ पल उन नलिनों की फेरी देकर ढल पड़ता है, प्रियतम ! 
पीले जलरुह के उर पर फिर रहता प्रभात तक है, प्रियतम॥२३२॥

हे राजतनूजे ! कह कहकर कैसे समझाऊँ मैं, प्रियतम ! 
कितना है चमत्कारकारी, प्रत्यक्ष इसे कर लो, प्रियतम !
देखो द्रुम-अवली कूलों की हिलती यह दीख रही, प्रियतम !
दो-ढाई सौ पद चलते ही तट पर पद रख दोगी', प्रियतम॥२३३॥

तोता इतना कहकर, उड़कर उस ओर लगा चलने, प्रियतम ! 
सखियों को लिये तुरंत चली अवनीशनन्दिनी भी, प्रियतम ! 
मिल गया पाँच पल में सर का तट अग्निकोण वाला, प्रियतम ! 
बातें सर्वथा सत्य निकलीं, जो कही कीर ने थीं, प्रियतम॥२३४॥

कम हो या अधिक, किंतु सबको लग गयी प्यास अब थी, प्रियतम ! 
था भरा स्वच्छ जल से पूरा कासार सामने ही, प्रियतम ! 
छू रहा नीर था पहली ही सीढ़ी के आधे को, प्रियतम !
अञ्जलि में जल भरकर सब वे पीने लग गयीं भला, प्रियतम॥२३५॥

दो घूँट कण्ठ के भीतर, बस, जाते ही उन सबके, प्रियतम ! 
हो गये प्राण शीतल, सुख में तन का कण-कण डूबा, प्रियतम ! 
आँखों में भरी और अभिनव रसमयी खुमारी-सी, प्रियतम ! 
निस्पन्दगात्र होकर सब वे ढल पड़ीं वहीं क्षण में, प्रियतम॥२३६॥

अनुभव अब राजनन्दिनी को होने लग गया वहाँ, प्रियतम ! 
मानो हूँ खड़ी अकेली मैं अनुजा को साथ लिये, प्रियतम ! 
बातें आगे-पीछे की थीं विस्मृत हो गयी सभी, प्रियतम ! 
आनन्दहिलोरों में बहकर सर को निहारती थी, प्रियतम॥२३७॥

बोली,‘री ! बहिन ! घूमकर अब पूरे सर को देखें’, प्रियतम ! 
पश्चिम की ओर चली, तट को पकड़े धीरे-धीरे, प्रियतम ! 
पद बीस-तीस ही चलने पर मिल गयी एक रमणी, प्रियतम ! 
गोरी, सुन्दरी अनोखी थी, यौवन से वह माती, प्रियतम॥२३८॥

यह कहा तथा उस रमणी ने उन नृपदुहिताओं से प्रियतम !
तुम चलो, पधारो मेरे घर, शशिमुखि ! न विलम्ब करो, प्रियतम ! 
अतिकाल हो चुका है, पहले किञ्चित् भोजन कर लो, प्रियतम ! 
मैं ही हूँ नित्य सेविका, इस वन की अधिदेवी की', प्रियतम॥२३९॥

फँसकर मीठे आकर्षण में दासी की वाणी के, प्रियतम !
पहुँचीं वे उसके घर पर जो पश्चिम सर-तट पर था, प्रियतम ! 
सुन्दर विशाल था, पद उसमें रखते ही दोनों को, प्रियतम ! 
ऐसा प्रतिभात हुआ, मानो अपना ही वह घर हो, प्रियतम॥२४०॥

छोटी चञ्चला पहुँचते ही लग गयी खेल करने, प्रियतम ! 
गृह के जो प्रतिपालित सुन्दर पक्षी थे, उन सबसे, प्रियतम !
वह बड़ी राजनन्दिनी किंतु चुपचाप सोचती थी, प्रियतम !
‘आयी तो मैं अवश्य ही हूँ पहले भी कभी यहाँ’, प्रियतम॥२४१॥

कोई मानो कानों में यह कह उठा, ‘सदा जय हो !, प्रियतम !
कानन की अहो ! स्वामिनी की, रसमयी मुग्धता की, प्रियतम !
अपना वासस्थल यह उनका सच्चिदानन्दमय है, प्रियतम ! 
वे भूल रही हैं पर इसको, अपने को, मुझको भी’, प्रियतम॥२४२॥

यह भान उसे होते ही वह अकचक-सी हुई उठी, प्रियतम ! 
स्वर था परिचित, पर किसका है, इस समय न जान सकी, प्रियतम ! 
सम्मुख वह हंस हंसिनी से कह रहा झूम कर था, प्रियतम ! 
‘प्रियतमे ! कथा मैं कहता हूँ, तुम सुनो एक मन से, प्रियतम॥२४३॥

है वन अनादि, इसमें पुष्पित जो वे अशोकतरु हैं, प्रियतम ! 
उत्तरमें उनसे ही निर्मित जो वह निकुञ्जथल है, प्रियतम ! 
उसमें ही नित्य सनातन अज वे दम्पति रहते हैं, प्रियतम ! 
अतिशय ऊँचे हों भाग, तभी कोई ले देख भले, प्रियतम॥२४४॥

वल्लभे ! कहूँ कैसे घटना कबकी वह थी या है, प्रियतम ! 
जब काल नहीं इस वन में है शासन करनेवाला, प्रियतम ! 
है अहो ! त्रिकाल सत्य, फिर है सच परे काल से भी, प्रियतम ! 
इतना-सा ही संकेत गिरा उसका कर सकती है, प्रियतम॥२४५॥

वैसे ही तुम, ‘निकुञ्ज है वह’ ये शब्द भले सुन लो, प्रियतम ! 
पर ‘देश’ नाम से कथित नहीं कोई है वस्तु वहाँ, प्रियतम ! 
‘है कहाँ, अहो !’ फिर इसका है उत्तर इतना बनता, प्रियतम ! 
वह अपनी ही महिमा में है परिनिष्ठित नित्य, भला, प्रियतम॥२४६॥

अच्छा तो, प्राणाधिके ! सुनो, दम्पति के जीवनमें, प्रियतम !
कैसी थी प्रीति परस्पर की, लहरें लेती रहती, प्रियतम !
दोनों ही एक दूसरे को रहते निहारते ही, प्रियतम ! 
फिर भी अतृप्ति रहती, मानो दर्शन का सुख न मिला, प्रियतम॥२४७॥

दोनों के प्राण एक होकर ऐसी गति धर लेते, प्रियतम !
होने लगती प्रतीति उनको, मानो मैं हूँ न अहो !, प्रियतम ! 
स्वीकार काल का वे करते कहनेके लिये तभी, प्रियतम ! 
वह था उनका स्वरूप ही, फिर आरम्भ खेल होता, प्रियतम॥२४८॥

उनकी पलकें खुलतीं, सुस्मित अधरों पर भर आता, प्रियतम ! 
सुस्थिर वे नयन-पुतरियाँ भी चञ्चल कुछ हो जातीं, प्रियतम ! 
गलबाँही दिये हुए ही वे धीरे-धीरे उठते, प्रियतम ! 
चलते धीरे, सुख से धरणी जड़िमा धारण करती, प्रियतम॥२४९॥

आगे प्रवाह बढ़ता क्रमशः उन दोनों के रस का, प्रियतम !
वे अहो ! कहाँ-से-कहाँ जुड़े उसमें बहते रहते, प्रियतम ! 
पीछे आने का प्रश्न नहीं उस धारा में बनता, प्रियतम ! 
वे सृजन और संहारजनित परिणाम न उसमें हैं, प्रियतम॥२५०॥

जो हो, वह घटना है तब की, दोनों जब उत्सुक थे, प्रियतम !
शृङ्गार धराने की इच्छा ले गौर-नील तन में, प्रियतम ! 
दोनोंमें होड़ लगी थी यह, हैं कला किसे कहते, प्रियतम !
दिखलायें आज परस्पर की पहली इस रचना में, प्रियतम॥२५१॥

प्यारी को देख-देखकर ही प्यारे रचना करते, प्रियतम !
प्यारे को देख-देखकर ही प्यारी रचना करती, प्रियतम !
अपने ही आप अँगुलियों में उनकी वे आ जाते, प्रियतम !
उपकरण सभी, आवश्यक जो जितने जब थे होते, प्रियतम॥२५२॥

प्राणों की अभिलाषा ही वह माला बनकर आती, प्रियतम !
प्राणों का ही उल्लास सुमन सुरभित होकर आता, प्रियतम ! 
प्राणों का स्नेह विमल नीला-पीला फुलेल बनता, प्रियतम ! 
प्राणों का ही अनुराग तरल शीतल विलेप होता, प्रियतम॥२५३॥

प्राणों की वृत्ति सदा नव सुख देने-ही-देने की, प्रियतम !
प्राणों की आशा नित्य नये रस में सन जाने की, प्रियतम ! 
प्राणों की वह अभिसंधि मिले रहने की आपस में, प्रियतम !
प्राणों से झर ये सब बनतीं तूली छवि लिखने की, प्रियतम॥२५४॥

प्राणों की ममता ही काली-कबरी डोरी बनती, प्रियतम ! 
प्राणों का मोह परस्पर वह काजल बन जाता था, प्रियतम ! 
प्राणों का अद्वयपन मद चू भ्रूमध्य बिन्दु बनता, प्रियतम! 
प्राणों का प्रणय-रोष होता वह लाल महावर था, प्रियतम॥२५५॥

प्राणों में बढ़ी प्रीति टेढ़ी चलकर कँगही बनती, प्रियतम ! 
प्राणों की रति परिणत होती उज्ज्वलतम दर्पण में, प्रियतम ! 
प्राणों में बढ़ी हुई पल-पल आसक्ति पान होती, प्रियतम !
प्राणों की ही रुचि बन जाती अम्बर नीला-पीला, प्रियतम॥२५६॥

प्राणों का सञ्चालन बनता आवरण पयोधर का, प्रियतम !
प्राणों के स्वर वे सात बंद चोली के हो जाते, प्रियतम !
प्राणों का ही विश्वास अचल, वह पुष्पसार बनता, प्रियतम !
प्राणों की सुन्दरता होती लीला-नीरज कर का, प्रियतम॥२५७॥

यों स्वतः हुई प्रस्तुत चिन्मय सामग्री लेकर वे, प्रियतम !
तल्लीन हुए निरुपम रचना करने लग गये वहाँ, प्रियतम ! 
भावों से कर हिल-हिलकर, था कुछ-का-कुछ बन जाता, प्रियतम ! 
दो-तीन बार में ही पूरा श्रृंगार एक होता, प्रियतम॥२५८॥

हो गयी वेश-रचना, तब वे कहने इस भाँति लगे, प्रियतम !
किसने बाजी जीती बोलो, ‘पहले तुम’, ‘तुम पहले’, प्रियतम ! 
कोई सम्मत न हुआ, निर्णय जो पहले बतलाये, प्रियतम ! 
बस, झूल-झूलकर हँसते वे, गलबाँही दिये हुए, प्रियतम॥२५९॥

आखिर बोली प्यारी, प्यारे ! तुम अहो ! विजेता हो, प्रियतम ! 
बोला प्यारा, सच हे प्यारी ! श्री-कर में ही जय है, प्रियतम ! 
दोनों ही दुहराते जाते अपनी ही उक्ति, भला, प्रियतम ! 
मुखरित निकुञ्ज वन का कण-कण होता उस मधुरव से, प्रियतम॥२६०॥

क्या सत्य कभी दो है होता ? है नित्य एक वह तो, प्रियतम !
प्यारी विचार कर तुम देखो, है उक्ति सही मेरी, प्रियतम ! 
हे प्यारे ! है स्वीकार मुझे यह, सत्य एक ही है, प्रियतम ! 
सोचो तुम बार-बार अब भी, मेरा कहना सच है, प्रियतम॥२६१॥

ऐसी बतकही रसीली शुचि उनमें पल साठ चली, प्रियतम !
यह कहा अन्तमें प्यारीने, प्यारे ! देखो अब तो, प्रियतम !
अपने-ही-आप सजाऊँगी मैं अपने इस तन को, प्रियतम !
तुम किंतु घड़ी आधी अपने लोचन मूँदे रहना, प्रियतम॥२६२॥

प्यारे ने हँस-हँस कर ऐसा करना स्वीकार किया, प्रियतम !
शर्तें दो रखी, किंतु उसने कुछ बात सोच करके, प्रियतम ! 
छूता मैं रहूँ निरन्तर ये दस नख पीले पद के, प्रियतम ! 
फिर मैं भी अङ्ग सँवारूँ, तब मीलित-दृग तुम रहना, प्रियतम॥२६३॥

प्यारी ने मुसका-मुसकाकर हामी भर ली इसकी, प्रियतम !
कौतुक नवीन आरम्भ हुआ अब वह निमेष में ही, प्रियतम !
मुट्ठी में पद-नख मणि धारण करके प्यारे बैठे, प्रियतम ! 
प्यारी विचित्र अपने तन की रचना करने बैठी, प्रियतम॥२६४॥

बोली मन में, प्यारेको मैं अबतक सुख दे न सकी, प्रियतम !
ये सदा पूछते रहते हैं बातें अनेक मुझसे, प्रियतम !
लज्जा में भरी किंतु मैं तो कुछ बोल नहीं पाती, प्रियतम ! 
अतएव रूप अपना निरवधि मैं एक और कर लूँ, प्रियतम॥२६५॥

कर्पूर-गौर वह रूप बने करुणा से नित्य भरा, प्रियतम ! 
अलकें उसकी कमनीय अहो ! बन जायँ जटा नीली, प्रियतम ! 
आवरण-हीन वह नित्य रहे, भूषित फिर नित्य रहे, प्रियतम ! 
प्यारे के पद-सरोरुहों की रज की परछाँही से, प्रियतम॥२६६॥

देवी के बदले प्यारे को वह महादेव दीखे, प्रियतम !
प्यारे की प्रियता भी उसमें पल-पल परिवर्धित हो, प्रियतम !
मैं युगपत् अपने इस तनको, उस महादेव-तनको, प्रियतम ! 
देखूँ, मेरी मुग्धता किंतु यह भी अक्षुण्ण रहे, प्रियतम॥२६७॥

इसके पश्चात अहो ! जब भी जो भी ये प्रश्न करें, प्रियतम ! 
तत्क्षण ही समाधान उसका सुन्दर कर पाऊँ मैं, प्रियतम ! 
प्यारे को सुख ही दूँ, मेरा जीवन है इसीलिये, प्रियतम ! 
है सच यह, तो प्यारे देखें वह रूप आँख खुलते, प्रियतम॥२६८॥

प्यारे के लोचन उन्मीलित हो गये विपलमें ही, प्रियतम ! 
प्यारी का अद्भुत रूप निरख करके वह मुसकाया, प्रियतम ! 
‘जय-जय हे ! महादेव ! जय !’ फिर कहकर नतमस्तक हो, प्रियतम ! 
वह भी अब चला वेश-रचना करने नूतन अपनी, प्रियतम॥२६९॥

प्यारी के चिन्तन में ही थी प्यारे की वृत्ति लगी, प्रियतम ! 
ऐसी अखण्ड तन्मयता थी पल तीस बनी उसकी, प्रियतम ! 
जो प्रायः उसको परिणत थी प्यारी में कर बैठी, प्रियतम ! 
अतएव ढक गया साँवरपन पहले गोरेपन से, प्रियतम॥२७०॥

हो गये व्यक्त फिर उसमें वे तरुणी के चिह्न सभी, प्रियतम ! 
वह बना रमण से अब रमणी सुन्दरी अतुल गोरी, प्रियतम ! 
सम्मिश्रित भावों का बोझा इतना गुरु-गुरुतर था, प्रियतम ! 
जिससे दबकर दृग ने धर ली अचपल गंभीर मुद्रा, प्रियतम॥२७१॥

प्यारे में प्यारेपन की कुछ अब भी थी गन्ध बची, प्रियतम !
इसलिये सोचता था यों वह रमणी-तन में बैठा, प्रियतम !
प्यारी के सभी मनोरथ हों पूरे अनुराग भरे, प्रियतम !
इन महादेव की मैं भी अब हूँ नित्य महादेवी, प्रियतम॥२७२॥

चारों में ही स्वरूपतः है यद्यपि न भेद कोई, प्रियतम !
चारों ये रूप सर्वथा हैं सच्चिदानन्दमय ही, प्रियतम !
लीलाप्रिय अहो ! किंतु निरवधि हम चार हुए खेलें, प्रियतम ! 
युगपत् मुग्धता, नित्य संविद् मुझ में भी व्यक्त रहे, प्रियतम॥२७३॥

उन महादेव के इतने में लोचन खुल गये, तथा, प्रियतम !
शोभा निहार कर मुग्ध हुए वे उन नवदेवी की, प्रियतम !
वे पार्श्ववर्तिनी क्षण में ही चिर-परिचित हो बैठीं, प्रियतम !
उमड़ा रस-सिन्धु, देव डूबे देवी को साथ लिये, प्रियतम॥२७४॥

पहली तरंग से ही प्लावित उत्तर की कुञ्ज हुई, प्रियतम !
फिर लहर दूसरी में कानन पश्चिम का डूब गया, प्रियतम !
ऊँची अत्यन्त तीसरी में दक्षिण का वन डूबा, प्रियतम !
चौथे प्रवाह में मग्न हुआ प्राची अरण्य पूरा, प्रियतम॥२७५॥

प्लावन जाकर तब कहीं थमा, जब युग असंख्य बीते, प्रियतम !
देवी वे महादेव उससे बाहर अब निकल सके, प्रियतम !
डूबे रहने का सुख अनुपम उन चारों लहरों में, प्रियतम ! 
जो था उनको अनुभूत हुआ, उसकी ही बात छिड़ी, प्रियतम॥२७६॥

देवी बोली, स्वर था उनका मानो रस का सोता, प्रियतम ! 
हे नाथ ! बात कुछ बतलाओ उत्तर निकुञ्जवाली, प्रियतम !
सुनते ही महादेव गद्-गद् होकर यों बोल पड़े, प्रियतम !
हे सती ! सुनो द्रुमडाली पर हिमकर के न्याय कहूँ, प्रियतम॥२७७॥

युगपत् निस्पन्द नित्य एवं उच्छलित नित्य रस है, प्रियतम !
वह देश-काल से परे जहाँ अपने स्वरूप में है, प्रियतम !
है किंतु कूल पर जो, उसकी आँखों के अनुभव में, प्रियतम !
उसके स्वभाव ये नित्य अहो ! आते हैं क्रमशः ही, प्रियतम॥२७८॥

आस्वादन, आस्वादक एवं आस्वाद्य नामवाला, प्रियतम ! 
सच तो यह है, दयिते ! किंचित् कोई है भेद नहीं, प्रियतम ! 
फिर भी वह है रसराज, वहाँ वह महाभाव भी है, प्रियतम ! 
इन दो की ही क्रीड़ा चलती उत्तरनिकुञ्ज में है, प्रियतम॥२७९॥

'प्राणाधिक ! कहो वनस्थल की पश्चिम के क्या गति है ? प्रियतम !
देवी की आँख लगी बहने झर-झर कहकर इतना, प्रियतम !
विह्वल वे देव जटावाले उस ओर हुए ऐसे प्रियतम !
मानो प्रवाहिणी भावों की ले डूबेगी उनको, प्रियतम॥२८०॥

जैसे-तैसे अपने को वे किंचित् सँभाल पाये, प्रियतम ! 
हो जाता कण्ठ रुद्ध फिर भी, ज्यों कुछ कहने चलते, प्रियतम ! 
आखिर वे बोल सके इतना, प्रियतमे ! वहाँ देखो, प्रियतम ! 
रसराज नित्य नीला निरुपम शिशु बन है खेल रहा, प्रियतम॥२८१॥

स्वामिन् ! दक्षिण वन में क्या है ? देवी ने अब पूछा, प्रियतम ! 
करते-करते ही प्रश्न किंतु ढल पड़ीं देव पर वे, प्रियतम ! 
उत्तर का उनको पहले ही मानो आभास मिला, प्रियतम ! 
उस सुख में ही वह चेतनता सत्तर पल डूब गयी, प्रियतम॥२८२॥

अनुरागभरे शीतल कर से दयिता के अङ्गों को, प्रियतम ! 
सहला-सहलाकर देव लगे करने प्रबुद्ध उनको, प्रियतम ! 
आकुल बूँदें टप-टप दृगसे गिर रही अनर्गल थीं, प्रियतम ! 
अभिषेक हो रहा था उनसे देवी के श्री-मुख का, प्रियतम॥२८३॥

वे जगीं देव ने बात कही दक्षिण अरण्यथल की, प्रियतम !
वह महाभाव ही नित्य बना अवनीशनन्दिनी है, प्रियतम !
रसराज बना ताना उसमें, है महाभाव बाना, प्रियतम ! 
निर्मित वितान उस पट से है नभ में उन दो वन का प्रियतम॥२८४॥

देवी के मृदुल कलेवर में चल पड़ी गुद-गुदी-सी, प्रियतम ! 
मानो ऊपर तक रस भरकर हिल गया बाँध उरका, प्रियतम ! 
ऊँचे स्वर से रह-रहकर वे हँसने अब लगीं, तथा, प्रियतम !
‘पूरब-पूरब’ केवल इतना मुख से था निकल रहा, प्रियतम॥२८५॥

‘अच्छा तो, पूरब वन की भी अब बात रहस्यमयी, प्रियतम ! 
जीवनसंगिनि ! सुन लो’, बोले वे महादेवता भी, प्रियतम ! 
अभिनव सुन्दर शुचि रंगस्थल वह मधुर भावका है, प्रियतम ! 
है जहाँ प्रीति का आश्रय भी फिर विषय परस्पर वे, प्रियतम॥२८६॥

है प्रीति ढली वह किंतु वहाँ अद्भुत उस साँचे में, प्रियतम ! 
आवरण दोष का लिये अहो ! जो नित्य निराविल है, प्रियतम !
पावनतम है, पल-पल में है नव-नव होनेवाला, प्रियतम ! 
हो सकी, न है तुलना जिसकी, होगी भी नहीं कभी, प्रियतम॥२८७॥

इतना कहते-सुनते ही वे दोनों ध्यानस्थ हुए, प्रियतम !
पुष्पित अशोक डाली वह ऊपर से एक झुकी, प्रियतम !
उन दोनों पर ही झूल, लगी सुरभित बयार करने, प्रियतम !
हम दो भी तत्क्षण उनकी ही झर पड़े साँस से हैं’, प्रियतम॥२८८॥

यह उपर्युक्त इतिहास हंस कह गया हंसिनी से, प्रियतम !
तन्मय होकर सुन गयी इसे वह राजनन्दिनी भी, प्रियतम !
अब लिये मराल मराली को धीरे-धीरे आया, प्रियतम !
छूने स्वचञ्चु से लगा धरा नृप-दुहिता के आगे, प्रियतम॥२८९॥

कर रही याद-सी अपनी ही भूली कुछ बातों को, प्रियतम !
थी खड़ी नृपति-दुहिता नीरव गुत्थी सुलझाती-सी, प्रियतम !
‘है जुड़ा अवश्य अहो ! मुझसे इतिवृत्त हंसवाला’ प्रियतम ! 
कुछ पल के लिये चित्त उसका भावित इस भाँति हुआ, प्रियतम॥२९०॥

मन में आया, मराल से ही क्यों मैं न पूछ यह लूँ, प्रियतम !
संकोच हो गया किंतु, पुरुष आखिर विहङ्ग यह है, प्रियतम ! 
अतएव तनिक चतुराई का पथ अपनाया उसने, प्रियतम ! 
बोली- ‘हे हंस ! जहाँ वे हैं, मैं जा सकती हूँ क्या ?’, प्रियतम॥२९१॥

‘निर्बाध, अवश्य-अवश्य अहो ! नृप-नन्दिनि, जब चाहो, प्रियतम !
श्रीपद का ही तो नित्य, भला, कर रहे ध्यान वे हैं, प्रियतम ! 
जा-जाकर ही रस-वारिधि में सब पथिक नहाते हैं, प्रियतम ! 
आ जाय उमड़कर पास वही, यह भाग सुदुर्लभ है’ प्रियतम॥२९२॥

ऐसे कह उठा हंस, देकर फेरी नृपपुत्री की, प्रियतम ! 
गुत्थी खुलती-सी दीखी, पर उसका मन उलझ गया, प्रियतम ! 
उस नेह जाल में, विधिगति से, जो अकस्मात फैला, प्रियतम ! 
लेकर मराल की ओट सरस चालित अलक्ष्य कर से, प्रियतम॥२९३॥

लज्जा का भान हुआ, फिर भी बोली वह धीरे-से, प्रियतम !
जाऊँ मराल मैं किस पथ से, इतना-सा और कहो, प्रियतम !
विस्मृत-सी हुई मुझे बातें लगती निकुञ्ज की हैं, प्रियतम !
 तुम सहृदय हो, इससे साहस हो गया पूछने का' प्रियतम॥२९४॥

दो पथ, महीपनन्दिनि ! हैं, तुम चाहो जिससे, जाओ, प्रियतम !
पहले में दोनों ओर लगे उज्ज्वल फूले तरु हैं, प्रियतम !
पथरीला है, वह ठंढापन-सूनापन लिये हुए प्रियतम !
अव्यक्त और हो जाते हैं पदचिह्न सभी उसमें, प्रियतम॥२९५॥

है लता दूसरे में पीली लिपटी नीले द्रुम से, प्रियतम !
वह नवल बारहों मास बनी, नौ भाँति फूलती है, प्रियतम !
आगे वह लाल कुसुम पथ को करता परागमय है, प्रियतम !
अङ्कित सुस्पष्ट चिह्न उसपर होते पद-पद पर हैं, प्रियतम॥२९६॥

पहला पथ है उनका, जिनका धीरज न छूटता है, प्रियतम !
बाहर न आँख जाती जिनकी, मति सहस्रार में है, प्रियतम !
करते न विराम कभी जो हैं, रखते न पास कुछ हैं, प्रियतम !
है अहम् निकल जाता जिनका चलने से पहले ही, प्रियतम॥२९७॥

फूली लतिका पथ है, उनका आकुल जो पल-पल हैं, प्रियतम ! 
आँखें फँसती हैं जिनकी, रति उर के भावों में है, प्रियतम ! 
हैं श्रमित चरण जिनके, जो हैं अञ्चल में फूल लिये, प्रियतम ! 
छाया रसमयी अहंता की जिनको न छोड़ती है, प्रियतम॥२९८॥

यह नृपति-तनूजे ! विनती इस किंकर मराल की है, प्रियतम ! 
तुम तो दोनों पथ को हँसकर केवल छू भर लेना, प्रियतम ! 
अग्रिम इस उपवन से भी, वे चलते हैं सटे-सटे, प्रियतम ! 
इतने में ही वह हंसिनी उड़ी, उड़ गया हंस पीछे प्रियतम॥२९९॥

नृपपुत्री बारह-चौदह पल खोयी-सी खड़ी रही, प्रियतम !
उस ओर देखती, उड़कर थे वे जिधर विहङ्ग गये, प्रियतम !
सहसा उसकी फिर चित्तवृत्ति अनुजा की ओर गयी, प्रियतम !
देखा वह तो सोयी सुख से गहरी निद्रा में है, प्रियतम॥३००॥

क्या करूँ ? जगाऊँ इसको या मैं ही किंचित् ठहरूँ प्रियतम ! 
यों रही सोचती, किंतु ठीक निर्णय कुछ कर न सकी, प्रियतम ! 
थी भरी अनोखी निर्भयता सर्वत्र वहाँ गृह में, प्रियतम ! 
आयी न अतः उसके मन में कोई अनिष्ट-शङ्का, प्रियतम॥३०१॥

घूमूँ मैं इस उपवन में यह तब तक जग सकती है, प्रियतम ! 
जगकर यह मुझे ढूँढ़ लेगी, मैं दूर न जाऊँगी, प्रियतम ! 
ऐसा विचार कर चली तथा उपवन में जा पैठी, प्रियतम ! 
लगभग सौ पद पर ही दीखी ऊँची-सी एक शिला प्रियतम॥३०२॥

उसपर चढ़कर उसने डाली सब ओर दृष्टि अपनी, प्रियतम !
जीवन का पहला अवसर था, सर्वथा अकेली थी, प्रियतम !
यह हुई प्रतीति उसे, मानो कोई पुकारता हो, प्रियतम !
आओ, प्रियतमे ! इधर आओ, पथ देख रहा हूँ मैं प्रियतम॥३०३॥
''',
      ),
      BookPage(
        title: 'चतुर्थ शतक',
        content: '''प्उद्यान एक उस वन में था सुषमा की खानि बना, प्रियतम !
आकर्षण कण-कण में उसके ऐसा था भरा हुआ, प्रियतम !
कोई प्राणी सपने में भी क्षणभर यदि देख सके, प्रियतम ! 
खोकर सब कुछ भी वह अपना चाहेगा जाना ही, प्रियतम॥३०४॥

प्राची की ओर लता मण्डित शोभित तमाल तरु थे, प्रियतम !
दक्षिण-पश्चिम-उत्तर में थी श्रेणी कदम्ब की, हे प्रियतम !
थी भूमि वाटिका की अनुपम सर्वत्र लालमणि की, प्रियतम !
विरचित वेदी थी एक वहाँ कुसुमों की क्यारी में, प्रियतम॥३०५॥

उस पद्मराग की वेदीपर फूलों के बीच खड़ी, प्रियतम !
नीलम-निर्मित थी मूर्ति एक, मानो, बस बोल चली, प्रियतम !
अभिनव बालक की, जो अपने करमें था वेणु लिये, प्रियतम !
स्वर भरने की तैयारी में, कुछ बात सोचता-सा, प्रियतम॥३०६॥

इस नीली-प्रतिमा से पूरब, बस, ठीक सामने ही, प्रियतम !
थी प्रस्तर-शिला, खड़ी जिस पर वह राजकुमारी थी, प्रियतम !
दोनों में थी दूरी केवल पद तीन-चार सौ की, प्रियतम !
वे विटप तमाल वाटिका के छू रहे शिला को थे, प्रियतम॥३०७॥

सुस्पष्ट शिला पर से ही थी सहसा वह दीख गयी, प्रियतम !
प्रतिमा अवनीशनन्दिनी को सुन पड़ा और वह था, प्रियतम !
मीठा स्वर उसे बुलाने का उस दिशा प्रतीची से, प्रियतम !
दोनों ही एक काल में ही बातें ये हुईं वहाँ, प्रियतम॥३०८॥

सुन्दर नव वह अनुभूति सुखद नरपालनन्दिनी की, प्रियतम ! 
कैसे बतलाऊँ, वाणी के वश की है बात नहीं, प्रियतम ! 
ऐसे सब अवसर पर रहता है रिक्त कोश उसका, प्रियतम ! 
मिलनेकी युक्ति मिली न उसे श्रवणों से, लोचन से, प्रियतम॥३०९॥

जो हो, तत्काल उतर आयी नृपपुत्री, किंतु उसे, प्रियतम ! 
कोई न मिली पगदंडी, जो सीधे उस ओर चले, प्रियतम ! 
वे सघन लताएँ उपवन की जुड़कर थीं जाल बनी, प्रियतम ! 
उत्तर का तो पथ मिलता था, पर नहीं प्रतीची का, प्रियतम॥३१०॥

धीरज न बचा उसमें अब था, जो सोच-विचार करे, प्रियतम !
अपना सिर डाल दिया उसने वल्ली के छिद्रों में, प्रियतम ! 
जैसे-तैसे निर्माण लगी करने पथ उनमें ही, प्रियतम !
वे टूट न जायँ, किंतु इतना था ध्यान बना उसमें, प्रियतम॥३११॥

जैसी भावना निकलती है, वैसी ही आती है, प्रियतम ! 
वल्लरियों के मन में आया, तोड़ें न हृदय इसका, प्रियतम ! 
अपने ही आप लगीं होने अपसारित वे पल में, प्रियतम ! 
छोटा-सा द्वार बना, नृप की पुत्री उस पार हुई, प्रियतम॥३१२॥

भावोंसे थी विभोर, दिग्भ्रम हो गया अतः उसको, प्रियतम !
सीधे पश्चिम चलना था, पर उत्तर की ओर चली, प्रियतम !
गूँजी कानों में इतने में वैसी ही मधुर गिरा, प्रियतम !
‘बायें प्राणों की रानी हे ! तुम तो मुड़ चलो अभी’, प्रियतम॥३१३॥

उसके दृग सुलझे, भान हुआ, प्रतिमा बायें ही है, प्रियतम !
झंकृत उर-तार हुए छूकर उस लहर वैखरी को, प्रियतम !
क्या मूर्ति वही है बोल रही, भ्रम होने लगा उसे, प्रियतम !
कैसे सुन पायी स्वर धीमा इतना इस दूरी से, प्रियतम॥३१४॥

दौड़ी वह भान भुलाकर अब, नीचे क्या है इसका, प्रियतम ! 
कैसे न अहो ! टकरायी, वह तरु से अचरज यह था, प्रियतम !
दो-तीन पलों में पद्मराग वेदी पर जा पहुँची, प्रियतम !
थे खड़े सभी द्रुम हरे-हरे, वे पत्र-छत्र ताने, प्रियतम॥३१५॥

छू गये मृदुल पद जाते ही उसके अजान में ही, प्रियतम !
फूलों के सुरभित गजरे से, जो पड़ा सामने था, प्रियतम !
यों जान-बूझकर ही जैसे रख दिया किसी ने हो, प्रियतम !
सुन्दर सरोज के पत्ते पर, बस, अभी सजा करके, प्रियतम॥३१६॥

इतने समीप से प्रतिमा की शोभा निहारते ही, प्रियतम !
भावोंकी एक उठी आँधी, उड़ गया चित्त उसका, प्रियतम !
उसके प्रवाह में पीछे अब संभव न लौटना था, प्रियतम !
जीवन का मानचित्र बदला दस-बारह पल में ही, प्रियतम॥३१७॥

भोलापन-पूरित शिशुता के अन्तर्हित भाव हुए, प्रियतम !
आये प्राणों के विनिमय के उद्दीपन वाले वे, प्रियतम !
बदली चितवन की रीति, रंग बदला वारिज-मुख का, प्रियतम !
अङ्गों की संचालन-शैली पूरी वह बदल गयी, प्रियतम॥३१८॥

नृपपुत्री के निहारने पर आधे मीलित-दृग से प्रियतम ! 
प्रतिमा सजीव-सी ऐसी थी रह-रहकर बन जाती, प्रियतम ! 
मानो हो अतुल नीलसुन्दर कोई किशोर वय का, प्रियतम ! 
प्राणों को रोके सत्य अहो ! ठग रहा उसी को हो, प्रियतम॥३१९॥

क्यों हो विलम्ब, फिर काल कहीं कुछ हेर-फेर कर दे, प्रियतम ! 
स्वर्णिम-वेला चल देती है पल-आधे-पल में ही, प्रियतम ! 
ले माल चली नृपसुता वहाँ निरवधि निमग्न होने, प्रियतम ! 
प्राणों की दो सरिता मिलकर होती है एक जहाँ, प्रियतम॥३२०॥

चञ्चल हरिणी-सी आँख बड़ी क्षण एक हुई उसकी, प्रियतम !
देखा जब उसने, दर्शक था कोई भी नहीं वहाँ, प्रियतम !
वह सुमनहार मानो प्रतीक जीवन-यौवन, सबका, प्रियतम !
ग्रीवा में प्रतिमा के पहना, चरणों में लुढ़क पड़ी, प्रियतम॥३२१॥

बह चली अनर्गल अब धारा नयनों से, छू नख को, प्रियतम ! 
उस इन्द्रनील-विरचित शिशुके, आकुल थी नृप-दुहिता, प्रियतम ! 
‘कैसे मेरे ये प्राण अभी इनमें प्रविष्ट होवें, प्रियतम ! 
फिर काल अन्त-विरहित तक मैं केवल देखूँ मुख को’ प्रियतम॥३२२॥

भूली वह, कौन कहाँ मैं हूँ, कितने क्षण, कौन कहे, प्रियतम !
युग-युग बीते अथवा परार्द्ध, नखमणि में लीन हुए, प्रियतम ! 
सहसा, आँखें जब खुलीं, लगा, ‘मूर्छित थी हुई अभी’ प्रियतम ! 
सर्वस्व-समर्पण कर अपना, होकर दासी इनकी, प्रियतम॥३२३॥

है सत्य किसी की आकृति ही यह, पर वह है मेरा, प्रियतम ! 
हूँ एकमात्र उसकी मैं अब, अधिकार परस्पर है, प्रियतम ! 
वह मिले मुझे या मिले नहीं, इसकी क्या चिन्ता है, प्रियतम !
प्राणों का सौदा होता है क्षण में कुछ ऐसे ही, प्रियतम॥३२४॥

अपने जीवन की साध अभी पूरी कर लेती हूँ, प्रियतम !
क्षणभर इस कण्ठ मनोहर से बस एक बार भेंटूँ, प्रियतम !
एकान्त मुझे अवसर ऐसा फिर मिले, न कभी मिले, प्रियतम ! 
आ पाऊँगी भी इस वनमें है बात भाग्यलिपि की, प्रियतम॥३२५॥

दृग लगे पुनः छल-छल करने, वह उठी, भुजा फैली, प्रियतम ! 
आगे तुम देख भले ही लो झूलना सरस उसका, प्रियतम ! 
कहकर पवित्रता मैं अधमा उसकी क्यों नष्ट करूँ, प्रियतम ! 
केवल वह है सम्बल मेरा, मैं क्यों खोऊँ उसको ! प्रियतम॥३२६॥

इतना-सा ही कह सकती हूँ, वह मिलन अर्धपल का, प्रियतम !
आधार-शिला बनकर उसपर बनने प्रासाद लगा, प्रियतम ! 
जिसमें विभाग थे- स्नेह, मान, वे प्रणय, राग, आगे, प्रियतम ! 
अनुराग, भाव, फिर महाभाव, सातों अप्रतिम बने, प्रियतम॥३२७॥

अधिदेवी उन सातों की थी वह राजतनूजा ही, प्रियतम !
जो स्नेहकक्ष था, किंतु अभी उसमें थी वह उतरी, प्रियतम !
इतने में ही खोजती उसे अनुजा झट आ पहुँची, प्रियतम !
उसके पद चिह्नों पर चलकर जो उगे धरा पर थे, प्रियतम॥३२८॥

दो हाथ हटी प्रतिमा से थी बैठी नृप की पुत्री, प्रियतम ! 
पीछे से उसके कंधों पर कर रखकर वह बोली, प्रियतम ! 
‘री बहिन ! कहाँ मन तेरा है, क्यों छोड़ मुझे आयी, प्रियतम ! 
अच्छा, अब तो बतला दे, क्या-क्या है करना, कैसे’, प्रियतम॥३२९॥

जागी समाधि से वह, लज्जा किंचित्-सी हुई उसे, प्रियतम ! 
क्रमशः उसको सब बतलाया, जिस भाँति यहाँ पहुँची,प्रियतम ! 
सुनकर वह बड़ी बहिन से यह पूरा ब्योरा, बोली, प्रियतम !
‘मैं पहले से ही प्रतिमा की कुछ बात जानती हूँ’, प्रियतम॥३३०॥

नृप-पुत्री चौंक उठी, मानो मिल गयी उसे ताली, प्रियतम ! 
पेटी की अहो ! महानिधि वह थी बन्दपड़ी जिसमें, प्रियतम ! 
तू सब बतला दे, पता तुझे जो कुछ है, अभी मुझे प्रियतम ! 
भुजमाल कनिष्ठा को पहना, इतना ही कह पायी, प्रियतम॥३३१॥

अच्छा, सुन ले ! आँखें, वाणी अनुजा की घूम उठीं, प्रियतम ! 
मौसी ने बात कही मुझसे, रूठी बैठी तू थी, प्रियतम ! 
आश्विन की एक वर्ष पहले थी साँझ अमावस की, प्रियतम ! 
साँझी के फूल बीन लौटीं हम सभी देर से थीं, प्रियतम॥३३२॥

मौसी बोली, लाड़िली बड़ी बावली, सत्य यह है, प्रियतम ! 
छोटी होकर भी तू तो पर सब बात समझती है, प्रियतम !
मैं बतलाऊँ, क्यों तुम सब पर तुम सबकी ही मैया, प्रियतम !
है आज तनिक-सी खीझ गयी ज्यों ही तुम सब आयीं, प्रियतम॥३३३॥

घटना है ग्यारह मास, दिवस दो अबसे पहले की, प्रियतम ! 
तेरा श्रीभैया वन में था गायों को लिये गया, प्रियतम !
शिशुओं में दैवयोग से यह चर्चा छिड़ गयी वहाँ, प्रियतम !
इन सभी अरण्यों का राजा है कौन, कहे कोई, प्रियतम॥३३४॥

जो वे गोपों के अधिपति हैं, उनका बेटा बोला, प्रियतम ! 
‘मैं ही हूँ नित्य ईश सबका, थे, हैं, होंगे वन जो’ प्रियतम !
हँस पड़ा हँसोड़ा शिशु सुनकर, भूसुरकुल का जो था, प्रियतम ! 
बारह ही वर्ष-वयस का जो रहता था बना सदा, प्रियतम॥३३५॥

क्यों हँसा, बोल सच तू, उसके पीछे पड़ गये सभी, प्रियतम !
वह भी पक्का था, चंगुल में फँसता न किसी के था, प्रियतम ! 
थी किंतु एक दुर्बलता, जो उसको थी च्युत करती, प्रियतम ! 
कोई मीठी कुछ वस्तु खिला ले लेता मोल उसे, प्रियतम॥३३६॥

शिशुओं ने यही उपाय किया, मोदक की भेंट धरी, प्रियतम ! 
खाकर वह बोला- ‘राजा हैं श्रीभैया के बाबा, प्रियतम !
वे सभी बनों के, ब्रज के हैं पालक पालक के भी, प्रियतम ! 
ये गोपराज भी पहले थे देते कर उस कुल को, प्रियतम॥३३७॥

जो वृद्धपितामह हैं, उनने कर लेना बंद किया, प्रियतम ! 
हो गयी मित्रता अद्भुत-सी दोनों ही नृपकुल में, प्रियतम !
बँध गये स्नेह के बन्धन में दो राजवंश ऐसे, प्रियतम !
मानो हों अहो ! एक माँ से जाये जो गद्दी लें, प्रियतम॥३३८॥

अतएव छूट इसको है, यह चाहे जिस कानन में, प्रियतम ! 
जाकर गोचारण करे, कहीं है रोक नहीं कोई, प्रियतम ! 
श्रीभैया के बाबा चाहें तो आज बंद कर दें, प्रियतम ! 
छोटा-सा जो वन है इसका, उसमें ही फिर घूमो, प्रियतम॥३३९॥

यह वन विशेषतः, जिसमें हैं बैठे हम सभी अभी, प्रियतम ! 
केवल जगदम्बा का है, वे रहती इसमें ही हैं, प्रियतम ! 
है पता नहीं कुछ, तब भी यह बोला-'मालिक मैं हूँ’, प्रियतम ! 
इसके इस भोलेपनपर ही आ गयी हँसी मुझको’, प्रियतम॥३४०॥

गोपेश-तनय मुसकाया, दृग-कनखी से देख उसे, प्रियतम !
प्राणों का प्यार उधर उमड़ा तेरे श्रीभैया का, प्रियतम !
जीवन के नित्य-सखा की क्यों खण्डित वह उक्ति हुई, प्रियतम ! 
तत्क्षण उसने पूछा हँसकर उस बन्धु हँसोड़े से, प्रियतम॥३४१॥

तू तो पण्डित है ही, बतला, कोई उपाय है क्या ? प्रियतम ! 
कल रवि उगने से पहले यह हो जाय बात सच्ची, प्रियतम ! 
अधिकार आज जिस-जिस वनपर मेरे बाबा का है, प्रियतम ! 
स्वामी उन सबका निरवधि हो यह प्राणसखा मेरा। प्रियतम॥३४२॥

उत्तर तुरंत सुन्दर इसका दे दिया हँसोड़े ने, प्रियतम ! 
तू ही तो है युवराज, कहीं तू त्याग सत्य कर दे, प्रियतम ! 
उस ओर अहो ! तेरी बहिनें जो दो सहोदरा हैं, प्रियतम ! 
उनकी इस गोपराज सुत से हो चुकी सगाई है, प्रियतम॥३४३॥

जब भी विवाह हो, इससे क्या, बस, आज रात में ही, प्रियतम ! 
भावी दहेज का दान-पत्र तेरे बाबा लिख दें, प्रियतम ! 
फिर तो वैसा ही होगा, तू जैसा है चाह रहा, प्रियतम ! 
पूरे अरण्य का कल होगा यह एक छत्र राजा। प्रियतम॥३४४॥

चर्चा यह आयी-गयी-सदृश औरों के लिये हुई, प्रियतम !
तेरे श्रीभैया के मनसे वह किंतु नहीं निकली, प्रियतम !
सन्ध्या के समय लौट कर जब बन से घर पर आया, प्रियतम !
चुपचाप महादेवी के वह मन्दिर में जा बैठा। प्रियतम॥३४५॥

जाकर तुरंत हम सब चिन्तित उसको पूछने लगे, प्रियतम !
कारण न किंतु बतलाता कुछ, मुख था उदास उसका, प्रियतम !
तेरी मैया, मौसी मैं, फिर तेरे बाबा, मौसा, प्रियतम !
ये चार जने थे वहाँ, लगा रोने वह आकुल हो। प्रियतम॥३४६॥

मैंने समझाया, मैया ने, बाबा ने, मौसा ने, प्रियतम !
घिग्घी उसकी बँध गयी, और इतना-सा बोल सका, प्रियतम ! 
बाबा ! प्रण तुम पहले कर लो, जो भी मैं अभी कहूँ, प्रियतम ! 
उसको ज्यों-का-त्यों सत्य-सत्य पूरा करना ही है।, प्रियतम॥३४७॥

तेरे बाबा ने भी पलभर सोचा तक नहीं तनिक, प्रियतम ! 
अर्चन का जल था पास, उसे करमें लेकर बोले, प्रियतम ! 
रे लाल ! देन जगजननी की तू तो मेरे घर है, प्रियतम ! 
तू जो भी कह देगा, उसको वैसेही कर दूँगा, प्रियतम॥३४८॥

बोला श्रीभैया, आँखों में फिर से जल भर कर के, प्रियतम ! 
बाबा ! है प्रिय साँवरा अहो ! प्राणों से अधिक मुझे, प्रियतम ! 
बातें इस भाँति हुईं वनमें, भारी है व्यथा मुझे, प्रियतम ! 
उस सखा विदूषक के अन्तिम निर्णय को सत्य करो ! प्रियतम॥३४९॥

जीवन में चाह नहीं है यह, राजा मैं कभी बनूँ, प्रियतम !
मेरी प्राणोपम दो बहिनें असमोर्ध्व भागवाली, प्रियतम !
हो चुकी साँवरे की हैं, अब मैं भी निहाल होऊँ, प्रियतम !
राजा हो वही, रखूँ मैं तो निरवधि सँभाल उसकी, प्रियतम॥३५०॥

चारों ही स्नेह-विभावित थे हम लगे विकल रोने, प्रियतम !
तेरे श्रीभैया के उर की लखकर विशालता को, प्रियतम !
चलती अविराम रही पावन धारा आठों दृगसे, प्रियतम !
उसमें भीगे रह कर ही यों तेरे बाबा बोले, प्रियतम॥३५१॥

सुन्दर ऐसा क्षण पहला है, जिस में मैं आज कहूँ, प्रियतम ! 
है धन्य पितापन मेरा अब, जो पुत्र मिला तुझसा, प्रियतम ! 
मेरी भी यही लालसा थी, रे लाल ! धन्य तू है, प्रियतम ! 
दे दिया अहो ! तुमने सब कुछ माँगे ही बिना मुझे। प्रियतम॥३५२॥

तत्काल बुलाने दूत गया गुरुदेव महोदय को, प्रियतम !
वे भी आये, रजनी सौ पल चढ़ने से पहले ही, प्रियतम !
उनको प्रत्यक्ष मिला था यह आदेश दिवाकर का, प्रियतम !
सायं-संध्या के समय उठे ज्यों चले नहाने वे, प्रियतम॥३५३॥

जाओ तुम नील-सरोवर पर, उसको प्रणाम करना, प्रियतम ! 
उत्तर-पूरबके कोनेपर अञ्जलि में फूल लिये, प्रियतम ! 
जल में प्रविष्ट होकर धीरे-धीरे क्रमशः बढ़ना, प्रियतम ! 
अपने-ही-आप सुमन कर से च्युत होते ही रुकना, प्रियतम॥३५४॥

उस जल के तल में ही निमग्न तत्क्षण तुम हो जाना, प्रियतम ! 
उपलब्ध वहाँ तुमको निरुपम दो स्वतः वस्तु होंगी, प्रियतम ! 
उनको लेकर नृपपत्तन में सीधे तुम चल देना, प्रियतम !
वह दूत मिलेगा पथ में ही प्रेषित उस राजा का। प्रियतम॥३५५॥

ऐसा ही हुआ और गुरुवर थे महासिद्ध पहुँचे, प्रियतम !
वे लिये हुए थे साथ वही, जो वस्तु मिली उनको, प्रियतम ! 
नीली-प्रतिमा थी एक और था, एक पुरट-पत्ता, प्रियतम ! 
पुरइन की आकृति का, जिसपर अक्षर थे लिखे हुए, प्रियतम॥३५६॥

वह दान-पत्र ही था सचमुच भावी दहेजवाला, प्रियतम !
तेरे बाबा की सही, भला, उस पर पहले से थी। प्रियतम ! 
अङ्कित थी उसपर तिथि, जो थी उस दिन धनतेरस की, प्रियतम !
साखीथे गुरुवर और तरणि उनके थे चिह्न बने। प्रियतम॥३५७॥

की सभी व्यवस्था अग्रिम अब गुरुदेव महोदय ने, प्रियतम !
उस ओर गोपराजा को था होने यह भान लगा, प्रियतम ! 
श्रीनारायण का नीराजन संध्या में करते ही, प्रियतम !
मानो श्रीविग्रह मणिमय वह मुसकाकर कहता हो, प्रियतम॥३५८॥

हे वत्स ! बुलाता है तुमको वह नृपति धर्मभाई, प्रियतम !
कुलगुरु को साथ लिये तुम तो प्रस्थान तुरंत करो। प्रियतम !
प्रेषित गोपेश यहाँ आये दो घड़ी रात जाते, प्रियतम ! 
उन शकट-बली वर्दों में था मानो बल उड़ने का, प्रियतम॥३५९॥

मिलकर, बातें कर, भाव विकल वे धर्मबन्धु रोये, प्रियतम ! 
दोनों कुलगुरुवर का निर्णय अपने-ही-आप हुआ, प्रियतम !
बस, अभी प्रतिष्ठित हो प्रतिमा सुन्दरी वाटिका में, प्रियतम ! 
हो दानपत्र यह नित्य जड़ा प्रतिमा-पद के नीचे। प्रियतम॥३६०॥

तुम दोनों बहिनों की सँभाल करती मैं यहाँ रही, प्रियतम !
तेरी मैया, तेरे बाबा, ब्रजराज, महामुनि दो, प्रियतम !
पाँचों, तेरे श्रीभैया को आगे कर, वहाँ गये, प्रियतम !
हो अर्धनिशा, उससे पहले पूरा सब कृत्य हुआ, प्रियतम॥३६१॥

चौदस के प्रातः तुम दोनों बाहर खेलने गयीं, प्रियतम !
करके साँवरा कलेवा जब कानन में चला गया, प्रियतम !
लेकर संगिनी एक आयीं वे गोपराज-रानी, प्रियतम !
दो तथा इधर से हम पहुँचीं उद्यान-सुन्दरी में, प्रियतम॥३६२॥

चारों, न निहार-निहार थकीं प्रतिमा की सुन्दरता, प्रियतम ! 
गोपेश-गेहिनी के सुत की आकृति वह विधिकृत थी, प्रियतम !
दिन में तो तरणि-किरण को वह नीलाभ बना देती, प्रियतम ! 
साढ़े चौबीस रात में शशि उससे निस्सृत होते। प्रियतम॥३६३॥

उसदिन से ही उद्यान अहो ! प्रायः अदृश्य रहता, प्रियतम ! 
वन फेरी देते, देती थीं जो उन दो तिथियों में, प्रियतम ! 
उनमें जिसको भी देवी का दर्शन हो जाता था, प्रियतम ! 
उसको ही ज्योतिर्मय वह, पल-दो-पल दीखता भला, प्रियतम॥३६४॥

गुरुवरने चलते समय कहा तेरी मैया से था, प्रियतम ! 
मैं पास खड़ी थी, मुद्रा थी गम्भीर बड़ी उनकी, प्रियतम ! 
अपनी इन दो दुहिताओं की, रानी ! सँभाल रखना, प्रियतम ! 
निश्चित उस एक अवधितक ये उस वन में जायँ नहीं। प्रियतम॥३६५॥

तेरी बुढ़िया नानी, जो है जननी हम बहिनों की, प्रियतम ! 
उसने ही आज दुपहरी में आकर है यहाँ कहा, प्रियतम ! 
ये चपल छोरियाँ घुसती हैं उस वन की सीमा में प्रियतम ! 
तेरी मैया अत्यधिक इसे सुनते ही घबरायीं। प्रियतम॥३६६॥

उसने मुझको भेजा, दौड़ी मैं उस वन में पहुँची, प्रियतम ! 
कोई न मिली तुम, किंतु वहाँ थक गयी खोजकर मैं, प्रियतम ! 
आखिर लौटी, रवि-मन्दिर में तुम सब थी खेल रही, प्रियतम ! 
मैंने न कहा कुछ तुम सबको चुपचाप चली आयी, प्रियतम॥३६७॥

तुम भी तुरंत पहुँची, तेरी मैया भी खीझ उठी, प्रियतम ! 
है हेतु यही, है पता नहीं यह किन्तु लाड़ली को, प्रियतम ! 
गुरुवर की रुचि का ही पालन मंगलकारी होगा, प्रियतम ! 
जाकर उसको सब बतला दे, तू बड़ी सयानी है। प्रियतम॥३६८॥

मौसी इन बातों को मुझसे जिस समय कह रही थी, प्रियतम ! 
केवल दस-बीस हाथ हटकर तू भी तो थी बैठी। प्रियतम ! 
उसका स्वर था पर धीमा, मुँह तू तथा फुलाये थी, प्रियतम ! 
घटना रहस्यपूरित यह तू इसलिये न सुनपायी। प्रियतम॥३६९॥

मैं चली तुझे कहने यह सब, इतने में ही बाबा, प्रियतम ! 
आ गये वहाँ, उनसे लालित हो कर तू मान गयी, प्रियतम ! 
ब्यारू के लिये तुरंत तथा फिर हम सब जा बैठीं, प्रियतम ! 
बातों में मैं फँस गयी और कहना यह भूलगयी। प्रियतम॥३७०॥

अतएव यही प्रतिमा है, जो तब हुई प्रतिष्ठित थी, प्रियतम ! 
तू देख, यहाँ दिनकर की हैं किरणें नीली-नीली। प्रियतम ! 
है स्वर्णपत्र भी जटित अहो ! चरणों के वह नीचे, प्रियतम ! 
संयोग देखने का इसको अपने-ही-आप लगा। प्रियतम॥३७१॥

‘अब तू कह, किधर चलें ?’ कहकर अनुजा पल तीन रुकी, प्रियतम !
चिन्तित-सी बड़ी बहिन उसको उत्तर कुछ दे न सकी, प्रियतम ! 
सहसा उसके मुखसे निकला-‘वे गयीं कहाँ सखियाँ’, प्रियतम ! 
आये ये शब्द कि टूट गयी पूरी समाधि उसकी, प्रियतम॥३७२॥

दीखा जगते ही, सम्मुख है सर वही मिष्टजल का, प्रियतम ! 
घबरायी-सी होकर सखियाँ हैं उसे निहार रही, प्रियतम ! 
तोता भी द्रुम-डाली पर है वैसे ही निरख रहा, प्रियतम !
शीतल समीर का झोंका वह वैसा ही है अब भी, प्रियतम॥३७३॥

पूछा सहचरियों ने, कैसा अनुभव री ! हुआ तुझे ? प्रियतम ! 
क्या कहती वह, बरबस पानी आँखों में भर आया, प्रियतम ! 
इच्छा न तनिक भी अब उसकी आगे बढ़ने की थी, प्रियतम ! 
आयी थी जिस पथ से वनमें, उससे ही लौट पड़ी, प्रियतम॥३७४॥

आयी झाडी मेंहदी की वह दक्षिण सीमावाली, प्रियतम ! 
नृपपुत्री ने उदास मन से उसको ज्यों पार किया, प्रियतम ! 
आया, बस, कीर वही उड़कर, करके प्रणाम बोला, प्रियतम ! 
‘संदेश एक है श्रीपद में उन नीलदेवता का। प्रियतम॥३७५॥

सेवा न बनी कुछ भी सचमुच अरसिक मुझ किंकरसे, प्रियतम ! 
अपनी ही ओर देख, उरमें अविचल निवास देना, प्रियतम ! 
है नहीं मनोभ्रम, सच्ची है घटना सब इस वन की, प्रियतम ! 
माला है झूल रही उरपर, झूलेगी नित्य तथा।’ प्रियतम॥३७६॥

वह वायुकोणमें कीर उड़ा, कहकर इतना-सा ही, प्रियतम ! 
घर चली नृपति-पुत्री, अपना मन रखकर वन में ही, प्रियतम ! 
सब बोल रही थीं सखियाँ, वह बोली न किंतु कुछ भी, प्रियतम ! 
ढ़ाँचा वह भाव-तड़िच्चालित तन का था लौट रहा, प्रियतम॥३७७॥

आते ही घर मैया उर में भरकर, दृगधारा से, प्रियतम !
नहलाकर, ‘कैसे क्या देखा वनमें ?’ पूछने लगी, प्रियतम !
औरों ने बात कही, किंचित् छोटी छोरी ने भी, प्रियतम ! 
केवल नीरव वह एक रही, कह सकी न, बड़ी लली, प्रियतम॥३७८॥

उद्यान महल से सटा हुआ जो था विशाल उसका, प्रियतम ! 
उसमें ही जा बैठी उस दिन हो जाने पर संध्या, प्रियतम ! 
था प्रिय एकाकी पन उसको सर्वथा आज अब तो प्रियतम ! 
उस वन की वह नीली प्रतिमा मानो सम्मुख ही थी, प्रियतम॥३७९॥

तोतेके द्वारा प्रेषित वह संदेश देवता का, प्रियतम ! 
उसके कानों में गूँज रहा मधुभरा निरन्तर था, प्रियतम ! 
त्वक् और नासिका, रसना में अनुभूति भरी वह थी, प्रियतम ! 
जो भुजा समर्पण के क्षण में उसको थी वहाँ हुई, प्रियतम॥३८०॥

दो घड़ी बीतते ही सखियाँ उसके समीप आयीं, प्रियतम ! 
उसको न किंतु दीखीं सब वे क्षणभर भी खड़ी वहाँ, प्रियतम !
उन पाँच-सात की संख्या में नीली-प्रतिमा ही है, प्रियतम ! 
उसको यह अनुभव हुआ और विस्मय में थी डूबी, प्रियतम॥३८१॥

बातें कितनी ही बार-बार कह गयीं न जाने वे, प्रियतम !
कानों में कोई भी उनकी वह उक्ति न किंतु गयी, प्रियतम ! 
हैं ओंठ हिल रहे, बोल रही नीली-प्रतिमा ही है, प्रियतम !
‘प्रियतमे ! वल्लभे ! प्राणेश्वरि !’ यों, थी प्रतीति उसको, प्रियतम॥३८२॥

अविलम्ब महल में ले जाना उसको आवश्यक था, प्रियतम !
जैसे उस सखी सयानी ने उसका कर अब पकड़ा, प्रियतम !
मेरा है किया हस्त धारण नीली-प्रतिमा ने ही, प्रियतम ! 
यह लगा और अनुभूति हुई प्राणस्पर्शी सुख की, प्रियतम॥३८३॥

विश्राम-कक्ष में उसको वे ज्यों-त्यों कर ले आयीं, प्रियतम !
थी बहिन कनिष्ठा लगा रही सुरभित विलेप तन में, प्रियतम !
यह भान हुआ उसको, सौरभ नीली प्रतिमा में है, प्रियतम ! 
उससे झर कर भर रहा और मेरे अङ्गों में है, प्रियतम॥३८४॥

ब्यारू न करा पायीं सखियाँ, तब अनुजा ने अपनी, प्रियतम ! 
अधजूठ मिठाई वह उसके ओठों पर तनिक रखी, प्रियतम ! 
है अधर-सुधा यह तो सचमुच नीली-प्रतिमा की ही, प्रियतम ! 
होने यह भान लगा उसको, खाती वह चली गयी, प्रियतम॥३८५॥

वैसे ही उसे पिलाया फिर जल भी अनुजा ने ही, प्रियतम ! 
वैसे ही भुला-भुलाकर ही वह पान खिला पायी, प्रियतम ! 
है प्रीति-दान यह तो मुझको नीली-प्रतिमा का ही, प्रियतम ! 
उसकी प्रतीति थी क्रमशः यह गाढ़ी होती जाती, प्रियतम॥३८६॥

थी एक पहर रजनी बीती, सहसा वह उठ बैठी, प्रियतम !
अपनी ही अहो ! हथेली पर जा टिकी आँख उसकी, प्रियतम ! 
दीखी वह पूरी-की-पूरी नीली-प्रतिमा-जैसी, प्रियतम !
ऊपर वह बाहुमूल तक था पूरा कर ही नीला, प्रियतम॥३८७॥

दो-तीन पलों के अन्तर से उसने लहँगा अपना, प्रियतम ! 
सरका कर हेतु भरे दृग से देखा अपने पद को, प्रियतम !
वे गुल्फ और घुटने सब थे नीली-प्रतिमा जैसे, प्रियतम ! 
वैसा ही नीलापन पूरित पूरे चरणों में था, प्रियतम॥३८८॥

जाते न एक पल जाते ही उसको यह भान हुआ, प्रियतम !
नव चिह्न किशोरीपनका वह कोई न अङ्ग में है, प्रियतम ! 
‘मेरा तन भी यह पूरा है नीली प्रतिमा जैसा, प्रियतम ! 
आभूषण के बदले यह है वैसे ही वेणु धरे।’ प्रियतम॥३८९॥

थी दशा एक-दो पल तक तो उसकी विचित्र-सी थी, प्रियतम ! 
इस ऊहापोह-भँवर में था उसका मन उलझ गया, प्रियतम ! 
रमणी हूँ या सर्वथा पुरुष, नीली-प्रतिमा ही हूँ, प्रियतम ! 
परिवर्तन है सच यह अथवा हो रही भ्रमित मैं हूँ, प्रियतम॥३९०॥

आगे आधा पल मुँदी रही पलकें आधी उसकी, प्रियतम ! 
निर्णय उसको मिल गया और मन लीन हुआ उसमें, प्रियतम ! 
वह पर्यवसित मैं-पना हुआ नीली-प्रतिमा में ही, प्रियतम ! 
सब ओर वहाँ अब फैल गयीं नीली-नीली लहरें, प्रियतम॥३९१॥

उसके पश्चात नीलिमा की अव्यक्त परिस्थिति का, प्रियतम ! 
आगे फिर संविन्मयी उसी नीली रस-सत्ता का, प्रियतम ! 
जिसमें अप्रतिम पीतिमा भी वह नित्य विराजित है, प्रियतम ! 
अज्ञेय भला वह है, उसका, कैसे निर्देश करूँ, प्रियतम॥३९२॥

जब शरद-निशा वह बीत चुकी पहली सित परिवा की, प्रियतम ! 
अपने उस राज-तनूजा के तनको वह पकड़ सकी, प्रियतम !
मैया, मौसी, सब सहचरियाँ भारी चिन्ता में थीं, प्रियतम ! 
जो हुआ अचानक परिवर्तन उसमें, लेकर उसको, प्रियतम॥३९३॥

मैया कहती तू बतला दे, क्या हुआ लड़ैती री ! प्रियतम ! 
जो भी चाहेगी तू, तुझको दूँगी अवश्य वह मैं, प्रियतम ! 
क्या कहे लड़ैती उसकी, अब कोई भी रुचि न रही, प्रियतम ! 
जा मिली चाह उसकी सारी उन नील-देवता में, प्रियतम॥३९४॥

व्यवहार संतुलित कोई सा उसका न आज भी था, प्रियतम ! 
जब सखी पान कर पर रखकर बोली,‘बतला, क्या है ?’ प्रियतम ! 
उसने उत्तर यह दिया, ‘तडित् वारिद में रहती है’, प्रियतम ! 
‘पहले वह किंतु चमकती है, जलधर तब झरता है।’ प्रियतम॥३९५॥ 

सहचरी अलक-रचना करने आयी, प्रस्ताव किया, प्रियतम ! 
पहले तो बोली कुछ न, तथा बोली तब कह बैठी, प्रियतम ! 
‘प्रियता में सुख है, सुख में है प्रियता, स्वभाव से ही, प्रियतम ! 
क्यों भेद अहो ! फिर नित्य बढ़ें, ये इसीलिये तो हैं’, प्रियतम॥३९६॥

‘क्यों अरी ! सुमन लेकर अर्चन करने न जायगी तू ?’ प्रियतम ! 
बोली लघुसखी, सुना उसने या नहीं, कौन जाने, प्रियतम ! 
धीमा स्वर निकला,‘दी किसने यह बुद्धि पपीहे को’, प्रियतम ! 
‘मैंने या उनने या पाली उसने अपने से ही’ प्रियतम॥३९७॥

अनमनी हुई वह बैठी थी, सम्मुख थे फूल खिले, प्रियतम ! 
कुछ कहा सहेली ने, पर वह कुछ और समझ बैठी, प्रियतम ! 
बोली,‘यौवन ऐसा ही है, जैसे ये खिलते हैं’, प्रियतम ! 
‘है नियम नहीं, अलि रस पीले प्रत्येक पुष्प का ही।’ प्रियतम॥३९८॥

यों तीस घड़ी जाकर आयी दूजी तिथि की रजनी, प्रियतम ! 
उसके प्रत्येक पहर में वह भावित हो भाग चली, प्रियतम ! 
पहले में दीखा, वे आये लेकर चम्पकमाला, प्रियतम ! 
झट डाल कण्ठ में चले, चली वह भी पीछे उनके, प्रियतम॥३९९॥

ले हार चमेली का दीखे वे खड़े दूसरे में, प्रियतम !
लेकर गजरा तीसरे पहर यूथी का वे आये, प्रियतम !
चौथे में जवाकुसुम की थी माला शोभित कर में, प्रियतम !
उनका रसदान उषा का वह अत्यन्त निराला था, प्रियतम॥४००॥

उसके पश्चात लोचनों से उसके जो स्रोत चला, प्रियतम!
चालीस पहर, दो घड़ी, भला, झरता ही सतत रहा, प्रियतम !
मानो वह राजसदन अब तो उसमें ही बूड़ चला, प्रियतम ! 
आया अलक्ष्य रक्षा कर तब उन नीलदेवता का, प्रियतम ॥४०१॥

प्रातः था वही बहुश्रुत शुक आया उस कोने से, प्रियतम ! 
बोला- ‘श्री-पद में प्रणति सरस उनकी पल-पल शत है’, प्रियतम ! 
‘है और विनम्र निवेदन यह उनके अन्तस्तलका’, प्रियतम ! 
‘प्रियतमे ! रखो धीरज, मुझसे अब नित्य मिलन होगा।’ प्रियतम॥४०२॥

‘पूरे हो रहे इसी क्षण हैं बारह शुभ मास, भला’, प्रियतम ! 
‘उन्मत्त हुए मुनि थे तुमसे ले रहे विदा, तब से’, प्रियतम !
‘उनका प्रदत्त वरदान वही उसमें निमित्त होगा’, प्रियतम !
‘जय हो!जय हो! निरवधि जय हो!श्रीचरण-सरोरुह की’ प्रियतम॥४०३॥

शीतल अवनीश-नन्दिनी के वे अश्रु हुए पल में, प्रियतम ! 
आनन-सरोज मुरझाया वह खिल उठा अहो ! फिर से, प्रियतम ! 
क्रन्दन-विराम का हेतु नहीं मिल सका किसी कोभी, प्रियतम ! 
प्लावित पर अब सुख से सब थे, हँस रहे तरणि भी थे, प्रियतम॥४०४॥
''',
      ),
      BookPage(
        title: 'पञ्चम शतक',
        content: '''थे अतिथि हुए कोपन अतिशय, ऋषि एक नृपति-गृह में, प्रियतम ! 
दाढ़ी थी लंबी पिङ्गलाभ, सिर पर थी बँधी जटा, प्रियतम !
तप का था तेज भरा उनके लोचन में, अङ्गों में, प्रियतम !
हुत्भुक था मानो मूर्तिमान, इतने तेजस्वी थे प्रियतम॥४०५॥

अवनीश गिरे चरणों में आ, रानी ने पद धोये, प्रियतम !
विधिवत् अर्चा करके उनकी, कर जोड़, खड़े वे थे, प्रियतम !
गम्भीर हुए-से मुनि बोले- ‘राजन् धर्मज्ञ सुनो’, प्रियतम !
‘रहना है सोलह पहर मुझे इस गृह में जहाँ कहो।’ प्रियतम॥४०६॥

सोती थी जहाँ राजपुत्री, प्रासाद-कक्ष वह था, प्रियतम !
सबसे सुन्दर, नृपने उनको ठहराया उसमें ही, प्रियतम ! 
‘जब एक घड़ी ध्यानस्थ यहाँ एकाकी मैं रह लूँ, प्रियतम !
आकर फिर तुम सेवा करना’ कहकर मुनि बैठ गये, प्रियतम॥४०७॥

करके प्रणाम राजा उनको, चल पड़े वहाँ से, हे प्रियतम !
सीधे आये कुलदेवी के मन्दिर में दौड़े-से, प्रियतम !
परिचित मुनि के स्वभाव से थे, अतएव भीत मन से, प्रियतम ! 
कह,‘पाहि, जननि !’ सिर टेक दिया विग्रह के चरणों में, प्रियतम॥४०८॥

मुसकान कनकमय विग्रह के अधरों पर भर आयी, प्रियतम ! 
वीणा से भी मीठी वाणी होने फिर व्यक्त लगी, प्रियतम ! 
‘चिन्ता न करो तुम, वत्स ! सुखद मिलना होगा इनका’, प्रियतम ! 
‘अपनी दोनों दुहिताओं को आगे कर यह कहना’, प्रियतम॥४०९॥

‘मुनिपुंगव ! जो है पुत्र एक, अत्यन्त चपल वह है’, प्रियतम ! 
‘सेवाके योग्य चार हम हैं, चारों को या दो को’, प्रियतम ! 
‘स्वीकार करें, होऊँ कृतार्थ पाकर पद की सेवा’, प्रियतम !
‘जगजननी की रुचि है पर यह, पुत्री पर दया करें।’ प्रियतम॥४१०॥

निश्चिन्त नृपति रानी को ले, पुत्री युग को आये, प्रियतम ! 
लोचन मुनि के जब खुले, तभी वैसी ही की विनती, प्रियतम ! 
कन्या थी बड़ी गौर वर्णा, साँवरी कनिष्ठा थी, प्रियतम ! 
ज्यों दृष्टि पड़ी, मुनि के तन में विद्युत-सी व्याप गयी, प्रियतम॥४११॥

आसन को छोड़ उठे, कम्पित था रोम-रोम उनका, प्रियतम ! 
थीं पलकहीन आँखें, अञ्जलि बँध गयी अचानक थी, प्रियतम ! 
क्या हुआ, पता क्या, अचरज में पड़कर रानी-राजा, प्रियतम ! 
करबद्ध खड़े थे, हँसती थी पर कन्या वह छोटी, प्रियतम॥४१२॥

डरकर रानीने कर रखकर ढक दिये अधर उसके, प्रियतम ! 
आकुल मुनिने संकेत किया, हाथों को नचा-नचा, प्रियतम ! 
छेड़ो मत, इसको करने दो, करती जैसे यह है, प्रियतम ! 
चल पड़ा आँसुओं का प्रवाह अब था दृगसे उनके, प्रियतम॥४१३॥

वह आम्रमञ्जरी-प्राशन की दो नगर वासियों की, प्रियतम !
नीली लहरों वाली तटनी तट पर की होली की, प्रियतम !
रसमयी पञ्चमी की लीला छप्पन शुभ मास तथा, प्रियतम !
दिन एक आज से पहले की ली देख तपोधन ने, प्रियतम॥४१४॥

आराधन पञ्चदेवता का नाना उपचारों से, प्रियतम !
हो रहा वहाँ पर था, रानी सहयोग दे रही थीं, प्रियतम !
प्यारी प्राणोंसे बढ़कर उस अलबेली बेटी की, प्रियतम !
रक्षाका भार सभी रखकर अपनी अनुजा पर ही, प्रियतम॥४१५॥

उस समय लली की वयस मास सत्रह में थे घटते, प्रियतम ! 
दिन तीन; किन्तु अब भी वह थी आँखें मूँदे रहती, प्रियतम ! 
वह एक नाम सुनकर अवश्य कुछ देर खोलती थी, प्रियतम ! 
वह भी तबसे आये जब थे वे मुनि वीणाधारी, प्रियतम॥४१६॥

अथवा आती जब थीं अपने अप्रतिम लाल को ले, प्रियतम ! 
गोपेश-गेहिनी-शिशु-तनका सौरभ मिलता रहता, प्रियतम ! 
उसके दृग-नलिन खुले रहते तब तक, वह किंतु जहाँ प्रियतम ! 
ओझल होता, पलकें तुरन्त मुद्रित हो जाती थीं, प्रियतम॥४१७॥

थे उसी प्रकार सलोने दृग खुलते, मीलित होते, प्रियतम ! 
गोदी में उसको लेकर थी मौसी यह सोच रही, प्रियतम ! 
कम्पित होकर, पुलकित होकर, भरकर जल लोचन में, प्रियतम ! 
रह-रहकर तन-सुधि भी खोकर, बहकर रस-वारिधि में, प्रियतम॥४१८॥

होती जो एक अतुल ऐसी सुषमाशालिनी अहो, प्रियतम ! 
इसकी ही छोटी बहिन, भला, सुखदा सहोदरा ही, प्रियतम !
 मैं उसे अङ्कमें लिये सदा रहती या इसको ही, प्रियतम !
भगिनीके वक्षःस्थलपर यह शोभित या वह रहती, प्रियतम॥४१९॥

मनमें यह अभिलाषा जगकर होगयी विकल मौसी, प्रियतम ! 
तत्काल अनुग्रहमयी गिरा नभवाली गूँज उठी, प्रियतम ! 
यह है त्रिकालसच, जननि, इसे छूकर चाहो कुछ भी प्रियतम !
मिलती ही है वह वस्तु, परम मंगल एवं होगा प्रियतम॥४२०॥

मौसी के तन-मन फूल उठे, उस ओर हुई पूरी, प्रियतम ! 
देवों की सविधि अर्चना वह, ढप लगे तथा बजने, प्रियतम ! 
आकाश बना अरुणाभ, हुआ रवि-किरण-जाल धुँधला, प्रियतम ! 
आटोप अबीर-गुलाल रचित हो चला घना क्रम से, प्रियतम॥४२१॥

उस दिन के उस अतिशय विशाल जन-समारोह में, हे प्रियतम !
क्षणभर के लिये लली उतरी मौसी की गोदी से, प्रियतम ! 
इतने में सभी रमणियों ने, जो थीं अहीरपुर की, प्रियतम !
रसभेंट लिये, रानी को, फिर मौसी को घेर लिया, प्रियतम॥४२२॥

हो गयी लली कुछ दूर अहो ! वैसे ही दृग मूँदे, प्रियतम ! 
ओठों पर थी मुसकान, भला, देती करताली थी, प्रियतम ! 
गा रही तथा कुछ थी धीरे, स्वर था इतना मीठा, प्रियतम ! 
भर चली मत्तता प्राणों में सबके अजान में ही, प्रियतम॥४२३॥

‘मैं कौन, कहाँ पर हूँ, क्या है करना मुझको’, भूले, प्रियतम ! 
अञ्जलि में लिये गुलाल तरल सब-के-सब दौड़ चले, प्रियतम ! 
उस ओर जहाँ थी लली सृजन करती रस की सरिता, प्रियतम ! 
नव-नव कुछ लहरों का सुन्दर आवर्त चित्र लिखती, प्रियतम॥४२४॥

‘ठहरो, ठहरो ! क्या करते हो ? राजा की यह बेटी’, प्रियतम ! 
‘है खड़ी यहाँ, पिस जाती यह, होता जो मैं न यहाँ’, प्रियतम ! 
स्वर उसी अनोखे बालक का, आभीरराजसुत का, प्रियतम ! 
सहसा सुखमत्त हुए सबके कानों में ध्वनित हुआ, प्रियतम॥४२५॥

ज्यों-के-त्यों सब रुक गये तथा दीखा यह सम्भव-सा, प्रियतम ! 
समवेत तरुण-तरुणी-वयस्क, सबके दृग छलक उठे, प्रियतम ! 
हँसता था केवल एक वही छोरा अहीर-नृप का, प्रियतम ! 
रानी की सुता रूप उसका पी रही दृगों से थी, प्रियतम॥४२६॥

पन्द्रह-सोलह पल जब बीते, प्रकृतिस्थ हुईं रानी, प्रियतम !
बोलीं एवं हँसकर, ‘मेरे रे लाल, नैनतारा, प्रियतम !
तूँ ही था, तूँ ही है, आगे निरवधि तूँ ही होगा, प्रियतम !
हरदम सँभाल रखनेवाला मेरी इस बेटी की।’ प्रियतम॥४२७॥

लोचन खिल उठे सभी के, ज्यों यह उक्ति सुनी सबने, प्रियतम ! 
इतने में वही नीलसुन्दर बालक फिर बोल उठा, प्रियतम !
आँखें मटकाकर रानी से,‘दो पुरस्कार अब तो, प्रियतम ! 
दोगी तुरंत, या ले जाकर मुझको अपने गृह में ? प्रियतम॥४२८॥

सस्ते छूटोगी, दे दोगी जो अभी यहीं कुछ भी, प्रियतम ! 
ले गयी कदाचित् घर पर तो दूना देना होगा, प्रियतम ! 
है एक लाभ इसमें अवश्य, इन अहो ! लाड़िली के, प्रियतम !
लोचन फिर तो मुद्रित होंगे क्षणभर भी नहीं कभी।’ प्रियतम॥४२९॥

‘रे लाल ! भला, घर चलकर तो तूँ देख सही, क्या-क्या, प्रियतम !
देती हूँ मैं तुझको; पर फिर कुछ दिन रहना होगा, प्रियतम !
अपना पूरा घर सौंप, अहो ! सचमुच दूँगी तुझको, प्रियतम ! 
मनमानी तूँ करते रहना, रोकूँगी नहीं कभी।’ प्रियतम॥४३०॥

हँस पड़ी ठठाकर, कहकर, कर धरकर शिशु का, रानी, प्रियतम !
चलनेके लिये तुरंत हुआ सम्मत वह बालक भी, प्रियतम !
गोपेश-गेहिनी मुसकाकर बोलीं,‘साँवला अरे ! प्रियतम !
आवास करेगा उजियारा फिर कौन नित्य मेरा ?’ प्रियतम॥४३१॥

‘मैया री ! अच्छा, सुन ले यह, तूँ समझ नहीं पायी, प्रियतम !
 मैं एक साथ दोनों गृह में रह लूँगा, देख सही।’ प्रियतम ! 
आरसी एक चम चम करती थी पड़ी पास में ही, प्रियतम ! 
मरकत-साँवर छोरा बोला होकर समक्ष उसके, प्रियतम॥४३२॥

‘तेरे घर तो मैं स्वयं नित्य हूँ और रहूँगा ही, प्रियतम !
अब अहो ! प्रतिच्छाया मेरी, रानी को यह दूँगा, प्रियतम !
इनकी दृगपुतरी बेटीजी श्रीजी के साथ सदा, प्रियतम !
मेरी यह छाया भी खेले, मैं तो खेलूँगा ही।’ प्रियतम॥४३३॥

कुञ्चित केशों से घिरा हुआ वह मुख नीला-नीला, प्रियतम !
हो गया मनोहर कितना था उस समय, कहूँ कैसे, प्रियतम !
जब आँख डूबती है उसमें, वाणी रुक जाती है, प्रियतम ! 
चलती है जब वह, मोहनता उसको ठग लेती है, प्रियतम॥४३४॥

जो हो, रसमयी विनोद, अहो ! उस लघु वय के शिशु की, प्रियतम ! 
सुनकर विचित्र सबके मन की क्षणभर हो गयी दशा, प्रियतम ! 
अचरज था एक और भारी, सबको प्रतीति यह थी, प्रियतम ! 
‘मैं हूँ सन्निकट अवस्थित,वह इस भाँति कह रहा है।’ प्रियतम॥४३५ ॥

ढल पड़े देव दिनकर अब थे, फिर भी उल्लास नया, प्रियतम !
प्रतिपल अदम्य था जाग रहा सबके प्राणों में ही, प्रियतम ! 
गोरी छोरी, साँवर छोरा दृग में थे भरे हुए, प्रियतम ! 
हो भान कहाँ किसको कैसे इस दृश्य कालगति का, प्रियतम॥४३६॥

केवल थीं एक महारानी हो गयीं श्रमित मानो, प्रियतम ! 
हटकर उस जन-समूह से वे बाहर थीं आ बैठीं, प्रियतम ! 
गम्भीर सोचती-सी कुछ थीं, लोचन थे अर्ध खुले, प्रियतम !
लाड़िली अङ्क में थी राजित, मुट्ठी अपनी बाँधे, प्रियतम॥४३७॥

वह थी विनोद की बात, किन्तु रानी में समा गयी, प्रियतम ! 
बनकर लालसा बुद्धि-मन को मन्थन करने वाली, प्रियतम !
यह बने कदाचित् सम्भव सच जगजननी की रुचि से, प्रियतम ! 
परछाँही यदि वह आ सकती शिशु बनकर घर मेरे, प्रियतम॥४३८॥

हो जाती मैं निश्चिन्त उसे रखकर समीप इसके, प्रियतम ! 
यह खोल सलोनी आँखों को हँसकर खेला करती, प्रियतम !
आता क्षण वह जब कर-अम्बुज इसके पीले होते, प्रियतम ! 
वह छाँह साँवरा बनती या संगिनी नित्य इसकी, प्रियतम॥४३९॥

यह अहो ! चित्तधारा विरमित हो, उससे पहले ही, प्रियतम !
रानी की आँखों में शत दस दिनकर की ज्योति भरी, प्रियतम ! 
श्रीमहात्रिपुरसुन्दरी खड़ी नभ में थीं पूछ रही, प्रियतम !
‘है एक चाह भी अबतक जो पूरी न तुरंत हुई ? प्रियतम॥ ४४०॥

इन नील-देवता की छाया चिन्मयी अनूप हुई, प्रियतम !
कन्या बनकर उदरस्थल में तेरे प्रविष्ट होगी, प्रियतम !
रजनी है मंगलमयी परम पञ्चमी आज की जो, प्रियतम !
आनेवाली अब से होगी अप्रतिम सुहाग निशा।’ प्रियतम॥४४१॥

अन्तर्हित हुईं महादेवी, यह कहकर रानी से, प्रियतम ! 
फिर उसदिन के उत्सव का जब आया विराम शुभ था, प्रियतम ! 
नारीदल एक ओर, नरदल उससे कुछ हट करके, प्रियतम !
नीली सरिता में अवगाहन करने लग गया वहाँ, प्रियतम॥४४२॥

उस ओर महामाया ने दी रच एक नयी लीला, प्रियतम !
 हो गये महाराजा भावित रसमय कुछ भावों से, प्रियतम !
अप्रतिम जितेन्द्रिय थे, पर वे चञ्चल से क्षणिक हुए, प्रियतम ! 
फिर चाह तीसरी संतति की हो गयी प्रबल सहसा, प्रियतम॥४४३॥

पहुँचे जब घर पर, संध्या थी हो चुकी, खिन्न वे थे, प्रियतम !
जगदम्बा के पदपद्मों पर सिर रखकर वे रोये, प्रियतम !
संधिनी रूपिणी रानी में संवित् छाया नीली, प्रियतम !
वह हुई व्यक्त उस रजनी में, नृप तब सब समझ सके, प्रियतम॥४४४॥

ज्योतिर्मय यही अतीत दृश्य सब वर्तमान-जैसा, प्रियतम !
बनकर उन मुनि-पुंगव के था लोचन में समा गया, प्रियतम !
गोरी-साँवरी नृपति की दो छोरियाँ न दीखी थीं, प्रियतम !
वे परदेवता युगल उनको प्रत्यक्ष दीखते थे, प्रियतम॥४४५॥

पाकर मुनि का संकेत, नृपति, रानी को लिये हुए, प्रियतम ! 
बाहर उस सदर-कक्ष से थे आ गये, हाथ जोड़े, प्रियतम । 
भीतर रह गयीं पुत्रियाँ दो, मुनि ने आरम्भ किया, प्रियतम !
अर्चन उनका विह्वल होकर, वाणी के पुष्पों से, प्रियतम॥४४६॥

गम्भीर हुई गोरी छोरी सुनती थी श्लोकों को, प्रियतम ! 
उसकी भगिनी साँवरी किंतु रह-रहकर हँस देती, प्रियतम ! 
दो दण्ड बीतने पर सहसा मुनि की जब गिरा रुकी, प्रियतम ! 
श्यामा छोरी चपला उनसे बोली मीठे स्वर में, प्रियतम॥४४७॥

‘मुनिराज ! थक गये होगे सच अब तक तुम खड़े-खड़े, प्रियतम ! 
आसन पर बैठो, अहो ! श्रमित हो गयी खड़ी मैं तो।’ प्रियतम ! 
इतना-सा ही कहकर उनसे, कर-अलक कँपा करके, प्रियतम ! 
अपनी फिर बड़ी बहिन से थी कहने लग गयी भला, प्रियतम॥४४८॥

‘री ! तू चुपचाप देखती है, मुनिवर भूखे होंगे, प्रियतम ! 
ये कोस न जाने कितने हैं चलकर घर पर आये, प्रियतम !
तूँ पूछ सही, लायें क्या हम, किस पर इनकी रुचि है ? प्रियतम !
मेरे घर हैं तैयार नित्य वस्तुएँ सभी रस की’ प्रियतम॥४४९॥

गोरी ने मन्द-मधुर हँसकर समझाया भगिनी को, प्रियतम ! 
रहने के लिये अचञ्चल, फिर करबद्ध हुई बोली, प्रियतम ! 
‘ऋषिवर्य ! देव ! हम दोनों को पुत्रीवत् ही समझें, प्रियतम ! 
है पली लाड़ में श्यामा यह, बातूनी अतः बनी। प्रियतम॥४५०॥

अब आप विराजें, कृपा करें, सेवा सब बतलादें, प्रियतम ! 
मैं स्वयं करूँगी, पल-पल में उत्साह नवीन लिये, प्रियतम ! 
यह भी कुछ कर देगी, फिर जो भूलें होंगी हमसे, प्रियतम ! 
उनको तो क्षमा करेंगे ही, विश्वास सत्य यह है।’ प्रियतम॥४५१॥

वाणी क्या थी उसकी, मानो धारा थी सुधामयी, प्रियतम ! 
मुनिवर को, अहो ! और भी वह सुधिहीन लगी करने, प्रियतम ! 
इतने में पुनः साँवरी ने ऐसी चर्चा छेड़ी, प्रियतम !
सुनकर जिसको हँस पड़ी बड़ी बरबस ऊँचे स्वर से, प्रियतम॥४५२॥

हो गयी समाधि शिथिल मुनि की, दैवी प्रेरणा हुई, प्रियतम !
भावों का संधिस्थल आया, माया-सी फिर फैली, प्रियतम !
आकर्षण अहो ! छोरियों में यद्यपि था वैसा ही, प्रियतम !
असमोर्ध्व ईशता पर झीना आवरण एक आया, प्रियतम॥४५३॥

उन महातपोधन के उर में, ऊसर जो अबतक था, प्रियतम !
अंकुर अभिनव वत्सलता का जग उठा, अहो ! क्षण में, प्रियतम ! 
नृप-दुहिताओं के प्रति, निर्मल अत्यन्त ममत्व लिये, प्रियतम ! 
बढ़ते पल्लवित और पुष्पित होते न विलम्ब हुआ, प्रियतम॥४५४॥

मध्याह्न हो चला था, श्यामा कर धारण कर ऋषि के, प्रियतम ! 
बोली,‘तुम हुए नये बाबा हम दोनों बहिनों के, प्रियतम ! 
अब आज इसी क्षण से, जो सब सहचरी हमारी हैं, प्रियतम ! 
वे भी इस भाँति मानकर ही सर्वदा पुकारेंगी, प्रियतम॥४५५॥

हमसे है बड़ा सहोदर जो प्यारा अतिशय भाई, प्रियतम ! 
कानन में चरा रहा है वह इस समय धेनुओं को, प्रियतम ! 
संध्या होनेपर आयेगा, उससे भी कह दूँगी, प्रियतम ! 
वह और समस्त सखा उसके ऐसा ही मानेंगे, प्रियतम॥४५६॥

वे सब हैं पर अतिशय चञ्चल, जो छेड़ कहीं वे लें, प्रियतम ! 
तुम रुष्ट नहीं होना उनसे, उनका स्वभाव यह है, प्रियतम ! 
प्यारी अत्यन्त बहिन मैं हूँ उन सबकी ही, फिर भी, प्रियतम ! 
मुझको भी कभी-कभी सब वे देते है रुला, भला। प्रियतम॥४५७॥

अब चलो, सरोवर में तुमको हम दोनों नहलायें, प्रियतम !
जिसमें प्रतिदिन हमको मैया, मौसी नहलाती है, प्रियतम !
कमलों से भरा हुआ वह है, निर्मल जल है उसका, प्रियतम !
सुन्दर विहंग हैं नित्य वहाँ कलरव करते रहते।’ प्रियतम॥४५८॥

छोरी की सरस, सरल वाणी मुनिवर के प्राणों में, प्रियतम ! 
अनुपम मादकता थी क्रमशः भर रही, मौन वे थे, प्रियतम ! 
‘क्या करें, कहें क्या उसे ?’ नहीं निर्णय कर पाते थे, प्रियतम ! 
भावों की विमल नीर धारा आँखों से थी बहती, प्रियतम॥४५९॥

दोनों के हाथों में ऋषि ने अपने को सौंप दिया, प्रियतम !
‘जो रुचे करो।’ पल-पल उनकी अनुभूति बदलती थी, प्रियतम !
हैं नृपति-तनूजा, नहीं, अहो ! मेरी बेटी ये हैं, प्रियतम !
फिर इष्टदेवता की झाँकी उनमें होने लगती, प्रियतम॥४६०॥

वह बड़ी राजपुत्री हँसकर जैसे-तैसे मुनि को, प्रियतम !
ले गयी सरोवर पर सचेत कर-करके नहलाया, प्रियतम !
श्यामा ने अङ्ग पोंछकर फिर परिधान दिया उनको, प्रियतम ! 
जैसे कठपुतली हों, उनने धारण कर लिया उसे, प्रियतम॥४६१॥

मध्याह्न-कृत्य भी कहने पर कर गये यन्त्रवत् ही, प्रियतम ! 
ले आयीं उसी कक्ष में वे उनका कर-युग पकड़े, प्रियतम ! 
आसीन हुए जब वे, उनसे बोली नृपलली बड़ी, प्रियतम ! 
‘लाऊँ क्या, हे मुनीश ! अब मैं भोजन की सामग्री ?’ प्रियतम॥४६२॥

कह उठी कनिष्ठा बहिन,‘अरी ! भोली सचमुच तूँ है, प्रियतम ! 
हैं ध्यानमग्न मुनि, तो उनको तू व्यर्थ छेड़ती है, प्रियतम ! 
जैसे मैं कहती हूँ कर ले, चल, खीर बना लायें, प्रियतम ! 
खा लेंगे जो वे स्वयं, ठीक है; नहीं खिला देना।’ प्रियतम॥४६३॥

फिर भी जब रुकी रही, लोचन उनकी ही ओर किये, प्रियतम ! 
ढलकी मुनि-दृग से बूँद, मिली सम्मति हिलकर पलकें,प्रियतम ! 
हँसकर, आकर्षित लाली को करके, अनुजा बोली, प्रियतम !
‘तू कर विश्वास, बात मेरी ऋषि मान सभी लेंगे।’ प्रियतम॥४६४॥

वे चलीं, वहाँ पहुँचीं जननी थी जहाँ प्रतीक्षा में, प्रियतम !
उसकी ग्रीवा में झूल, लली साँवरी लगी कहने, प्रियतम !
जबतक उसकी अनुपस्थिति में बातें जो हुईं वहाँ, प्रियतम !
सुनकर अवाक् दस पल मैया रह गयी अचम्भे से, प्रियतम॥४६५॥

पायस-रन्धन की तैयारी उसने तुरंत कर दी, प्रियतम !
लाड़िली सलोने हाथों से प्रस्तुत कर ले आयी, प्रियतम !
समयोचित आसन आदि पूत विधिवत् सब रच कर के,प्रियतम ! 
फिर हाथ जोड़ करके ऋषि से विनती कर खड़ी रही, प्रियतम॥४६६॥

वे उठे विराज गये आकर, आचमन किया उनने, प्रियतम ! 
अग्रिम कर्तव्य तुरंत किंतु वे पुनः भूल बैठे, प्रियतम ! 
रच करके ग्रास लाड़िली ने अपने कर-सरसिज से, प्रियतम ! 
उनके मुख में रख दिया, अहो ! जय घोष हुआ नभमें, प्रियतम॥४६७॥

तन था गतिहीन, खा रहे थे वे खीर तथापि, भला प्रियतम ! 
लाड़िली खिलाने वाली थी, इसलिये हुआ ऐसा, प्रियतम ! 
अन्यथा दशा उनकी ऐसी हो गयी उस समय थी, प्रियतम ! 
पायस तो दूर, नीरकण तक भीतर न उतर पाता, प्रियतम॥४६८॥

आचमन करा कर लाली ने मुखवास दिया उनको, प्रियतम ! 
फिर नील सुकोमल मखमल की शय्या पर बैठाया, प्रियतम !
आरती लगी करने गाकर महिमा उनके तप की, प्रियतम ! 
अनुसरण साँवरी भी उसका कर रही सरसतम थी, प्रियतम॥४६९॥

जो भूत-भविष्यत्-वर्तमान माधुरी स्वरों की है, प्रियतम ! 
उसका उद्गम जो है, जिसको छू सकी न बुद्धि-गिरा, प्रियतम !
जो नित्य सनातन अद्भुत है मीठा अनुपम, उसको, प्रियतम ! 
पा लिया छोरियों के स्वर में उन महातपस्वी ने, प्रियतम॥४७०॥

क्षण में वे अन्तर्मुख होते, बाहर आते क्षण में, प्रियतम ! 
आखिर लग गये झूमने वे उठकर धीरे-धीरे, प्रियतम ! 
नीराजनपात्र लाड़िली के कर-नलिन-दलों से वे, प्रियतम ! 
लेकर विक्षिप्त चित्त होकर लग गये नृत्य करने, प्रियतम॥४७१॥

हँसकर साँवरी, तान भरकर, नूपुर रुनझुन करके, प्रियतम ! 
उस तालबन्ध पर ही उनको सहयोग लगी देने, प्रियतम ! 
जाने ही बिना मुनीश मत्त अब अहो ! लाड़िली की, प्रियतम ! 
करने प्रदक्षिणा लगे, लली लज्जित रह गयी खड़ी, प्रियतम॥४७२॥

लगभग जब सवा घड़ी बीती मुनिवर की आँख खुली, प्रियतम ! 
भौंचक होकर उन दोनों को लग गये देखने वे, प्रियतम ! 
आदर से बड़ी लली उनको बैठा करके, बोली, प्रियतम ! 
थे अभी, मुनीश ! आप भावित लोकोत्तर भावों से, प्रियतम॥४७३॥

बस, अतुल आपके निर्हैतुक, निस्सीम अनुग्रह से, प्रियतम ! 
उसका दर्शन कर हम दोनों हो गयीं निहाल, भला, प्रियतम ! 
अब समय आपके संध्योचित कृत्यों का आया है, प्रियतम ! 
कासार-कूलपर चलें, यहीं रहकर अथवा कर लें प्रियतम॥४७४॥

मुनि अन्यमनस्क हुए आये सुन्दर उस सर पर ही, प्रियतम ! 
मज्जन करके दिनकर को जब वे अर्घ्य दे रहे थे, प्रियतम ! 
रवि ढले अस्तगिरि में, उनके दृगपथ में आ न सके, प्रियतम ! 
वे नृपति-छोरियाँ ही नभ में हो रही अवस्थित थीं, प्रियतम॥४७५॥

हो करके चकित, दृष्टि उनने सर-तट पर तब डाली, प्रियतम !
वे ठीक वहाँ पर भी दोनों वैसी ही खड़ी मिलीं, प्रियतम !
दोनों ही ओर योगबल से अब एक समय में ही, प्रियतम ! 
देखा, युगपत् वे वहाँ और थीं यहाँ तीर पर भी, प्रियतम॥४७६॥

विस्मित अत्यन्त हुए, फिर तो उत्तर की ओर तथा, प्रियतम !
पूरब-दक्षिण, ऊपर-नीचे, चारों कोनों में ही, प्रियतम !
वे देख गये पल में, उनकी पर दृष्टि जहाँ पड़ती, प्रियतम ! 
वे दो नरपाललली उनको मिलती थीं खड़ी वहीं, प्रियतम॥४७७॥

मुनि के दृग से संसार हटा, बच गयीं ज्योतियाँ दो, प्रियतम !
थी एक नीलघन-सी, सुतप्त, कनकाभ दूसरी थी, प्रियतम !
हो गयीं सभी वृत्तियाँ लीन मन की उनके उनमें, प्रियतम !
अप्रतिम समाधि लगी उनकी वह सभी दृष्टियों से, प्रियतम॥४७८॥

निस्पन्द देह मुनिवर की थी, नृपललियों ने उसको, प्रियतम !
जल से बाहर लाकर, गीला परिधान बदल करके, प्रियतम !
फिर उसी जलाशय के तट के सन्निकट वेशगृह में, प्रियतम !
ले जाकर बैठा दिया और दोनों हो गयीं खड़ी, प्रियतम॥४७९॥

शारीरिक निस्पन्दता, अहो ! ज्यों-की-त्यों बनी रही, प्रियतम !
रजनी जाकर आयी शुक्ला सप्तमी शरद् पहली, प्रियतम ! 
दिन बीत गया, संध्या होकर वह रात पुनः बीती, प्रियतम ! 
हँसता प्रभात फिर था लौटा वह महाअष्टमी का, प्रियतम॥४८०॥

अब तक दो दण्ड जहाँ बीते, रानी-नृप आते थे, प्रियतम !
कुछ दूर अवस्थित रह कर ही सब ढंग देख लेते, प्रियतम !
श्यामा समीप जाकर भी सब बातें बतला देती, प्रियतम ! 
निश्चिन्त लौटते नृप, रानी चिन्ता करती जाती, प्रियतम॥४८१॥

जगदम्बा की अनुमति लेकर रानी चुपचाप वहाँ, प्रियतम !
षष्ठी-प्रदोष में, आगे के प्रातः, फिर संध्या में, प्रियतम ! 
बस, तीन बार जाकर अपनी दो, अहो ! बेटियों को, प्रियतम !
नहलाकर फिर शृङ्गार धराकिंचित् थीं खिला सकी, प्रियतम॥४८२॥

दो रात न सोयी बड़ी लली, प्रायः बैठी रहती, प्रियतम ! 
साँवरी बहिन की गोदी में सिर रखकर कुछ सोयी, प्रियतम ! 
छोटी के हठ कर लेनेपर लाड़िली लेट जाती, प्रियतम ! 
पल बीस-तीस, फिर उठ जाती, करके प्रसन्न उसको, प्रियतम॥४८३॥

जो हो, जब महा अष्टमी की दो घड़ी प्रथम बीती, प्रियतम ! 
मुनिवर की खुली समाधि, उठे धीरे-धीरे फिर वे, प्रियतम ! 
आ करके उस सर पर उनने कालोचित कृत्य किये, प्रियतम ! 
आये फिर राजभवन में वे दोनों को साथ लिये, प्रियतम॥४८४॥

वे अपने-आप वहाँ पहुँचे, रानी-अवनीश जहाँ, प्रियतम ! 
थे जोह रहे पथ पल-पल में बढ़ती उत्कण्ठा से, प्रियतम ! 
आठों अङ्गों से राजा ने प्रणिपात किया मुनि को, प्रियतम ! 
धरती पर बार-बार मस्तक रानी थीं झुका रही, प्रियतम॥४८५॥

भर आया कण्ठ तपोधन का, जैसे बोलने चले, प्रियतम ! 
कर उठे अभय मुद्रा में, पर लग गये काँपने वे, प्रियतम ! 
भर गया स्वेद भी अङ्गों में, भावित इस भाँति हुए, प्रियतम ! 
वे खड़े रहे बारह-चौदह पल तक आँखें मूँदे, प्रियतम॥४८६॥

जैसे-तैसे धीरज लाकर ललचाये लोचन से, प्रियतम ! 
श्रीमुख निहार कर बार-बार वे नृपति-छोरियों का, प्रियतम ! 
बोले,“हे रानी ! राजन् ! सच हो धन्य नित्य तुम ही, प्रियतम ! 
जो इन अप्रतिम पुत्रियों की माता हो और पिता, प्रियतम॥४८७॥

होने के लिये कृतार्थ परम मैं भी हूँ अतिथि हुआ, प्रियतम ! 
इस गृह में, जिसकी धरणी का कण-कण पावनतम है,प्रियतम ! 
छूकर इन दोनों के अभिनव पद अरुण सरोजों को, प्रियतम ! 
जिनका किञ्जल्क सुदुर्लभ है योगीश-मुनीशों को' प्रियतम॥४८८॥
क्षणभर वे रुके, और निकली रसमयी पुनः वाणी, प्रियतम ! 
जैसे प्रसंग की धारा को दे फेर शक्ति कोई, प्रियतम ! 
हे नृप दम्पति ! इनने मेरी सुन्दर जो की सेवा, प्रियतम ! 
कोई भी कर न सका अबतक, कर सकी नहीं कोई, प्रियतम॥४८९॥

मैं क्या इनको दूँ, किंतु सफल हो जाय वचन मेरा, प्रियतम !
इसलिये अवश्य कहूँगा कुछ दैवी इच्छा से ही, प्रियतम !
इस बड़ी लाडिली के कर से अब बने रसोई जो, प्रियतम ! 
तत्क्षण रुजापहर हो, अक्षय, सुस्वादु अनूप तथा, प्रियतम॥४९०॥

मुझको यह लगा, अभी मानो साँवरी कह रही हो, प्रियतम !
दिखलाकर अहो ! लाड़िली को, ‘वरदान मुझे देना, प्रियतम ! 
इसके प्रति पल-पल भाव, सदा अनुराग बढ़े मेरा’ प्रियतम !
बस, मैं भी ‘एवमस्तु’ कहकर देता हूँ यही इसे, प्रियतम॥४९१॥

जा रहा किंतु हूँ अब मैं तो, हे राजा ! हे रानी ! प्रियतम ! 
वे करुणामयी ललित अम्बा मुझको ले जायँ वहीं, प्रियतम ! 
होगा जो भाग पुनः मेरा, आऊँगा इस गृह में, प्रियतम !
देखूँगा आँखें भर-भरकर इन दोनों शिशुओं को।’ प्रियतम॥४९२॥

रुक गयी गिरा ऋषि की, रोने लग गये सिसक कर वे, प्रियतम ! 
रोने रानी लग गयीं, अहो ! रो उठे विकल राजा, प्रियतम ! 
वह भाव-उदधि उनके दृग से उमड़ा जो, अबतक है, प्रियतम ! 
दे रहा प्राण, वत्सलता से सम्पुटित ईशता को, प्रियतम॥४९३॥

साँवरी और लाडिली अहो ! मुनिवर से लिपट गयीं, प्रियतम !
‘बाबा ! बाबा ! तुम फिर आना’, कहकर, भरकर आँखें, प्रियतम !
मुक्ताएँ फिर झर-झर साँवर-गोरे गालों पर जो, प्रियतम ! 
फैलीं, उनको रो-रोकर मुनि लग गये चयन करने, प्रियतम॥४९४॥

जो क्रियाशील होती न कहीं रानी-नृप-मुनिवर में, प्रियतम ! 
उस समय अचिन्त्य शक्ति कोई शासित करनेवाली, प्रियतम ! 
आसन्न-अनागत-गत समस्त इस दृश्य तमाशे को, प्रियतम ! 
हो जाती अहो ! दशा दसवीं, उनकी व्याकुलता से, प्रियतम॥४९५॥

जो हो, प्रवाह यह भावों का हो गया नियन्त्रित-सा, प्रियतम ! 
ऋषिपद में गिरकर पुनः पुनः ललियों को साथ लिये, प्रियतम ! 
उत्तर के निर्झर तक उनको पहुँचा कर, अनुमति पा, प्रियतम ! 
रानी-नृप लौटे, पागल से मुनि समा गये वनमें, प्रियतम॥४९६॥

इसके पश्चात वर्ष पूरा होकर, फिर से आयी, प्रियतम ! 
तिथि यही शरद् की संध्या थी नवरात्र-अष्टमी की, प्रियतम ! 
महिषी-अवनीश चले गृह से ज्यों, वटु इतने में ही, प्रियतम ! 
आया आदेश लिये कुल के गुरुदेव महाऋषि का, प्रियतम॥४९७॥

आने की आवश्यकता अब तुम दोनों के न रही, प्रियतम ! 
सहचरी वर्ग के सहित युगल दुहिता के द्वारा ही, प्रियतम ! 
नवनीत-दूध-दधि-घृत, जितना वे बिना परिश्रम के, प्रियतम ! 
ढो सकें, भेज देना कल तुम दो घड़ी दिवस चढ़ते, प्रियतम॥४९८॥

अतएव सदा की भाँति वहाँ दोनों, वे नहीं गये, प्रियतम ! 
होते ही सुप्रभात, भरकर उन सभी वस्तुओं को, प्रियतम ! 
सोने के लघु-लघु कलशों में रानी ने भेज दिया, प्रियतम ! 
रखकर सिरपर कन्याओं के शत-शत सहचरियों के, प्रियतम॥४९९॥

वे चलीं राजपथ से पहले, फिर तो अरण्यपथ ही, प्रियतम !
सुन्दर उनको प्रतिभात हुआ टेढ़ी पगदंडी का, प्रियतम !
दोनों ही ओर लताएँ थीं फूलों से लदी हुई, प्रियतम !
अत्यधिक फलों का भार लिये हो रहे नमित तरु थे, प्रियतम॥५००॥

गा रहे विहङ्गम थे अगणित रागिणी सरस ऐसी, प्रियतम ! 
गन्धर्व-रमणियाँ भी जिसकी छू सकीं न छाँह कभी, प्रियतम !
सौ-दो सौ पद के अन्तर से निर्मित पावस-जल से, प्रियतम ! 
छोटे हृद शतशः थे, जिनमें प्रस्फुटित कंज अब थे, प्रियतम॥५०१॥

उड़कर गुन-गुन करता समूह भौंरों का आता था, प्रियतम ! 
थी सत्य रसीली मति उसकी अपहृत हो रही वहाँ, प्रियतम ! 
लाड़िली आदि सबके तन से निःसृत उस सौरभ को, प्रियतम ! 
पाकर उनके मुखको अभिनव अरविन्द समझ करके, प्रियतम॥५०२॥

वे इसी मधुर पथ से पहुँचीं आश्रम पर गुरुवर के, प्रियतम !
अर्चा उन सब कुमारियों की, ऋषि परम सिद्ध ने की, प्रियतम ! 
भावों की भेंट समर्पित कर, फिर पट रंगस्थल का, प्रियतम ! 
परिवर्तन कर, तन्मय होकर उनको कर दिया विदा, प्रियतम॥५०३॥

उत्तर की पगदंडी से वे लौटीं, रवि-कुण्ड मिला, प्रियतम ! 
श्यामा हठ कर बैठी, इसमें मैं आज नहाऊँगी, प्रियतम ! 
थी सदा साँवरी की रुचि जो, थी वही लाड़िली की, प्रियतम ! 
प्यारी सहचरी सयानी ने दी राय किंतु ऐसी, प्रियतम॥५०४॥

‘री ! क्यों न चलें फिर तो, अब वह अत्यन्त सन्निकट है, प्रियतम ! 
सुन्दरीसरोवर पर ही, जो रमणीय अप्रतिम है’, प्रियतम !
पीने भर पानी के बदले, निर्झर पीयूष मिले, प्रियतम ! 
दक्षिण कर बहिन लाड़िली का धरकर साँवरी चली, प्रियतम॥५०५॥
''',
      ),
      BookPage(
        title: 'षष्ठम शतक',
        content: '''ऋतु शरद् विराजित थी वन में, शुक्ला नौमी तिथि थी, प्रियतम ! 
प्रातःवेला थी बीत चुकी, संगव था हुआ अभी, प्रियतम !
सुन्दर अनेक शिशुओं को ले, जो समवयस्क सब थे, प्रियतम ! 
जा मस्त रहा था एक वहाँ बालक धीरे-धीरे, प्रियतम॥५०६॥

साँवर था, आगे-पीछे थीं उसके चलती गायें, प्रियतम ! 
रुकता रह-रहकर था किंचित्, फिर फूँक वेणु देता, प्रियतम ! 
ऐसी लहरी निःसृत होती, जो पूरित हो जाती, प्रियतम ! 
नभ में, समीर, रवि में, जल में, थल में, मन में, सबके, प्रियतम॥५०७॥

हो जाता धर्म-विपर्यय था चर-अचर-समूहों में, प्रियतम ! 
वह नाद मात्र बच जाता था, मिटकर सबकुछ मन से, प्रियतम ! 
बहती इतने में अन्य लहर, जो चेत करा देती, प्रियतम ! 
कौतुक होता था बालक का, हँसता वह देख इसे, प्रियतम॥५०८॥

‘भैयाओं ! एक जानता हूँ मैं मन्त्र रहस्यभरा, प्रियतम !
उसको पढ़कर वंशी में स्वर भर देता हूँ ऐसा, प्रियतम ! 
जो सुने, वही पागल-पगली हो जाय, और तो क्या, प्रियतम ! 
देखो इन पाँच तत्त्व पर भी इसका परिणाम भला’ प्रियतम॥५०९॥

कहकर साँवर ने दिखलाया रत्नों के पर्वत को, प्रियतम !
फिर गूँजा क्षणभर वेणु, अहो ! हीरे-पुखराज गले, प्रियतम !
पीली उज्ज्वल धारा बनकर बह चले सामने ही, प्रियतम !
गायें पीछेकी ओर कूद, लग गयीं रँभाने-सी, प्रियतम॥५१०॥

साँवर अब बायीं ओर मुड़ा नीलम-सी लहरें थीं, प्रियतम ! 
सरिता में उठती, उस पर भी उसने जादू डाला, प्रियतम ! 
पूरी प्रवाहिणी का ही जल पल में आवर्त बना, प्रियतम !
जम गया दूसरे क्षण फिर वह होकर हिम धरती-सा, प्रियतम॥५११॥

उन अगणित नीर-विहङ्गों के तन अक्षत रहकर भी, प्रियतम ! 
पद यन्त्रित थे हिम के भीतर, पाँखें, बस, हिलती थीं, प्रियतम ! 
आवर्तस्थल था दीख रहा वापी विशाल जैसा, प्रियतम ! 
जलचारी मत्स्य आदि सब थे निस्पन्द पड़े जिसमें, प्रियतम॥५१२॥

ऊपर थे पद्मबन्धु हँसते, हँस पड़ा साँवरा भी, प्रियतम ! 
ध्वनि हुई वंशिका से निस्सृत दिनमणि को लक्ष्य किये, प्रियतम ! 
वह शारदीय रवि-किरण राशि बन गयी सुधा शशि की, प्रियतम ! 
नवमी का दिवस-काल दस पल राका से भासित था, प्रियतम॥५१३॥

गति हुई धेनुकुल, खगकुल की, अलिकुल की, तरुकुल की, प्रियतम ! 
उतने क्षण रजनी कालोचित, दर्शक केवल शिशु थे, प्रियतम ! 
‘अब करो पूर्ववत् इनको’ यों बोले वे, बस, निकला, प्रियतम ! 
स्वर ललित, बह चला नीर सरित, उग उठे अंशुमाली, प्रियतम॥५१४॥

साँवर बोला,‘शीतल-सुरभित-जीवनदाता सबको’, प्रियतम !
‘है पवन, किंतु देखो मेरा जादू तुम इसपर भी’, प्रियतम !
‘जैसे ही मैं फूँकूँगा स्वर सम्मोहित कर इसको’, प्रियतम !
‘होगा यह लीन एक मेरी नासा-मुख वंशी में’, प्रियतम॥५१५॥

ऐसा ही हुआ, सभी बालक अचरज में भरे हुए, प्रियतम ! 
लग गये देखने खेल, अहो ! क्या बात दूर पर की, प्रियतम !
प्रत्येक सखा को अनुभव था हो रहा, न चलती है, प्रियतम ! 
उनकी ही साँस, किंतु तब भी जीवित सब थे सुख से, प्रियतम॥५१६॥

पल बीस-पचीस बीतनेपर गतिशील समीर हुआ, प्रियतम ! 
सुनकर रसमयी तान फिर से, शिशुओं ने प्रश्न किया, प्रियतम ! 
‘हम अरे ! कन्हैया भैया ! थे कैसे सब बचे हुए ? प्रियतम ! 
है सुना, श्वास रुक जाने पर मर जाता है प्राणी।’ प्रियतम॥५१७॥

हँस-हँसकर समाधान उनका कर रहा साँवरा था, प्रियतम ! 
देखो, वंशी के छिद्रों से जो सुधा बरसती है, प्रियतम ! 
कोई भी क्षणभर एक बार सपने में भी पी ले, प्रियतम ! 
हो जाता है वह सदा अमर, तुम नित्य पी रहे हो। प्रियतम॥५१८॥

निर्मल था व्योम, दृष्टि उसपर अब गयी साँवरे की, प्रियतम ! 
बोला,‘है ऐसा कौन, गगन जो ले समेट नख में, प्रियतम ! 
मैं अभी बजाकर वंशी यह करके दिखलाता हूँ, प्रियतम ! 
नभ, बायें पद अनाम नख में मेरे आ सिमटेगा।’ प्रियतम॥५१९॥

धारा-सी मधुकी क्षणभर फिर बह चली वंशिका से, प्रियतम ! 
इतने में जो अनुभूति हुई प्रत्येक सखा शिशु को, प्रियतम ! 
है सत्य अनिर्वचनीय शाख-शशधर के न्याय कहूँ, प्रियतम ! 
अवकाशदानदाता केवल तुम एक बच रहे थे, प्रियतम॥५२०॥

अब पुनः बहा पीयूष सरित, तब भावसमाधि खुली, प्रियतम ! 
शिशुओं की, लगे नहाने वे सब झूम-झूम उसमें, प्रियतम ! 
शत-शत हंसिनी-हंस दौड़े, जल-खगगण उड़ आये, प्रियतम ! 
उस ओर सहस्त्र मयूरों के दल ने आ घेर लिया, प्रियतम॥५२१॥

रव भरते समय जिधर झुकती ग्रीवा थी साँवर की, प्रियतम ! 
दल मत्त विहङ्गों का तत्क्षण गतिशील उधर होता, प्रियतम ! 
पल-पल में सरस बदलती थी उनकी भङ्गीधारा, प्रियतम ! 
हाथों से पेट थामकर थे हँस रहे सभी शिशु वे, प्रियतम॥५२२॥

ज्यों होता क्षणिक विराम, अहो ! मधुभरे वेणुरव का, प्रियतम ! 
रह-रहकर, जान-बूझकर ही साँवर यह करता था, प्रियतम ! 
उस समय विहङ्गों में आती प्रेमोत्थित जड़िमा जो, प्रियतम ! 
पा सकीं न एक निदर्शन भी उसका ब्रह्माणी भी, प्रियतम॥५२३॥

टप-टप सुमिष्ट बूँदें तरुकी शाखा से, पल्लव से, प्रियतम !
फूलों से, बेलि समूहों से, झर रही निरन्तर थीं, प्रियतम !
स्वरलहरी के चालन से ही विहगों की चों-चों को, प्रियतम !
साँवर ऊपर कर देता था, बूँदें गिरतीं उनमें, प्रियतम॥५२४॥

बारी अब वन्य चतुष्पद की आयी रस लेने की, प्रियतम !
टेरी वंशिका साँवरे ने उस गहन वनस्थल में, प्रियतम !
हों हुए निमन्त्रित ऐसे वे, द्वीपी, करेणु-करिणी, प्रियतम !
भल्लूक-मृगी-मृग आदि दौड़ आ जुड़े वहाँ क्षण में, प्रियतम॥५२५॥

हैं बैरहीन ये नित्य यहाँ, शिशु सभी जानते थे, प्रियतम ! 
भय हुआ न किंचित् भी उनको चिहुँकी न गाय तक भी, प्रियतम ! 
एवं पयस्विनी अमृतमयी ज्यों प्रसरित पुनः हुई, प्रियतम ! 
वे हुए भाव-भावित चौपद, जैसे न कह सकूँगी, प्रियतम॥५२६॥

पल बीस-पचीस खेल कर-कर, रसमत्त बना उनको, प्रियतम ! 
साँवर ने स्वर संचालन से वन में फिर भेज दिया, प्रियतम ! 
शिशुओं ने पूछा,‘कान्हा रे ! कैसे ये चले गये’, प्रियतम ! 
‘दृग बन्द किये, वंशी जब थी बज रही यहीं, फिर भी’ प्रियतम॥५२७॥

साँवर के अरुणिम अधरों का सुस्मित वह हास बना, प्रियतम ! 
फिर तान एक मधुभरी छिड़ी, निर्णय शिशु कर न सके, प्रियतम ! 
पूरब से या दक्षिण से है, आ रही प्रतीची से, प्रियतम ! 
या उत्तर से कि धरातल से ध्वनि यह या ऊपर से, प्रियतम॥५२८॥

बोला साँवर,‘सर्वत्र समा जाती है स्वरलहरी’, प्रियतम ! 
‘मैं जिसको जहाँ जभी इसकी अनुभूति कराता हूँ’, प्रियतम !
‘उसको ही वहीं प्रतीति तभी होने लग जाती है’, प्रियतम ! 
‘तत्क्षण उसके तन-मन की गति होती है लीन वहीं’, प्रियतम॥५२९॥

ऐसे वंशी ध्वनि का प्रभाव शिशुओं को दिखलाता, प्रियतम ! 
हँस-हँसकर तथा स्वयं वह रस पीता मृगछौना-सा, प्रियतम ! 
चञ्चल साँवर बालक आया अतिशय सुरम्य वन में, प्रियतम ! 
था एक जहाँ कासार बृहत्, तट फटिक-विनिर्मित थे, प्रियतम॥५३०॥

उद्भासित् दिनकर-किरणों से सरसिज-संकुल जल था, प्रियतम !
थी तथा तड़िल्लहरी-जैसी आभा भी फैल रही, प्रियतम !
बाला एवं सहचरियों के अवगाहन की क्रीड़ा, प्रियतम !
निर्बाध चल रही थी, तरु थे झंकृत कङ्कण-रव से, प्रियतम॥५३१॥

कटि से ऊपर थे अङ्ग सभी आवरणहीन सबके, प्रियतम !
भीगी अलकों का जाल मात्र रह-रहकर ढक लेता,  प्रियतम !
अप्रतिम रूप की उन्मादी धारा को, भावों को, प्रियतम !
पौगण्ड-किशोर-सन्धि पर जो जगकर थे झाँक रहे, प्रियतम॥५३२॥

उस जलबिहार से अरुण हुए नयनों की सुषमा से, प्रियतम ! 
टोना-सी शक्ति बिखरती थी मोहित करने वाली, प्रियतम ! 
त्रिभुवन थिर जङ्गमको; यह भी छोड़ो, अचरज देखो, प्रियतम ! 
हो गयी रुद्ध गति वहाँ, भला, त्रिभुवन-मन-मोहन की, प्रियतम॥५३३॥

सचमुच था विश्वविमोहन वह सुन्दर साँवर छोरा, प्रियतम ! 
गायों को लिये अहो ! जैसे पहुँचा, ज्यों दृष्टि पड़ी, प्रियतम !
उन आर्द्रकुन्तलों से मण्डित आनन पर बाला के, प्रियतम ! 
वंशी चुप हुई, हुईं अपलक वे नित्य चपल आँखें, प्रियतम॥५३४॥

दो रसमय हृदयों के जब है आता क्षण जुड़ने का, प्रियतम ! 
उसका संयोग कहाँ, कैसे लगता है, क्या जाने, प्रियतम ! 
वे सरल दुधमुँहे-से शिशु, जो सहचर थे साँवर के, प्रियतम ! 
अतएव सखा की चादर को कर्षित कर वे बोले, प्रियतम॥५३५॥

‘भैया ! क्या है तू देख रहा, तेरे श्रीभैया की, प्रियतम !
बहिनें एवं उनकी सखियाँ हैं नहा रही सुख से, प्रियतम !
चल, चल, विलम्ब मतकर, आगे क्रीड़ा करनी हो तो, प्रियतम ! 
या यहीं नहाने की रुचि हो तेरी भी तो कह दे’, प्रियतम॥५३६॥

साँवर ने उत्तर नहीं दिया, ली दृष्टि हटा उसने, प्रियतम ! 
अविलम्ब उस तरफ से फिर वह चुपचाप चल पड़ा भी, प्रियतम ! 
प्रतिदिन के निर्धारित पथसे पूरब की ओर बढ़ा, प्रियतम !
उल्लास नित्य रहता, उसकी छाया तक पर न रही, प्रियतम॥५३७॥

शिशुओं ने किया प्रयास अथक, जिससे हँस पड़े सखा, प्रियतम ! 
कृत्रिम मुसकान कभी क्षणभर होठों पर, पर आती, प्रियतम ! 
कोई कौतुक न हुआ अतुलित, लग सकी न होड़ तथा, प्रियतम ! 
उनमें वह वेणु बजाने की या शृङ्ग फूंकने की, प्रियतम॥५३८॥

आने पर छाक उसे लेकर साँवर अवश्य बैठा, प्रियतम !
भोजन-रस लेनेवालों का मण्डल भी वहीं बना, प्रियतम !
केवल दो ग्रास लिये पर जब उस दिन साँवरने ही, प्रियतम !
खाते कैसे शिशु वे, सब कुछ सामग्री पड़ी रही, प्रियतम॥५३९॥

कोमल तृणराशि हरित पर थीं गायें सब घूम रही, प्रियतम ! 
अपने चालक-दल से चालित, उन भिन्न दिशाओं में, प्रियतम ! 
अपराह्नकाल तक कानन में, गिरिवर के, परिसर के, प्रियतम ! 
वे भी पर सत्य पेट भरकर चर सकीं न आज भला, प्रियतम॥५४०॥

साँवर की अकस्मात ऐसी अत्यन्त उदासी के, प्रियतम !
कारण का मित्रमण्डली वह अनुमान लगाती थी. प्रियतम !
कोई सोचता कहीं क्या तो मुझसे ही भूल हुई, प्रियतम !
या और किसी शिशु से चिढ़कर हो रहा खिन्न यह है, प्रियतम॥५४१॥

आती यह बात किसीके थी मन में भोरेपन की, प्रियतम ! 
‘क्षणभर में, अहो ! अलक्ष्य नजर लग सकती है इसको, प्रियतम ! 
इसलिये सदा मैया जैसे करती है, मैं कर दूँ’, प्रियतम ! 
गोपुच्छ फिरा साँवर पर वह परिणाम देखता था, प्रियतम॥५४२॥

श्रीभैया तथा उसीने जब संकेत किया अपने, प्रियतम !
उस मित्र सुबल सद्गुणशाली शिशु को तब, बस, ये दो, प्रियतम !
थे बात जान पाये सर पर आँखों के मिलने की, प्रियतम !
साँवर की और बहिन भोरी गोरी सहोदरा की, प्रियतम॥५४३॥

जब लगा प्रतीची क्षितिज देव रवि का स्वागत करने, प्रियतम ! 
साँवर गो शिशुओं को लेकर वासस्थल पर आया, प्रियतम ! 
प्रतिदिन वंशीरव सुन पड़ता उपवन की सीमा से, प्रियतम ! 
नीरव आगमन किंतु उसका था आज यही पहला, प्रियतम॥५४४॥

उद्विग्न हुए सब-के-सब ही आ गये ग्रामवासी, प्रियतम !
मैया छाती से लगा उसे बेहाल हो रही थी, प्रियतम !
अपने अनमोल नीलमणि का आनन उदास इतना, प्रियतम !
उसने देखा था कभी नहीं अब तक सपने में भी, प्रियतम॥५४५॥

रोती जननी को देख हँसी सूखी साँवर हँसता, प्रियतम !
देता प्रबोध भी कहकर यह, री ! स्वस्थ सत्य मैं हूँ ! प्रियतम ! 
ब्यारू के लिये किंतु जब वह बैठा, तब जननी को, प्रियतम ! 
विश्वास करा न सका खाकर आधे का आधा ही, प्रियतम॥५४६॥

दशमी के प्रातः भी उसका वैसा ही हाल रहा, प्रियतम !
मैया के हाथों से प्रस्तुत नवनीत, दही मीठा, प्रियतम !
औंटाया हुआ दूध गाढ़ा, ओदन मिष्टान्न, सभी, प्रियतम ! 
वस्तुएँ कलेवा की जो थीं साँवर ने चख भर ली, प्रियतम॥५४७॥

गोचारण के मिस से तुरंत अटवी की ओर चला, प्रियतम ! 
टोली गायों की, मित्रों की वैसी ही संग चली, प्रियतम ! 
पर अन्यमनस्कपना जो था साँवर का कल-सा ही, प्रियतम ! 
शिशुओं से छिप न सका उसके किंचित् हँसने पर भी, प्रियतम॥५४८॥

दैनन्दिन वह अरण्य का क्रम गोसंरक्षण वाला, प्रियतम !
पूरा कर साँझ समय साँवर वैसे ही घर लौटा, प्रियतम !
था हुआ छाक-भोजन वन में, बस, नाम मात्र का ही, प्रियतम ! 
कहने के लिये पुनः उसने कर दी ब्यारू लीला, प्रियतम॥५४९॥

मैया कैसे धीरज धरती, थे प्राण विकल उसके, प्रियतम ! 
उन निपुण वैद्यवर को उसने बुलवाया छिप करके, प्रियतम ! 
भोरी थी वह, है नहीं, न था, होगा न कभी कोई, प्रियतम ! 
जो उसके नित्य निरामय उस शिशु की नाड़ी परखे, प्रियतम॥५५०॥

आयी अब एकादशी वही अंकुशरूपा अघ की, प्रियतम ! 
केवल मैया ही नहीं, अखिल पुरवासी व्रती हुए, प्रियतम ! 
संकल्प किया यह सबने, श्रीनारायण सदय बनें, प्रियतम ! 
नीरोग नीलसुन्दर हो, बस, निर्जल रह गये सभी, प्रियतम॥५५१॥

उस ओर दशा क्या थी मन की साँवर के, कौन कहे, प्रियतम ! 
दोनों वे सखा सयाने, बस, गति-विधि थे देख रहे, प्रियतम ! 
हृत्तल में उठी हुई लहरें प्रतिचित्रित हो जातीं, प्रियतम ! 
आनन पर, वह उनको रोके, कितना भी क्यों न भले, प्रियतम॥५५२॥

आया अब कर्णिकार-वन दृग उसके थे भर आये, प्रियतम ! 
पिङ्गल थी जहाँ शिला गिरि की, बैठा वह आज वहीं, प्रियतम ! 
अपने पीले दुकूल पर ही थी दृष्टि गयी उसकी, प्रियतम ! 
कम्पन था हुआ क्षणिक उसके दो बार कलेवर में, प्रियतम॥५५३॥

गहरी आँखों से अरुण नलिन-दलको उसने देखा प्रियतम ! 
प्रस्वेद कपोलों पर उसके तत्क्षण भर आया था, प्रियतम ! 
थी उड़ी हंसिनी जब जल-कण उच्छलित हुए कुछ थे, प्रियतम ! 
साँवरने ठीक उसी क्षण था अपना लिलार छूआ, प्रियतम॥५५४॥

पीने पिरोइनी आयी थी निर्मल जल सरिता का, प्रियतम ! 
लहरों के कुछ छींटे उसके मस्तक पर बिखर गये, प्रियतम ! 
किंचित्-सा कृष्ण-अंश उसके रोओं का भीग गया, प्रियतम ! 
साँवर था देख रहा, उसने अपनी अलकें छू लीं, प्रियतम॥५५५॥

दस पाँच सखा उसके जल में सहसा थे कूद पड़े, प्रियतम ! 
करने के लिये प्रसन्न उसे, तट पर था वह बैठा, प्रियतम !
भहरा उठती उनके मुख पर चिकुरावलि जब भीगी, प्रियतम !
जड़िमा साँवर के तन में थी सुस्पष्ट दीख जाती, प्रियतम॥५५६॥

जो उसी जलाशय के समीप उतुङ्ग एक तरु था, प्रियतम ! 
दो दिवसों से उसके नीचे आकर रुक जाता था, प्रियतम ! 
वन जाते और लौटते भी आँखें उसकी उठतीं, प्रियतम ! 
सर-तट की ओर देख लेता, आहट-सी वह लेता, प्रियतम॥५५७॥

यों चतुर निरन्तर सहचर वे दोनों थे परख रहे, प्रियतम ! 
साँवर के मनोभाव को, पर रखकर सुगुप्त उसको, प्रियतम ! 
करते थे परामर्श छिपकर, दोनों किस भाँति करें, प्रियतम ! 
प्राणों के प्राण सुहृद्वर की, किंचित् सहायता भी, प्रियतम॥५५८॥

जो थीं कल्याणमयी अम्बा आदरणीया सबकी, प्रियतम !
गैरिकवसना कुटीरदेवी महिमा अपार वाली, प्रियतम !
अणिमादि सिद्धियाँ छाया में जिनकी लोटा करतीं, प्रियतम ! 
उनसे ये परिचित थे, इनपर थी कृपा बड़ी उनकी, प्रियतम॥५५९॥

दोनोंकी राय हुई, चलकर कह दें सब कुछ उनसे, प्रियतम ! 
वे परम अनुग्रहमयी हमें पथ उचित बता देंगी, प्रियतम ! 
है छिपा न कुछ उनसे, पर यह कर्तव्य हमारा है, प्रियतम ! 
स्वाहा हो जाय भले सब कुछ, साँवर को सुखी करें, प्रियतम॥५६०॥

इसलिये द्वादशी तिथि का जब अरुणोदय हुआ वहाँ, प्रियतम ! 
सर्वथा अलक्षित सबसे वे आश्रम पर जा बैठ, प्रियतम ! 
अम्बाके पद पर सिर रखकर बातें सब बतलायीं, प्रियतम ! 
वे हँसीं कुटीरवासिनी दे आलिङ्गन दोनों को, प्रियतम॥५६१॥


‘मैं अभी साथ चलती हूँ, तुम निश्चिन्त रहो, यह तो, प्रियतम ! 
आमुख है परम सुखद भावी सुन्दर उस अभिनय का।’ प्रियतम ! 
वे तेजोमयी उठीं कहकर पहुँचीं निमेष में ही, प्रियतम ! 
बालक दोनों का कर पकड़े आभीर-राजगृह में, प्रियतम॥५६२॥

साँवर की वह उदास मैया दौड़ी, पद पकड़ लिये, प्रियतम !
लोचन थे बरस रहे उसके, इस ओर भगवती के, प्रियतम !
फिर बँधे एक डोरी में हों एवं आकर्षित हों, प्रियतम !
यों हुए इकट्ठे सभी वहाँ पुर-नरनारी पल में, प्रियतम॥५६३॥

नीरव थे सभी, चित्त पर अब हो रहा प्रफुल्लित था, प्रियतम !
उन पर्णकुटीरवासिनी की इस समय उपस्थिति से, प्रियतम !
सबका अनुभव यह था, सबकी रुचि ये रख देती हैं, प्रियतम ! 
सर्वथा असम्भव को भी ये सम्भव कर देती हैं, प्रियतम॥५६४॥

प्राणों का प्राण साँवरा यह अब रोगहीन होगा, प्रियतम !
आयी हैं ये सच हम सबको देने ही भीख यही, प्रियतम !
ये बात जानने वाली हैं सबके अन्तस्तल की, प्रियतम ! 
प्रत्यक्ष हमारे व्रतका फल मिल रहा अभी यह है, प्रियतम॥५६५॥

जो हो, पल सात-आठ पूरित सुखसिक्त मनोरथ से, प्रियतम ! 
बीते जब, पर्णकुटीवाली देवी मुसका करके, प्रियतम ! 
साँवर की मैया के सिर पर कर वरद फेर करके, प्रियतम ! 
बोलीं रुक-रुककर कण्ठ अहो ! उनका भी भर आता, प्रियतम॥५६६॥

‘री गोपराजरानी ! अपनी जेठानी से कह दे, प्रियतम !
जो नगर महादेवी से है प्रतिपालित, वह उसमें, प्रियतम !
जाकर नरपाल-गेहिनी की वृद्धा उस जननी से, प्रियतम ! 
मिल लेगी, रहती है अब वह जामाता के घर ही, प्रियतम॥५६७॥

सुन्दर अत्यन्त उपाय एक निर्दोष अनोखा-सा, प्रियतम ! 
वृद्धा बतला देगी अतिशय तुम सबको सुखकारी, प्रियतम ! 
तूँ कर लेना, तेरा, मेरा, इस अखिल विश्व का ही, प्रियतम ! 
उरहार अमोल नीलमणि यह रोगी न कभी होगा।’ प्रियतम॥५६८॥

‘हे भगवति ! सही स्वस्थ मैं हूँ, मैया तो भोली है, प्रियतम ! 
मुझमें अत्यन्त मोहवश है चिन्ता करती रहती’, प्रियतम ! 
यह कहता, हँसता इतने में साँवर आ गया वहाँ, प्रियतम ! 
देवी के पद-वन्दन कर कुछ लज्जित-सा खड़ा हुआ, प्रियतम॥५६९॥

गैरिकवसना अम्बा ऊँचे स्वर से हँस पड़ीं भला, प्रियतम ! 
साँवर को अपने उर में ले, छूकर ठोड़ी उसकी, प्रियतम ! 
आँखें छलकीं पर नेह-लोर बाहर वह आ न सका, प्रियतम ! 
होकर संयत-सी फिर बोलीं वे लक्षित कर सबको, प्रियतम॥५७०॥

‘जननी यह नित्य साँवरे की अप्रतिम भागवाली, प्रियतम ! 
भोरी ही नहीं, बावरी भी हरदम सचमुच है ही, प्रियतम !
इसका पर लाल सलोना अब हो गया सयाना है, प्रियतम ! 
मानेगी क्या यह इतना भी कोई कहकर देखो।’ प्रियतम॥५७१॥

फिर तो देवी के अञ्चल में चञ्चल होकर अपना, प्रियतम ! 
श्रीमुख निलीन कर साँवर ने विनती-सी कुछ कर दी, प्रियतम ! 
केवल सुन सकीं उसे वे ही, स्वीकार कर लिया भी, प्रियतम ! 
‘ऐसा ही हो’-कहकर, सहला-सहलाकर कच उसके, प्रियतम॥५७२॥

जा बैठा साँवर अब अपनी मैया की गोदी में, प्रियतम ! 
मैया खिल उठी, प्रसन्न वदन लखकर अपने सुत का, प्रियतम ! 
सबका मन डूब गया नीले आनन्द-हिलोरों में, प्रियतम ! 
कल्याणी वे देवी फिर जब बोलीं तब चेत हुआ, प्रियतम॥५७३॥

‘री गोकुलेशरानी ! वन में इसको अब जाने दो, प्रियतम ! 
जो रुचे कलेवा जितना-सा, उतना ही आज करे।’ प्रियतम ! 
वृद्धा की बतलायी विधि वह आचरित हुई जैसे, प्रियतम ! 
उसके पश्चात् निरन्तर रुचि परिवर्द्धित होगी ही, प्रियतम॥५७४॥

वे महाप्रभावमयी समता-करुणा-वत्सलता की, प्रियतम !
विग्रहरूपा अम्बा इतना कहतीं-कहतीं लौटीं, प्रियतम !
तोरण तक साथ सभी उनके आये, इतने में ही, प्रियतम !
गिरते न पलक गिरते वे तो हो गयीं अदृश्य, भला, प्रियतम॥५७५॥ 

साँवर भी मैया से जल्दी-जल्दी लेकर छुट्टी, प्रियतम !
चल पड़ा धेनु आगे कर, फिर पथ में हँसकर बोला, प्रियतम !
‘भैयाओं ! स्वप्न एक सुन्दर मैंने गत रजनी के, प्रियतम ! 
उस ठीक अन्तवाले क्षण में देखा है, चलो, सुनो !’ प्रियतम॥५७६॥

प्राचीतट विशद सुरम्य उसी सुन्दरी सरोवर का, प्रियतम ! 
आ गया और साँवला लाल गोपाल वहीं बैठा, प्रियतम ! 
सहचरमण्डल की उत्सुक थीं आँखें द्रुमसुमनों से, प्रियतम ! 
झरता था मधु आरम्भ हई सपने की वह गाथा, प्रियतम॥५७७॥

वह उधर नीलसुन्दर की जो ताई थी जा पहुँची, प्रियतम !
देवीरक्षित महीपपुर के उत्तर की सीमा में, प्रियतम !
गिरिवर के सोते को उसने, बस, पार किया ही था, प्रियतम !
वृद्धा मिल गयी वहीं, जिससे मिलने आयी वह थी, प्रियतम॥५७८॥

किंचित् थी झुकी कमर उसकी, अब सितकेशी वह थी, प्रियतम ! 
थी ज्योति बनी दृगमें अब भी कुछ घट जाने पर भी, प्रियतम ! 
लाठी कर में लेकर चलती सब ओर घूम आती, प्रियतम ! 
सब खेर-नगर की जनता थी परिचित उस नानी से, प्रियतम॥५७९॥

वह बड़े स्नेह से मिली भला, साँवर की ताई से, प्रियतम ! 
स्वाभाविक बहुत बोलती थी, उसने ही पूछ लिया, प्रियतम ! 
‘कैसे तुम आज, अकेली हो आयी, प्रसन्न सब हैं ? प्रियतम ! 
वे लोग अहीरराजपुरके, है स्वस्थ नीलमणि तो ?’ प्रियतम॥५८०॥

अपने ही आप दैवगति से सुन्दर भूमिका बनी, प्रियतम !
बातें गत बीस पहर की सब ताई ने बतलायीं, प्रियतम !
सुन रही ध्यान देकर वह थी प्रत्येक बात को ही, प्रियतम !
थी जहाँ समझ न सकी, उसको दुहराकर पूछ लिया, प्रियतम॥५८१॥

सुनकर पर उन गैरिकवसना ऐश्वर्यशालिनी की, प्रियतम !
वह उक्ति रहस्यमयी शुचि, जो सम्बद्ध उसीसे थी, प्रियतम !
अत्यन्त पड़ी असमंजस में, उत्तर वह दे न सकी, प्रियतम !
आ गयी याद थी बात एक संवत्सर पहले की, प्रियतम॥५८२॥

‘आये थे पुत्री के घर ऋषि तेजस्वी एक महा, प्रियतम !
साँवरी दौहिती से मैंने उनकी बातें पूछीं, प्रियतम !
मेरी मनुहारों से दबकर उसने थी बतला दीं, प्रियतम !
वह बात सुगुप्त, लाड़िली को उनके वर देने की, प्रियतम॥५८३॥

देवीने जिसकी ओर किया संकेत यही वह है, प्रियतम !
आमयहारी उपाय निश्चित; पर जो मैं कह दूँ तो, प्रियतम !
मेरी साँवरी अहो ! मुझसे अत्यधिक रुष्ट होगी, प्रियतम ! 
विश्वासघातिनी कह-कहकर नाकों दम कर देगी, प्रियतम॥५८४॥

छोरा साँवरा उधर वह है रोगी हो रहा तथा, प्रियतम !
देवी-रुचि की हेला सम्भव है नहीं किसी से भी, प्रियतम !
जैसे-तैसे श्यामा को फिर आगे फुसला लूँगी, प्रियतम !
इसके अतिरिक्त और तो क्या कर सकती हुँ अब मैं ?’ प्रियतम॥५८५॥

इस भाँति घड़ी आधी तक वह चिन्ता में पड़ी रही, प्रियतम !
आखिर साँवर की ताई से उसने सब बात कही, प्रियतम !
दी राय और यह-‘साँवर को कुछ वस्तु खिला देना’, प्रियतम !
‘जो मेरी बड़ी दौहिती ने राँधी हो, उसमें से’, प्रियतम॥५८६॥

ताई तुरंत लौटी, मैया साँवर की बैठी थी, प्रियतम !
आकर आधे से कुछ आगे वन के उस पथ के ही, प्रियतम !
दोनों वे मिलीं, बात करके ताई फिर से आयी, प्रियतम !
अत्यन्त वेग से चलकर उस देवी-पालित पुर में, प्रियतम॥५८७॥

था डेढ़ पहर बाकी दिन अब, रानी अंतःपुर के, प्रियतम !
आँगन में थीं बैठी करती खिलवाड़ छोरियों से, प्रियतम !
दोनों बहनें खेलने आज बाहर थीं नहीं गयी, प्रियतम !
अच्छा संयोग लगा, पहुँची वह ठीक समय से ही, प्रियतम॥५८८॥

प्राणों का प्यार भरा सुखमय आलिङ्गन दे उसको, प्रियतम !
रानी ने आने का कारण पूछा, फिर सुनते ही, प्रियतम ! 
ले गयीं तुरंत लाड़िली की दादी के पास उसे, प्रियतम !
वह पितामही रहती अब थी केवल पति सेवा में, प्रियतम॥५८१॥

थे वृद्ध महाराजा प्रायः रहते समाधि में ही, प्रियतम ! 
दो-दो थे पहर बीत जाते, खुलती न आँख उनकी, प्रियतम ! 
प्रातः फिर अर्धनिशा में वे कुछ देर बोलते थे, प्रियतम ! 
दादी उस समय पूछ लेती, जो कुछ करना होता, प्रियतम॥५९०॥

अतएव परम सुन्दर निर्णय दादी ने यही दिया, प्रियतम ! 
‘लाली तुरंत अब आज यहीं रन्धन कुछ कर देगी, प्रियतम !
ब्यारू के समय नीलमणि को दे दो, प्रातः कल तो, प्रियतम ! 
मैं वहीं भेज दूँगी इसको, लेकर अनुमति इनकी। प्रियतम॥५९१॥

मेरी शत शुभाषीश कहना गोपेश-गेहिनी से, प्रियतम !
चिन्ता न करें, नीरोग नीलमणि नित्य रहेगा ही, प्रियतम !
लाली तो साँवर की ही निधि, साँवर जननी की है, प्रियतम !
चाहेंगी जब-जब वे, तब यह रन्धन कर आयेगी’, प्रियतम॥५९२॥

वैसा ही हुआ, द्वादशी के रवि गये अस्तगि रिमें, प्रियतम !
आकर वन से अलिन्द में जब साँवर खाने बैठा, प्रियतम ! 
वह एक कटोरा खीर जिसे ताई ले आयी थी, प्रियतम !
उसकी कैसी महिमा थी, यह जो देख सके, देखे, प्रियतम॥५९३॥

गोपेशपुरी के लोगों की चिन्ता हरने वाली, प्रियतम !
वह रात एक नूतन उत्सव जैसी होकर बीती, प्रियतम !
आने तक उषा, गूँजता था पत्तन के कण-कण में, प्रियतम !
‘श्रीमन्नारायण-नारायण’ रव सतत भरा स्वर में, प्रियतम॥५९४॥

वे महीपाल-गेहिनी उधर कुक्कुट-रव सुनते ही, प्रियतम ! 
बन्दन कुलदेवी का करके उठ पड़ी शीघ्रता से, प्रियतम ! 
निर्मञ्छन ललियों का कर, फिर उनको प्रबुद्ध करके, प्रियतम ! 
नहलाकर, अतुल वेषभूषा सुन्दर उनकी रच दी, प्रियतम॥५९५॥

आ पहुँचीं सब सहेलियाँ भी वैसी ही सजी-धजी, प्रियतम ! 
प्राची में दीखा-सा ही था ज्योतिर्मय रथ रवि का, प्रियतम ! 
मन्दिर में वृद्ध पितामह के एकत्र हुईं सब वे, प्रियतम !
आशीष लाड़िली को उनकी लेनी आवश्यक थी, प्रियतम॥५९६॥ 

दोनों उन अहो ! पोतियों पर, जो खड़ी सामने थीं, प्रियतम !
दादा की दृष्टि गयी, वे तो उठ पड़े अधीर हुए, प्रियतम !
था यही प्रथम अवसर उनके जीवन का, जो उनमें, प्रियतम !
हो गया देखते ही उनको आवेश मोह का-सा, प्रियतम॥५९७॥

कर्तव्यपरायण होकर भी निर्लिप्त सदा वे थे, प्रियतम !
था जन्म शाक्तकुल में उनका पर वैष्णवाग्र वे थे, प्रियतम !
क्षणभर भी पद्मनाभ-पद की विस्मृति न कभी होती, प्रियतम !
अब तो व्यवहार-जगत् से वे सर्वथा अलग-से थे, प्रियतम॥५९८॥

दादी ने हाथ पकड़ उनको आसन पर बैठाया, प्रियतम !
लाड़िली, साँवरी एवं सब जो खड़ी छोरियाँ थीं, प्रियतम !
वन्दना अङ्क में दादा के सिर रखकर सबने की, प्रियतम !
दादाजी के दृग से झर-झर बूँदें थीं बरस रही, प्रियतम॥५९९॥

कोई न समझ पाया, उनकी यह हुई अवस्था क्यों, प्रियतम !
संकेत अतःकर देती हूँ, दादा ने यह देखा, प्रियतम !
सच्चिदानन्द परतत्त्व, अहो ! अविषय मन वाणी का, प्रियतम !
गोरी-साँवरी-नीलसुन्दर, इनसे अभिन्न ही हैं, प्रियतम॥६००॥

है खेल अनिर्वचनीय और निरुपम अचिन्त्य इनका, प्रियतम । 
साँवर जिसको जितना-सा जब, दिखला दे, वह देखे, प्रियतम !
 उतना सा तभी, मर्म फिर भी अज्ञात रहेगा ही, प्रियतम ! 
अतएव नहीं पहचान सका अपनी पोती-युग को, प्रियतम॥६०१॥

ऐसी अनुभूति पितामह को हो गयी, और फिर वे, प्रियतम !
बह चले लहर में संविद् के ऊपर वत्सलता की, प्रियतम ! 
इच्छा थी सर्वनियन्ता की, दादाजी अब आगे, प्रियतम !
हों मग्न रसोदधि में, जो है वह परे ज्ञान से भी, प्रियतम॥६०२॥

हो जाय न कहीं विलम्ब, डेढ़ योजन जाना जो था, प्रियतम ! 
दादी ने उरसे लगा-लगा उन सबको बिदा किया, प्रियतम ! 
हो अहो ! जम्बुनदधारा के अन्दर से चमक रही, प्रियतम ! 
मानो सुवर्ण की राशि भला, इस भाँति चलीं वे सब, प्रियतम॥६०३॥

दूरी संकुचित अहो ! पथ की हो गयी सत्य सहसा, प्रियतम ! 
लाड़िली आदि सब जा पहुँचीं आधी घटिका में ही, प्रियतम ! 
साँवर की मैया ने सबका कैसा सत्कार किया, प्रियतम ! 
वाणी कहने का साहस कर कर देगी विकृत उसे, प्रियतम॥६०४॥

हो प्रबल चाह सुनने की यदि फिर भी तो यहाँ नहीं, प्रियतम ! 
आगे इस वनकी सीमा से दोनों हम जब पहुँचें, प्रियतम !
तुम याद दिला देना, लज्जा सर्वथा त्याग दूँगी, प्रियतम !
प्राणों में अङ्कित चित्रों का विवरण कर जाऊँगी, प्रियतम॥६०५॥

प्राणेश ! अभी तो इतना ही सुनकर सन्तोष करो, प्रियतम ! 
लाली ने सरस रसोई दी कर, एक घड़ी में ही, प्रियतम ! 
भोजन कर, वेणु बजाता वन साँवरा जा रहा था, प्रियतम ! 
मैया का प्यार अतुल लेकर लाली थी लौट रही, प्रियतम॥६०६॥
''',
      ),
      BookPage(
        title: 'सप्तम शतक',
        content: '''अश्वत्थ पुराना एक बड़ा पथ में विचित्र-सा था, प्रियतम ! 
पत्रावलि पतझड़ में उसकी गिरती थी नहीं कभी, प्रियतम ! 
रहता हरीतिमा का वह था अचरज का पुञ्ज बना, प्रियतम !* 
जन गाथा थी, हो व्यक्त वहाँ देवी बैठा करती, प्रियतम॥६०७॥

था नहीं काल का इसीलिये कोई प्रभाव पड़ता, प्रियतम ! 
उस तरु पर, तथा मनोरथ थे पूरित होते सबके, प्रियतम ! 
जिसकी जैसी इच्छा होती, उसको वैसी मिलती, प्रियतम ! 
परिणाम किंतु सबका होता मंगलमय परम सदा, प्रियतम॥६०८॥

रहने दो स्वप्न अनुक्त, यहीं इस पादप के नीचे, प्रियतम !
बालाने जो देखा, जब वह लौटी थी उस गृह से, प्रियतम ! 
विश्राम लगी करने वह थी सखियों के कहने से, प्रियतम ! 
क्षण एक मुँदी बस आँख, हुई अनुभूति रहस्यमयी, प्रियतम॥६०९॥

संकेत भले सुन लो, यद्यपि रस का सागर वह है, प्रियतम ! 
यह गिरा न जाने क्यों कुण्ठित हो रही अचानक है, प्रियतम !
कानन में विविध विहङ्गम हैं रस लोलुप, किंतु सभी, प्रियतम ! 
हैं रस-मर्मज्ञ नहीं पूरे, अतएव न समझेंगे, प्रियतम॥६१०॥

यह वही सिन्धु है, अबतक जो नापा जा सका नहीं, प्रियतम ! 
है गहरायी कितनी, कोई बतला न सका, न सकी, प्रियतम ! 
नीचे जितना जो गया, गयी, बढ़ती ही मिली उसे, प्रियतम ! 
वह मरा, मरी, जो बचा, बची, गूँगा, गूँगी वह है, प्रियतम॥६११॥

उस गूँगी  का इङ्गित कोई समझे, न समझ पाये, प्रियतम !
जो समझे, वह सब समझ गया, है नियम नहीं यह भी प्रियतम !
गूँगी तो यह निर्णय करने आयेगी नहीं कभी, प्रियतम !
बहरी तो थी ही, अंधी, फिर पगली हो जाती है, प्रियतम॥६१२॥
अस्तु, भगवत्याः योगमायायाः रंगस्थलोद्घाटनम्॥६१३॥
बालायाः स्वप्नारम्भः॥६१४॥
प्रियतमसम्बन्धविस्मृतिः॥६१५॥
द्विरागमनानुभूतिः॥६१६॥
अनुजया सहगमनम्॥६१७॥
दुर्मदस्य पथप्रदर्शनम्॥६१८॥
पथि अननुभूतवैवाहिकवृत्तस्य चिन्तनम्॥६१९॥
रविसेतुं प्राप्य तत्र स्थित्वा बालायाः दुर्मदं प्रति सविनयं आदेशदानम्॥६२०॥  
दुर्मदस्य तथैवाचरणम्॥६२१॥
रविमन्दिरदर्शनार्थं गमनं च॥६२२॥
बालायाः अनुजां प्रति स्वहृदयवेदनाकथनम्॥६२३॥
अनुजायाः क्रन्दनम्॥६२४॥
मिथो धैर्यप्रदानम्॥६२५॥
बालायाः ग्रामप्रवेशः॥६२६॥
गृहप्रवेशः॥६२७॥
देवीपूजनम्॥६२८॥
बालायाः वृद्धापदयोः पतनम्॥६२९॥
मूर्च्छा॥६३०॥
वृद्धाकृतविविधशीतलोपचारैः संज्ञालाभः॥६३१॥
आ पहुँची वही पर्णकुटियावाली देवी सहसा, प्रियतम !
बाला पहले की भाँति नहीं उनको पहचान सकी, प्रियतम !
केवल इतना-सा ही अनुभव उसको उस समय हुआ, प्रियतम !
मेरी रक्षा करनेवाली जग में अब ये ही हैं, प्रियतम॥६३२॥
देवीकूटोक्तिश्रवणेन बालायाः परित्राणाशा॥६३३॥
देव्याः सूर्यव्रतोपदेशः॥६३४॥
द्वादशवर्षीयनियमनिर्धारणम्॥६३५॥
वृद्धायाः सहर्ष अनुमोदनम्॥६३६॥
बाला का, उसकी अनुजा का दुस्सह परिताप मिटा, प्रियतम !
पाकर अभीष्ट देवी-पद में दोनों ही लोट पड़ीं, प्रियतम !
वे दयामयी लेकर उनको, चिपकाकर छाती से, प्रियतम !
रोने लगगयीं, स्नेह उर की सीमा में रह न सका, प्रियतम॥६३७॥
बालायाः सूर्यार्चनारम्भः॥६३८॥
संध्यायां सहचरीसमागमः॥६३९॥
द्वितीय दिवसे अर्चनार्थं पुष्पचयनम्॥६४०॥
उद्यानप्रवेशः॥६४१॥
उद्यानसौन्दर्यदर्शनम्॥६४२॥
प्रश्नः॥६४३॥
सहचर्याः उत्तरदानम्॥६४४॥
मानो था भरा सहचरी के उत्तर में टोना-सा, प्रियतम !
बाला का कर कम्पित होकर गिर गया पुष्प-दोना, प्रियतम !
एवं कुछ कहे बिना ही वह चल पड़ी वाटिका से, प्रियतम ! 
सीधे आकर कपाट गृह के कर लिये बन्द उसने, प्रियतम॥६४५॥
श्रवणयोः तन्मयता॥६४६॥
अनाहारः॥६४७॥
निशि च॥६४८॥
निद्राभावः॥६४९॥
रवौ उदिते सति सहचर्याः आगमनम्॥६५०॥
तस्याः बाला दशादर्शनेन महदाश्चर्यम्॥६५१॥
सहचरीस्नेहाग्रहरुद्धायाः बालायाः हेतुकथनम्॥६५२॥
आँखें उस नर्म सहेली की कारण वह सुनते ही, प्रियतम !
उल्लास सहानुभूति पूरित जलबिन्दु दान करती, प्रियतम !
संकेत मूक किंचित् देकर, चञ्चल कर बाला को, प्रियतम !
क्षणभर हो गयीं निमीलित, थीं अनुजा सब देख रही, प्रियतम॥६५३॥
अनुजाकृतसामयिकसेवा॥६५४॥
संध्याधिगमः॥६५५॥
मुरलीरव श्रवणम्॥६५६॥
रवप्रणेतारं प्रति आत्मनिवेदनम्॥६५७॥
चित्तस्य तन्नादमयत्वम्॥६५८॥
उषसि संध्याप्रदोषभ्रान्तिः॥६५९॥
देहविस्मृतिः॥६६०॥
अनुजा के किये उपायों से बाला को चेत हुआ, प्रियतम ! 
हो सका भोर के कृत्यों का निर्वाह अधूरा-सा, प्रियतम ! 
अनुजा सँभालती थी प्रतिपल, अतएव परिस्थिति को, प्रियतम ! 
वृद्धा न तथा उसकी न सुता आभास पा सकी थीं, प्रियतम॥६६१॥
अपराह्नसमये सहचर्याः चित्रपटदानम्॥६६२॥
बालायाः चित्रसौन्दर्यदर्शनम्॥६६३॥
विचित्रानुभूतिः॥६६४॥
तं अखिलरसामृतमूर्ति बालकं प्रति आत्मोत्सर्गः॥६६५॥
बुद्धेः तद्रुपत्वम्॥६६६॥
सर्वत्र तद्दर्शनम्॥६६७॥
तस्यां रजन्यां चित्तस्य अद्भुतवैक्लव्यम्॥६६८॥
बाला की चित्तदशा ऐसी हो गयी रातभर में, प्रियतम ! 
जिसको वह सखी देखते ही चिन्तामें डूब गयी, प्रियतम ! 
लक्षण उन्माद रोग के सब उसमें थे दीख रहे, प्रियतम !
अच्छा था यही, सखी को वह पहचान गयी अब भी, प्रियतम॥६६१॥
नामोच्चारणपूर्वकं मां मा स्पृश मा स्पृश इति उक्त्वा पलायनम्॥६७०॥
सहचर्याः समवरोधनम्॥६७१॥
बालायाः भृशं विलापः॥६७२॥
सहचर्याः सान्त्वनादानम्॥६७३॥
बालायाः शनैः शनैः स्वहृदयस्य अनिवार्य परिताप कथनम्॥६७४॥
सहचर्याः हासः॥६७५॥
बालायाः सरसभ्रान्तिनिवारणं च॥६७६॥
आ गिरी धधकती ज्वाला पर मानो जलधर-धारा, प्रियतम !
ऐसा परिणाम सहेली के उस एक वाक्य का था, प्रियतम !
सुखमयी अचेतनता के मृदुकर से लालित होती, प्रियतम !
थी पड़ी अङ्कमें उसके दस-पंद्रह पल तक बाला, प्रियतम॥६७७॥
सहचर्याः परिचयदानम्॥६७८॥
बालायाः भावाभिवृद्धिः॥६७९॥
सहचर्याः यथावसरं तं बालकं प्राप्य बालावृत्तकथनम्॥६८०॥
बालकस्य स्वानभिज्ञता प्रदर्शनम्॥६८१॥
देवसचतुष्ट्यानन्तरं बालां प्रति स्वाकर्षणाभावमूलकचेष्टा॥६८२॥
सहचर्याः भावविवर्द्धनार्थं विविध प्रयासः॥६८३॥
असफलता॥६८४॥
आखिर कुल-भय, लज्जा, गौरव, सब परित्याग करके, प्रियतम !
अपने सर्वस्व समर्पण का, अत्यन्त विवशता का, प्रियतम !
संकेतचित्र शुचि पत्ते पर अङ्कित कर नखमणि से, प्रियतम !
नीरद-सुन्दर उस बालक को बाला ने भी भेजा, प्रियतम॥६८५॥
तथापि नैराश्योपलब्धिः॥६८६॥
न भवति दुर्विपाकमूलेऽस्मिन् जन्मनि मत्प्राणनाथयोगः मम नवजन्मायुतमध्ये देवो दययिष्यत्यवश्यमेव इति बालायाः प्राणविसर्जनोपक्रमः॥६८७॥ 
कल्लोलिनीं प्राप्य प्रवाहनिरीक्षणम्॥६८८॥
सहचर्याः आगमनम्॥६८९॥
बालायाः तां आश्लिष्य क्रन्दनम्॥६९०॥
महाप्रयाणपाथेयरूपतच्चित्रपटदर्शनस्य कामना॥६९१॥
तद्पूर्तिः तस्य तत्रानुपलब्धेः॥६९२॥
यह सुख भी मन्द भाग्यवाली कैसे ले सकती है, प्रियतम ! 
मैं देख न सकी चित्र तक भी आराध्य देवता का, प्रियतम ! 
था उस दिन तो छवि से पूरित उरका कोना-कोना, प्रियतम ! 
देखूँ वे कहीं मिलें, विलीन कर सकूँ प्राण उनमें, प्रियतम॥६९३॥
इत्युक्त्वा बालायाः नयननिमीलनम्॥६९४॥
सहचर्याः बालां अङ्के कृत्वा उच्चस्वरेण क्रन्दनम्॥६९५॥
तत्क्षणमेव तस्य महामरकतद्युतेः बालकस्य तत्रागमनम्॥६९६॥
जो नीलपद्म रसना हो फिर बन्धन न काल का हो, प्रियतम ! 
लेकर रसना-तूलिका चित्र लिखती मैं रह जाऊँ, प्रियतम ! 
जो सुखद सखी को, बाला को अनुभूति हुई, उसका, प्रियतम ! 
आ जाने से उस बालक के, तब भी न लिख सकूँगी, प्रियतम॥६९७॥

जैसे कोई कवि चुन-चुनकर कल्पना सरस अपनी, प्रियतम!
गुम्फित कर उसको माला में प्राणों में ही रख ले, प्रियतम ! 
सम्मान-गर्व के कर से वह अस्पृष्ट सर्वथा हो, प्रियतम ! 
जो है उल्लास भरा उसमें, आया वह दोनों में, प्रियतम॥६९८॥

पावन अनुरागमयी धारा दो, बह-बहकर दृगसे, प्रियतम !
इस देश-काल की सीमा से उस पार पहुँच करके, प्रियतम !
हो जायँ संगमित, उनमें जो शीतलता रहती है, प्रियतम !
थी आत्मसात् कर रही वही दोनों के प्राणों को, प्रियतम॥६९९॥

है नहीं अहंता जहाँ, नहीं है बुद्धि, न ये गुण हैं, प्रियतम ! 
है नहीं प्रकृति भी जहाँ, अहो ! केवल चिति-ही-चिति है, प्रियतम ! 
जो है गंभीरता नित्य वहाँ निरुपम अद्वयपन की, प्रियतम !
थी व्यक्त हो रही वही, भला, दोनों के प्राणों में, प्रियतम॥७००॥

कितना-सा समय लगा उनको इस कालमान से था, प्रियतम ! 
अब पुनः लौटकर आनेमें तत्रस्थ कलेवर में, प्रियतम ! 
जग उठे और सो गये अहो ! शतबार चतुर्मुख थे, प्रियतम ! 
इतना-सा या दो दण्ड मात्र तुम एक जानते हो, प्रियतम॥७०१॥

जो हो, रजनी के अञ्चल में बसने वाली सुषमा, प्रियतम !
उनके लोचन की पलकों को छू-छूकर धीरे से, प्रियतम !
संकेत लगी करने विशुद्ध रसकी उस पद्धति का, प्रियतम ! 
वे तभी प्रकृति अपनी-अपनी स्वीकार कर सके थे, प्रियतम॥७०२॥

तीनों के ही मुख से कोई निस्सृत न हुई वाणी, प्रियतम !
थी प्रणय-रोष की छाया-सी क्षणभर केवल आयी, प्रियतम !
चञ्चल-सी हुई सहचरी के मुखपर इतने में ही, प्रियतम !
आँखें उसकी उन दोनों के आननपर नाच उठी, प्रियतम॥७०३॥

बाला-बालक के गालों पर जो बनी लोर-रेखा, प्रियतम !
उसके ही अन्तराल से था उनका उर बोल रहा, प्रियतम !
सहचरी, भला, अब बालक को क्या उपालम्भ देती, प्रियतम !
लग गयी याद करने रसकी भाषा का ककहारा, प्रियतम॥७०४॥

साखी देता शशि था नभमें ऊपर उठकर तरु से, प्रियतम !
नीली प्रवाहिणी कल-कलकर शुभ गीत गा रही थी, प्रियतम ! 
धोरही सखी थी दृग-जलसे परिणय की वेदी को, प्रियतम ! 
विद्युल्लहरी का कर धारण कर कृष्ण-वारिधर था, प्रियतम॥७०५॥

निर्मल था स्वप्न, अहो ! पर यह था लिये अँधेरा भी, प्रियतम ! 
संकल्प न था इसमें, अद्भुत विक्षिप्तपना पर था, प्रियतम ! 
संविद् रसमय था, फिर भी था हृत्तल की आह लिये, प्रियतम ! 
बाला का तो सपना था, पर जीवन यह है रस का, प्रियतम॥७०६॥

उस सपने में ही जो सपना उसको था अन्य हुआ, प्रियतम ! 
कह देती हूँ किंचित् यदि कह पाऊँगी, हूँ रोती, प्रियतम ! 
प्राणोंको है अनुभूति, किंतु वे बोल नहीं पाते, प्रियतम !
अतएव जान सकता है वह, जो है अन्तर्यामी, प्रियतम॥७०७॥
''',
      ),
      BookPage(
        title: 'अष्टम शतक',
        content: '''जब उषा शयनगृह में आकर छू लेती बाला को, प्रियतम !
कहकर ‘रजनी अब चली गयी, दे रही उसे मैं हूँ, प्रियतम ! 
हृत्तल का प्यार, सोच में पड़, जो सो न सका, न सकी’, प्रियतम ! 
है स्वप्न मिलन या सच्चा ? तब खुलती समाधि उसकी,प्रियतम॥७०८

साँवर सहेज देते उसकी अलकें मुख पर बिखरी, प्रियतम ! 
आलस्य भरे उन दोनों की आँखें मिलती जब थीं, प्रियतम ! 
साँवर बन जाते थे बाला, साँवर होती बाला, प्रियतम !
वे प्राण नहीं, केवल उनकी थी देह बदल जाती, प्रियतम॥७०९॥

कङ्कण की ध्वनि सहचरियों की इतनेमें सुन पड़ती, प्रियतम !
पहले-जैसे हो जाते थे क्षणभर में दोनों ही, प्रियतम !
भीतर सब वे जब आ जातीं उनपर बलिहार हुई, प्रियतम !
लज्जित होकर अञ्चल से थी ढक लेती मुख बाला, प्रियतम॥७१०॥

मंगल-नीराजन करती थीं उनका सब सहचरियाँ, प्रियतम ! 
‘जोरी जीओ युग-युग’ कहकर सुखमत्त सभी होतीं, प्रियतम ! 
झर पड़ते बाला-साँवर के दृगसे जलके कण थे, प्रियतम ! 
रव भरा कणों में यह रहता ‘होंगे न उऋण तुमसे !’ प्रियतम॥७११॥

शीतल समीर सौरभ का ले उपहार विनय करता, प्रियतम ! 
‘अब चलो, युगल दम्पति ! तुम हे, कानन की वल्लरियाँ, प्रियतम ! 
पुष्पित हो, तरु से जुड़कर, हैं हिल-हिलकर देख रहीं, प्रियतम ! 
पथ तुम दोनों का, आशा ले, मुख देख निहाल बनें’, प्रियतम॥७१२॥

वे ज्यों बाहर आते, दौड़ी आती रंगिणी मृगी, प्रियतम !
बाला की कटि को छूकर थी संकेतों में कहती, प्रियतम !
‘हो चपल चतुष्पद देते हैं फेरी उन कुञ्जों की, प्रियतम !
अङ्गों की तुम दोनों के कल है गन्धभरी जिनमें।’ प्रियतम॥७१३॥

साँवर-बाला के अङ्गों की हरिताभ-पीत शोभा, प्रियतम !
अपने लोचन-अञ्चल में भर, होकर मदमाती-सी, प्रियतम !
दो घड़ी अभी पहले जब थी ले रही विदा रजनी, प्रियतम ! 
चकई चक से थी मिली हुई शशि से जो यह कहती, प्रियतम॥७१४॥

‘आना राकेश ! पुनः सुख से कूलों पर सरिता के, प्रियतम ! 
कोसेंगे ये दोनों पंछी, होना न भीत हमसे।’ प्रियतम !
बाला-साँवर हैं नित्य यहाँ, होंगे न विलग हम भी, प्रियतम ! 
दुःखद निसर्ग के नियम यहाँ लागू होंगे न कभी, प्रियतम॥७१५॥

चर्चा प्रतिदिन कुछ ऐसी ही रस की उनकी होती, प्रियतम ! 
उड़कर फिर शयन-भवन के थे आँगन में वे आते, प्रियतम !
सारी-शुक आँख गड़ाकर थे उनको देखा करते, प्रियतम !
दम्पति विहङ्गमुद्रा लखकर उन्मुक्त हँसी हँसते, प्रियतम॥७१६॥

शोभा देखते हुए वन की वे मन्द-मन्द गति से, प्रियतम !
चलते थे, आगे पीछे थीं चलती सब सहचरियाँ, प्रियतम ! 
फूलों से लदे हुए द्रुम की अवली से झरती थी, प्रियतम !
सुमनों की राशि-राशि, उसपर दम्पति पद रखते थे, प्रियतम॥७१७॥

वे झूम लताएँ उठतीं, जब बाला अपने करमें, प्रियतम !
लेकर साँवर के करमें थी उनको पकड़ा देती, प्रियतम !
कहकर ‘देखो, प्राणाधिक ! ये कैसी हैं शीलवती, प्रियतम ! 
है नहीं स्वसुख की गन्ध तथा इनमें, जय हो इनकी।’ प्रियतम॥७१८॥

सन्मुख कलिन्दनन्दिनी-कूल आ जाता इतने में, प्रियतम !
श्रीमुख तट की उज्ज्वलता में प्रतिबिम्बित हो जाता, प्रियतम !
बाला हो जाती भ्रमित, अहो ! ‘हैं हम सच्चे या ये’, प्रियतम !
साँवर हँसने लगते, तब वह थी भूल समझ पाती, प्रियतम॥७१९॥

मानो हंसिनी पीठपर थी लेने आयी उनको, प्रियतम ! 
ऐसी नाचती दीख जाती लहरों पर सित नौका, प्रियतम ! 
बाला साँवर को कर्षित कर उस दिव्य घाटवाले, प्रियतम ! 
पथ पर चलकर जल्दी से थी आरोहण कर जाती, प्रियतम॥७२०॥

अपने बायें करसे हँसकर थी डाँड़ थाम लेती, प्रियतम ! 
‘प्राणेश ! अहो ! देखो, कितना सुन्दर मैं खेती हूँ’, प्रियतम ! 
उसकी चितवन-वाणी में जो रस निर्झर पूरित था, प्रियतम !
साँवर को मत्त बना देता, उस पर ढल पड़ते वे, प्रियतम॥७२१॥

‘बलिहार अहो ! निकुञ्जरानी !’ कहकर सहेलियाँ वे, प्रियतम ! 
उत्साहित बाला को करती, दूसरी डाँड़ खेती, प्रियतम !
उससे वह बात छिपाने का करती प्रयास, फिर भी, प्रियतम !
लेती वह देख बोलती,‘क्या इतनी निर्बल मैं हूँ ?’ प्रियतम॥७२२॥

साँवर मुसकाकर कहते-‘री ! तुम सब छोड़ो, देखो, प्रियतम ! 
मेरे प्राणों की रानी से छू जाने का जादू, प्रियतम ! 
इनको छूकर मैं ही जब हूँ चञ्चल हरदम, फिर तो, प्रियतम ! 
यह डाँड़ चलेगी नाव तथा अपने-ही-आप, भला !’ प्रियतम॥७२३॥

लज्जित होकर बाला तुरंत थी हाथ हटा लेती, प्रियतम ! 
उस ओर सरित की धारामें परिवर्तन हो जाता, प्रियतम ! 
हिल्लोलित लहरों से होकर तरणी चल पड़ती थी, प्रियतम ! 
बाला को उरमें भरकर थे ‘जय-जय’ साँवर कहते, प्रियतम॥७२४॥

उजली युगलित वरटावलि, जल-कुक्कुटटोली काली, प्रियतम ! 
उड़-उड़कर नाव घेर लेती, फैला-फैला पाँखें, प्रियतम !
आगे विहङ्ग वे कर देते अपनी-अपनी ग्रीवा, प्रियतम !
दम्पति उनको सहला-सहला थे प्यार दान करते, प्रियतम॥७२५॥

सहसा लहरों का वेग, अहो ! इतना बढ़ जाता था, प्रियतम ! 
तरणी डगमग करने लगती, बाला डर जाती थी, प्रियतम ! 
साँवर अञ्जलि में जल लेकर उसका पद धो देते, प्रियतम ! 
देते फिर छींट तरंगों पर, वे धीमी पड़ जातीं, प्रियतम॥७२६॥

‘हे प्राणवल्लभे ! सरिता यह छूना है चाह रही, प्रियतम ! 
तुमको, अतएव चलो, इसकी इच्छा अवश्य रख दें, प्रियतम ! 
है नीर न यहाँ गंभीर, तनिक लहँगा ऊँचा करके, प्रियतम ! 
चलना !’ यह कहते साँवर के लोचन छल-छल करते,प्रियतम॥७२७॥

यों कहकर साँवर बाला को ले साथ उतर पड़ते, प्रियतम !
दोनों के अतिशय सावधान रहकर चलने पर भी, प्रियतम ! 
लहँगे की नील किनारी वह गीली हो ही जाती, प्रियतम ! 
बाला हँस-हँसकर फिर रसमय थी उपालम्भ देती, प्रियतम॥७२८॥

नीली प्रवाहिणी के दक्षिण तट पर अब वे आते,  प्रियतम !
अवली तमालतरु की जल को छू-छूकर हिलती थी, प्रियतम ! 
कर देते और नमित उसको साँवर दक्षिण कर से, प्रियतम ! 
डोली-सी वह बनती, उस पर बाला को बैठाते, प्रियतम॥७२९॥

शोभा निहार, पलभर वे भी आरोहण कर जाते, प्रियतम ! 
सहचरियाँ सुख में भरकर थीं झोंटा देने लगतीं, प्रियतम ! 
अभिनव झूला-उत्सव-सा वह सचमुच हो जाता था, प्रियतम ! 
दम्पति की हँसी निराली, वह सबका मन हर लेती, प्रियतम॥७३०॥

मानो आती थी करने वह संकेत कालगति का, प्रियतम ! 
शाखा पर एक उसी तरु की चढती बंदरी, अहो ! प्रियतम !
बाला का ध्यान उधर बँटता, दृग चिन्ताकुल होते, प्रियतम ! 
साँवर भी स्वयं उतर, नीचे उसको उतार लेते, प्रियतम॥७३१॥

दोनों की आँखें भर आतीं, मस्तक झुक जाता था, प्रियतम ! 
कंधेपर एक दूसरे के, कुछ बोल न वे पाते, प्रियतम !
आता प्रस्वेद् गात से था इतना कि वस्त्र उनके, प्रियतम ! 
उससे धुल जाते, यों लेते वे बिदा परस्पर थे, प्रियतम॥७३२॥

दक्षिण-पश्चिम की ओर एक जाती पगडंडी थी, प्रियतम !
उसपर रुक-रुककर चल पड़ते, साँवर निहारते थे, प्रियतम ! 
बाला को आकुलता-बिनती-परिपूरित लोचनसे, प्रियतम !
पैंतीस-तीस पल में होते ओझल तरुजालों में, प्रियतम॥७३३॥

निष्प्राण हुई-सी बाला अब चलती धीरे-धीरे, प्रियतम ! 
घर जाकर शय्यापर आँखें मूँदे पड़ जाती थी, प्रियतम !
थे प्राण नीलसुन्दर उसके, तन कहीं रहे, क्या था, प्रियतम !
प्राणोपम पर वह सखियों को प्रिय था सँभालतीं वे, प्रियतम॥७३४॥

आवेश भाव का बाला में अद्भुत हो जाता था, प्रियतम !
ज्यों-की-त्यों सब घटनाओं को वह सत्य देख लेती, प्रियतम ! 
साँवर की मैया, साँवर जो-जैसे घर पर करते, प्रियतम !
उसके निस्पन्द बंद दृग पर अङ्कित यह हो जाता, प्रियतम॥७३५॥

बाला देखती, काल की गति पीछे है सरक गयी, प्रियतम !
हैं क्रियाशील हो रही अघटघटनापटीयसी वे, प्रियतम !
है उषा लगी, अब जननी भी जग उठी, किंतु भोली, प्रियतम !
साँवर रजनी में बाहर थे घर से, न समझ पायी, प्रियतम॥७३६॥

दीपक की लौ से निर्मञ्छन अपने सुत का करके, प्रियतम ! 
करने दधिमन्थन लगी सुधास्यन्दी स्वर में गाती, प्रियतम !
उसके श्रवणों में पूरित है रुन-झुन-रव नूपुर का, प्रियतम !
आँखों में भरा नीलमणि है आँगन में नाच रहा, प्रियतम॥७३७॥

नवनीत हुआ प्रस्तुत, समाधि मैया की अब टूटी, प्रियतम !
फिर उसी शयनमन्दिर में जा पहुँची धीरे-धीरे, प्रियतम !
साँवर के मुख-सरोज परसे भ्रमरावलि सी अलकें, प्रियतम !
मृदु कर से अपसारित कर वह फूली न समाती है, प्रियतम॥७३८॥

अपने अर्बुद मैं प्राण लक्ष शतगुण तुझपर वारूँ, प्रियतम ! 
तू जाग लाल मेरा अमोल ! हो चुका सबेरा है, प्रियतम ! 
आयेंगे अभी सखा तेरे, गायें पुकारती हैं, प्रियतम ! 
तुझको, जाकर दुह ले उनको, उठ तो तू, देख भला, प्रियतम॥७३९॥

यों प्रेमिल शत मनुहारों से साँवर को जगा सकी, प्रियतम ! 
होते-होते न मुखारी वे पूरी अब भाग चले, प्रियतम !
जा पहुँचे गृहसम्बद्ध उसी गोशाला में पल में, प्रियतम ! 
वह धेनुसमूह निहाल हुआ लखकर आनन नीला, प्रियतम॥७४०॥

इस भाँति देख लेती बाला रहकर अपने घर ही, प्रियतम ! 
जैसे-तैसे सहचरियाँ सब उसको प्रबुद्ध करतीं, प्रियतम ! 
रसभरे अनेक उपायों से निर्वाह करा पातीं, प्रियतम ! 
मुखशोधन, उद्वर्तन, मज्जन, परिधान विभूषण का, प्रियतम॥७४१॥

इतनेमें आ जाती दूती साँवर की मैया की, प्रियतम !
बाला को नित्य बुलाती थी अपने ही घर जननी, प्रियतम ! 
था अनुभव उसे, रसोई जो बाला छू देती है, प्रियतम !
साँवर भर पेट उसे ही है खाता, न अन्य कुछ भी, प्रियतम॥७४२॥

दूती एवं सब सहचरियाँ उसको ले चल पड़ती, प्रियतम !
साँवर-ही-साँवर बाला को सर्वत्र दीख पड़ते, प्रियतम ! 
विक्षिप्त हई-सी आ पाती घरपर वह साँवर के, प्रियतम !
उनका दर्शन होने पर ही प्रकृतिस्थ कहीं होती, प्रियतम॥७४३॥

मैया से मिलकर, साँवर के अग्रज की जननी के, प्रियतम ! 
तत्वावधान में रन्धन के होते थे काम सभी, प्रियतम !
सब कुछ करते रहने पर भी बाला का मन रहता, प्रियतम !
डूबा प्रियतम साँवर के ही नीले-नीले तन में, प्रियतम॥७४४॥

मैया भी उधर जुड़ी रहती, बस, एक नीलमणि से, प्रियतम ! 
गाथाएँ उसे न जाने थीं कितनी गढ़नी पड़ती, प्रियतम ! 
वह तभी लगा पाती उबटन, उनको नहला पाती, प्रियतम ! 
शृङ्गार धरा पाती, भोजनगृह में ले आ पाती, प्रियतम॥७४५॥

साँवर फिर साथ सखागण के हँस-हँसकर थे खाते, प्रियतम ! 
भोजन का दृश्य अतुल निधि था बनता सबके दृग का, प्रियतम ! 
मैया का स्नेह दबा लेता उसके चञ्चल सुत को, प्रियतम ! 
विश्राम पचीस-तीस पलतक हँसकर वह कर लेता, प्रियतम॥७४६॥

मुखरित मुरली-रवसे पत्तन होने वह अब लगता, प्रियतम ! 
धारा-सी तोरण से बाहर गोश्रेणी चल पड़ती, प्रियतम ! 
था नीलदेवता ही चालक उनका, वह भी चलता, प्रियतम ! 
बाला आवास-अटारी से अपलक निहारती थी, प्रियतम॥७४७॥

साँवर-जननी के हृत्तल की निरुपम वत्सलता से, प्रियतम ! 
होकर अभिषिक्त पुनः बाला वासस्थल पर आती, प्रियतम !
वैसे ही दसों दिशाओं में साँवर दीखते उसे, प्रियतम !
बाहर का ज्ञान नहीं-सा ही उसमें रह जाता था, प्रियतम॥७४८॥

पगली-सी हई बैठ जाती आकर बाहर गृह से, प्रियतम !
 उठता द्वितीय पट सर-तट पर नूतन रंगस्थल का, प्रियतम ! 
क्रीड़ा वनगमनजनित वियोग हुतभुक् करने आता, प्रियतम ! 
उद्गमथल था जलने लगता, सखियाँ सँभालती थीं, प्रियतम॥७४९॥

गिरिवर-परिसर में सुन्दर वन जो आठ कुञ्ज का है, प्रियतम ! 
उसमें ही किसी कुञ्जमें वे बाला को ले आतीं, प्रियतम !
साँवर की बाट देखने का पल वह युग-सा बनता, प्रियतम ! 
वे आ पाते जब दशा इधर दसवीं आने लगती, प्रियतम॥७५०॥

दोनों के मिल जाने पर अब चढ़ता रस-सागर जो, प्रियतम ! 
ऊँचापन है कितना उसका, आँका अबतक किसने, प्रियतम ! 
आँखें सहचरियों की डूबी, तट पर उतरा न सकीं, प्रियतम ! 
कुञ्जों की द्रुम-लतिकाएँ हैं जड़िमा-पूरित तबसे, प्रियतम॥७५१॥

जो हो, बाला को ले साँवर करते परिक्रमा-सी, प्रियतम ! 
प्रियतमा-स्वरूप-विभावित उन दोनों सरोवरों की, प्रियतम ! 
नौकारोहण कर, हँस-हँसकर, विकसित-सरोज-वनका, प्रियतम !
सौरभमय सुमन चयन कर-कर, निज सुख वितरण करते, प्रियतम॥७५२॥

निर्झर निकुञ्ज-तरु-पत्रों से मधु का झरता रहता, प्रियतम ! 
होता न विराम किसी ऋतु में उसका, था जहाँ, वहीं, प्रियतम !
साँवर बाला को ले जाते, द्विगुणित होता झरना, प्रियतम ! 
दोनों में पुरइन के मधु भर वे उसे पिला पीते, प्रियतम॥७५३॥

चन्दन-कामिनी-जाल निर्मित सन्मुख थी कुञ्ज-कुटी, प्रियतम ! 
दोनों विभोर हो भावों से, उसमें प्रविष्ट होते, प्रियतम ! 
उत्तर की ओर दीखता था वन एक कल्पतरु का, प्रियतम ! 
ज्योतिर्मय सित-नीला, उसकी गाथा कहते-सुनते, प्रियतम॥७५४॥

बाला में सुनते-सुनते ही आ जाती तन्मयता, प्रियतम !
विस्मरण उसे हो जाता था अपने स्वरूप का भी, प्रियतम !
अपने ही लिये प्रश्न करने लग जाती साँवर से, प्रियतम !
साँवर भी होते भ्रमित,‘अहो ! कैसे क्या समझाऊँ ?’ प्रियतम॥७५५॥

ऐसे अवसर पर पुनः वही घटना घट जाती थी, प्रियतम !
जो महाभाव है, वह बनता रसराज एक पल में, प्रियतम ! 
होता रसराज उधर परिणत उस महाभाव-वपु में, प्रियतम ! 
क्या कहूँ अनिर्वचनीय कथा रसमय उस विनिमय की,प्रियतम॥७५६॥

दिनकर की एक किरण सहसा दोनों को छू लेती, प्रियतम ! 
हो गयी देर है, यह उनमें संकल्प जाग उठता, प्रियतम ! 
अपने स्वरूप में आकर, वे हँसकर चल पड़ते थे, प्रियतम ! 
सन्मुख कासार पुनः आता, प्रियतमानामधारी, प्रियतम॥७५७॥

उसमें अवगाहन की इच्छा जगती, निदाघ आता, प्रियतम ! 
दम्पति की रुचि की ही ऋतुएँ अनुसरण वहाँ करतीं, प्रियतम ! 
पलभर ही पहले जल-थल में ऋतु जो भी क्यों न रहे, प्रियतम ! 
तत्क्षण विलीन हो नव सुषमा ले काल नया आता, प्रियतम॥७५८॥

बाला छूती जलको, साँवर तत्काल उछल पड़ते, प्रियतम ! 
फिर उसे अङ्कमें लेकर वे संतरण-खेल करते, प्रियतम ! 
कमलों से विरचित कन्दुक की क्रीड़ा भी नव होती, प्रियतम ! 
दम्पति-तन का निरुपम सौरभ झर-झर कर सर भरता, प्रियतम॥७५९॥

जब भीग-भीग दृग बाला के अत्यन्त अरुण होते, प्रियतम ! 
पावन जल केलि निराविल वह सुखमयी तभी थमती, प्रियतम ! 
दोनों के भीगे कुन्तल को, गोरे-नीले तन को, प्रियतम ! 
जो पोंछ वस्त्र पहनाती हैं, इतिहास गूढ़ उनका, प्रियतम॥७६०॥

आते अब वकुल-कुञ्ज में वे चलकर मन्थर गतिसे, प्रियतम ! 
श्रृंगार धराने का उनमें रसमय झगड़ा होता, प्रियतम !
यह कभी अनादिकाल से ही अब तक निर्णय न हुआ, प्रियतम !
भूषित कर सका, सकी पहले सचमुच वह कौन किसे, प्रियतम॥७६१॥

सुन्दर निकुञ्ज सुमनों का है सम्बद्ध एक उससे, प्रियतम ! 
उसमें पधार पीयूष भरे वनफल का रस लेते, प्रियतम !
बाला के अधरपल्लवों पर साँवर का, फिर उसका, प्रियतम !
उनके बिम्बाधर पर रखना फल दृगफल हो जाता, प्रियतम॥७६२॥

जो पीत-हरितमणि विरचित है मोहन-निकुञ्ज उसमें प्रियतम ! 
विश्राम फूल की शय्या पर वे एक दण्ड करते, प्रियतम ! 
जग कर फिर शीतल जल पीकर शुक-सारी की रचना, प्रियतम ! 
वह भावमयी सुनते-सुनते सुख से अचेत होते, प्रियतम॥७६३॥

आकर तृण की उस वेदी पर लेकर सोलह कौड़ी, प्रियतम !
फिर दाँव परस्पर अङ्गों का वे लगा खेलते थे, प्रियतम !
जो दाँव जीत लेता-लेती उसको अनुभव होता, प्रियतम !
मैं हारा, हार गयी, ऐसे रसभरे नियम कुछ थे, प्रियतम॥७६४॥

पश्चिम की ओर अंशुमाली ढल पड़े दीख जाते, प्रियतम !
वे तब हीरक रविमन्दिर में अर्चन करने आते, प्रियतम !
साँवर का स्वरचित मन्त्रों से रवि पूजन करवाना, प्रियतम !
बाला के दृग-मन में नव-नव सुख की आशा भरता, प्रियतम॥७६५॥

इसके पश्चात् बिछुड़ने की जल पड़ती आग वही, प्रियतम ! 
साँवर सँभालने चल पड़ते गो-सखा-समूहों को, प्रियतम ! 
रजनी में पुनर्मिलन की उस आशा को लिये हुए, प्रियतम !
बाला मुरझायी माला-सी घर आकर पड़ रहती, प्रियतम॥७६६॥

सहचरी नवीन वेष भूषा उसकी रच देती थी, प्रियतम ! 
उस ओर वेणुरव से वनका कण-कण पूरित होता, प्रियतम !
घर अतुल नीलमणि साँझ समय मैया के थे आते, प्रियतम ! 
दर्शन फिर तनिक दूर से ही कुछ पल बाला पाती, प्रियतम॥७६७॥

प्रत्येक वस्तु में प्राणों का रस भरकर ही मैया, प्रियतम ! 
उससे अपने सुत का लालन करके सुखिनी होती, प्रियतम ! 
पूरा करके प्रदोष का क्रम, साँवर सो जाते थे, प्रियतम ! 
त्रिभुवन-मोहन-मोहिनी शक्ति जननी को भी ढकती, प्रियतम॥७६८॥

निस्तब्ध निशा हो जाने पर साँवर उठ पड़ते थे, प्रियतम !
नीली सरिता के तट के उस वट के समीप आते, प्रियतम !
उस संकेतस्थल पर बाला पहले ही आ जाती, प्रियतम !
अभिसार निराला यह उसका अज्ञात सभी को था, प्रियतम॥७६९॥

भावोंका था आवेश एक उनमें विचित्र होता, प्रियतम !
प्रत्यक्ष परस्पर रहकर भी दोनों न देख पाते, प्रियतम !
हो आकुल एक दूसरे को निरुपाय ढूँढ़ते थे, प्रियतम !
दोनों के लिये ध्येयमय था यह अखिल दृश्य बनता, प्रियतम॥७७०॥

यह लहर शमित होते-होते लग जाती एक घड़ी, प्रियतम ! 
जाकर तब कहीं भुजाओं का बन्धन लग पाता था, प्रियतम ! 
जो भी बड़भागिन खड़ी-खड़ी अवगाहन कर पायी, प्रियतम ! 
उन खोज-मिलन की लहरों में, उसने समझा रस को, प्रियतम॥७७१॥

अब शुभ्र चाँदनी में उनका धीरे-धीरे चलना, प्रियतम !
सरिता का नीर गुल्फपरिमित होकर पथ दे देना, प्रियतम !
हँसते-हँसते दोनों का फिर उस पार उतर जाना, प्रियतम !
कहने जाकर यह खो दूँगी इसकी सुन्दरता को, प्रियतम॥७७२॥

रासस्थल की स्वर्णिम वेदी, स्वर्णिम वह मंच बड़ा, प्रियतम ! 
स्वर्णिम दण्डों से जुड़ी हुई स्वर्णिम वल्लरियाँ वे, प्रियतम ! 
स्वर्णिम वितान वह फूलों का स्वर्णिम खग की श्रेणी, प्रियतम ! 
ये बरबस साँवर-बाला को आकर्षित कर लेते, प्रियतम॥७७३॥

आकर, इनको छू-छूकर, वे दोनों खिल पड़ते थे, प्रियतम ! 
प्रस्तुत सब कुछ करके रखतीं सहचरियाँ पहले से, प्रियतम ! 
थे स्वयं आप साँवर करते अर्पित तमोल उनको, प्रियतम !
आरम्भ नृत्य फिर हो जाता बाला का, साँवर का, प्रियतम॥७७४॥

कबतक चलता वह नृत्य, अहो ! कैसे बतलाऊँ मैं, प्रियतम !
आँखों में है अबतक पूरित हल्लीसक-मुद्राएँ, प्रियतम !
शशधर है ठीक मध्य नभ में वैसे ही गति भूले, प्रियतम ! 
वे मुग्ध देखते हैं साँवर, बाला है नाच रही, प्रियतम॥७७५॥

वैसे ही कटि झुक जाती है बाला की पल-पल में, प्रियतम ! 
अम्बर वक्षःस्थल का भी वह वैसे ही चञ्चल है, प्रियतम ! 
वे कुण्डल भी वैसे ही हैं हो रहे चपल दोनों, प्रियतम ! 
आनन-सरोज पर वैसे ही प्रस्वेदकणावलि है, प्रियतम॥७७६॥

गिर रहे फूल वैसे ही हैं झर-झरकर अलकों से, प्रियतम !
साँवर अपने दुकूल में हैं कर रहे चयन उनको, प्रियतम !
वैसे ही नाच-नाच करके साँवर भी बाला की, प्रियतम !
कर रहे सरस अनुमोदन हैं उन नृत्यभङ्गियों का, प्रियतम॥७७७॥

रसमय तन्त्रों के तार सभी वैसे ही झंकृत हैं, प्रियतम !
वैसे ही नूपुर का रुन-झुन सहयोग दे रहा है, प्रियतम !
वैसे ही तालबन्ध भी है पल-पल नवीन होता, प्रियतम ! 
वैसे ही बज उठती है वह साँवर की करताली, प्रियतम॥७७८॥

इसपर मैं किंतु सरस झीना आवरण डालकर ही, प्रियतम !
आगे चलती हूँ बाला को, साँवर को ले दृग में, प्रियतम ! 
उस ओर नृत्य उन दोनों का अविराम चल रहा है, प्रियतम !
वे उधर उसी क्षण हैं निकुञ्जपथ में भी चल पड़ते, प्रियतम॥७७९॥

दक्षिण-उत्तर-विभाग युगपत् बन जाता क्रीड़ा का, प्रियतम !
दोनों ही ओर खेलते थे दोनों ही केवल वे, प्रियतम !
उत्तर की ओर चलें पर हम, है देर घड़ी दो की, प्रियतम !
है उषा सखी आनेवाली मिलने हम दोनों से, प्रियतम॥७८०॥

जो हो, निकुञ्ज में जब दोनों आकर विराजते थे, प्रियतम ! 
कौतुक विचित्र-सा वह उनमें होता रहस्यमय था, प्रियतम ! 
बाला कुछ सरस पहेली थी रखती समक्ष उनके, प्रियतम ! 
साँवर भी तनिक सोच, हँसकर उत्तर देते जाते, प्रियतम ॥७८१॥

है प्रथम कौन, जो स्निग्ध बनी ? फिर कौन ? सुशीतल है, प्रियतम ! 
तीसरी ? तरल सुरभित जो है, चौथी ? सुस्मित वाली, प्रियतम ! 
पञ्चम ? उज्ज्वल मणिमाला है, वह छठी ? अमित मीठी, प्रियतम ! 
मिल गयी ? अनुग्रहमयी साथ तुम हो निहाल मैं हूँ, प्रियतम॥७८२॥

अब पहली ? नित्य अरुण है, फिर ? जीवन का जीवन है, प्रियतम ! 
तीसरी ? लवणता निधि है, अब ? है बसी हुई मुख में, प्रियतम ! 
पाँचवीं ? अमल बूँदोंवाली, वह छठी ? सुचिह्नित है, प्रियतम ! 
मिल गयी ? अनुग्रहमयी साथ तुम हो, निहाल मैं हूँ, प्रियतम॥७८३॥

अब पहली ? काली ताली है, फिर ? पद्मरागरेखा, प्रियतम ! 
तीसरी ? निराविल, पोली है, फिर ? दीना पदवाली, प्रियतम ! 
अब ? शशि का गुण धरनेवाली, फिर ? पद-अँगुरी में है, प्रियतम ! 
मिल गयी ? अनुग्रहमयी साथ तुम हो, निहाल मैं हूँ, प्रियतम॥७८४॥

अब कौन ? सरसती रहती है, फिर ? रस-कलसीवाली, प्रियतम ! 
अब कौन ? छाप छलनेवाली, आगे ? प्रस्वेदभरी, प्रियतम ! 
फिर ? वह तिरछी चितवन में है, अब ? तोरणलतिका है, प्रियतम ! 
मिल गयी ? अनुग्रहमयी साथ तुम हो, निहाल मैं हूँ, प्रियतम॥७८५॥

अब पहली ? बँधी हई है जो, फिर ? दृगनिवासवाली, प्रियतम !
आगे ? वह निर्मल हासमयी, फिर ? असितबिन्दुवाली, प्रियतम ! 
पञ्चम ? आवरण कण्ठमें है, है छठी ? माँग भरती, प्रियतम !
मिल गयी ? अनुग्रहमयी साथ तुम हो, निहाल मैं हूँ, प्रियतम॥७८६॥

अब पहली ? कर धरनेवाली, फिर ? कर-पद-गति वाली, प्रियतम ! 
अब ? कालीरेखा है, आगे ? पलकों से जुड़ी हुई, प्रियतम ! 
पञ्चम ? पद-कंज-विभूषित है, फिर ? है आलस्यभरी, प्रियतम ! 
मिल गयी ? अनुग्रहमयी साथ तुम हो, निहाल मैं हैं, प्रियतम॥७८७॥

अब पहली ? लाल सलों वाली, फिर ? उरपर रहती है, प्रियतम ! 
फिर ? पीली-नीली, पोली है, अब ? बसी होंठ में है, प्रियतम ! 
पञ्चम ? पद रेखा वाली है, वह छठी ? भुजा में है, प्रियतम ! 
मिल गयी ? अनुग्रहमयी साथ तुम हो, निहाल मैं हूँ, प्रियतम॥७८८॥

अब पहली ? कुण्डलवाली, फिर ? तनके कण-कण में है, प्रियतम ! 
अब ? पद-पद पर जो मुखरा है, चौथी ? है कटि थामे, प्रियतम ! 
पञ्चम ? कुञ्चित कच में है, फिर ? कर धर कर पीन बनी, प्रियतम ! 
मिल गयी ? अनुग्रहमयी साथ तुम हो, निहाल मैं हूँ, प्रियतम॥७८९॥

‘अब अन्तिम कौन ? उसे तो मैं छूकर बतलाऊँगा।’ प्रियतम !
कहकर यह, साँवर पहनाते कर-माला बाला को, प्रियतम !
तदनन्तर वे लहरें उठतीं जो उस रस-वारिधि में, प्रियतम !
उनमें स्वरूप से ही मज्जन करने की पद्धति है, प्रियतम॥७९०॥

अपने ऊपर, अपने से ही, अपने को ही आगे, प्रियतम !
वे लहरदान करतीं रसमय वह रूप कूल का-सा, प्रियतम । 
जिस पर उतरा आते साँवर, उतरा आती बाला, प्रियतम !
कुछ पल के लिये, और उनमें बातें होने लगतीं, प्रियतम॥७९१॥

‘प्रियतमे ! कहानी एक कहो, तुम बहुत जानती हो’, प्रियतम ! 
‘प्राणाधिक ! मैं सब भूल गयी, तुम तो कह सकते हो।’ प्रियतम ! 
‘हे प्राणवल्लभे ! नहीं, नहीं, मेरी रुचि यह रख दो’, प्रियतम ! 
‘अच्छा तो, सुनो; हुँकारी पर सुनकर देते रहना।’ प्रियतम॥७९२॥

‘बस्ती थी एक अहीरों की, उनका अधिपति भी था’, प्रियतम ! 
‘उसका था एक तनूज चपल, जिसका तन था काला’, प्रियतम ! 
‘त्रिभुवन-जन-मन-मोहक उसने पायी थी सुन्दरता’, प्रियतम ! 
‘उस पर थीं बिना मोल के ही बिक गयी सभी तरुणी’, प्रियतम॥७९३॥

‘कुछ देर अभी पहले की ही घटना बतलाती हूँ’, प्रियतम !
‘उस काले बालक ने, ऐसी वंशीमें तान भरी’, प्रियतम ! 
‘सुनते ही जिसे अङ्गनाएँ, मोहित हो रुक न सकीं’, प्रियतम ! 
‘तत्क्षण सब परित्याग करके उसके समीप आयीं’, प्रियतम॥७९४॥

‘स्वागत करके पहले उसने की कड़ी जाँच उनकी’, प्रियतम ! 
‘डर दिखलाया, बहकाया भी, धर्मोचित दी शिक्षा’, प्रियतम ! 
‘फिर पाठ पढ़ाया, बढ़ने का उसके प्रति भाव भला’, प्रियतम ! 
‘प्राणोंमें टीस लगी चलने सुन-सुनकर उन सबके’, प्रियतम॥७९५॥

‘रो-रोकर उत्तर दे-देकर वे खरी उतर आयीं’, प्रियतम ! 
‘करुणा की ऊर्मि उठी रसमय हृत्तल में बालक के’, प्रियतम !
‘उनके जीवन की साध सभी उसने पूरी कर दी’, प्रियतम ! 
‘है किंतु निराली प्रीति-रीति, बालक छिप गया कहीं’, प्रियतम॥७९६॥

‘अच्छा-सा एक बहाना भी उसको मिल गया अहो !’ प्रियतम ! 
‘छोरी थी एक, उसीमें था मन फँसा हुआ उसका’, प्रियतम ! 
‘गोरी थी वह, बेटी थी उस नृपकी, जिसके तन में’, प्रियतम ! 
‘वे देव दिवाकर पूरित थे होकर हरदम रहते’, प्रियतम॥७९७॥

‘उस छोरी को ही साथ लिये भागा वह बालक था’, प्रियतम ! 
‘दीखा था म्लान हुआ-सा मुख, छोरी का बालक को’, प्रियतम ! 
‘अतएव अमित सुन्दरियों के उस नेह जाल में भी’, प्रियतम ! 
‘सामर्थ्य रही न उसे अब जो उलझाकर रोक सके’, प्रियतम॥७९८॥

‘इस ओर भूलने का स्वभाव पल-पल, छोरी का था’, प्रियतम ! 
‘हो भ्रमित, समझ बैठी बालक मुझको भी छोड़ गया’, प्रियतम !
‘उस ओर सत्य ही रसके उन नियमों में बँधा हुआ’, प्रियतम !
‘बालक उन तरुणी-गण के था दृग-पथ से हटा हुआ’, प्रियतम॥७९९॥

उमड़ी वियोग की दो सरिता दो भिन्न दिशाओं से’, प्रियतम ! 
संगमित हुई पथ में, तट पर बालक था खड़ा वहीं’, प्रियतम ! 
कानों में उसके गूँज रही ध्वनि थी प्रवाहिणी की’, प्रियतम !
हो रहे चित्र हृत्पट पर थे, अङ्कित सब लहरों के’, प्रियतम॥८००॥

‘मोहन-सुजान-पद-नीरज को क्षत लग न जाय कोई’, प्रियतम ! 
‘लेकर इस भय को ही अपने कर्कश उर पर रखतीं’, प्रियतम !
‘रे हाय ! हो रही क्या होगी दयनीय दशा उसकी’, प्रियतम ! 
‘काँटों से, पत्थर के कण से, इस घोर अँधेरे में।’ प्रियतम॥८०१॥

‘जैसे प्रतिचित्रित यह लहरी करुणा से सिक्त हुई’, प्रियतम !
‘बालक उनके दृग के आगे हँसकर हो गया खड़ा’, प्रियतम !
‘कोई अर्गला न अब रस के लेने-देने में थी’, प्रियतम !
‘अनुभूति उस समय की उनकी कोई न कह सकेगी’, प्रियतम॥८०२॥

‘इसके पश्चात नाचने का आयोजन बृहत् हुआ’, प्रियतम ! 
‘छोरी नाची, बालक नाचा, सब-की-सब वे नाचीं’, प्रियतम !
‘उनकी इस नृत्य-कहानी का अब एक अंश-भर है’, प्रियतम ! 
‘मेरे मानस-पट पर अङ्कित, बाकी मैं भूल गयी’, प्रियतम॥८०३॥

बाला इतना-सा ही कहकर रुकती, साँवर कहते, प्रियतम ! 
‘तो याद करा दूँ मैं आगे, प्रियतमे ! अनुज्ञा है ?’ प्रियतम !
‘क्या करना है, हो रहे श्रमित तुम हो, विश्राम करो।’ प्रियतम ! 
उत्तर बाला का यह होता, झपने-से दृग लगते, प्रियतम॥८०४॥

मीलित-से होने लग जाते साँवरके लोचन भी, प्रियतम !
दोनों की भावमयी समाधि निरुपम लग जाती थी, प्रियतम !
सविकल्प और फिर निर्विकल्प नामों से कही हुई, प्रियतम !
सत्ताएँ उसे न छू सकतीं, होती अद्भुत ऐसी, प्रियतम॥८०५॥

उसका प्रतिबिम्ब भले वाणी-मन-बुद्धि कहीं छू लें, प्रियतम !
वे तथा सदा के लिये बने तद्रूप निहाल अहो ! प्रियतम !
संभव है इतना-सा ही, मैं आगे क्या और कहूँ, प्रियतम ! 
हे प्राणाधिक ! निहार लेना सागर तुम गागर में, प्रियतम॥८०६॥
जो हो, आगे न सही, बायें मुड़ जाती हूँ अब मैं, प्रियतम ! 
धारामें सीधे कभी नहीं संतरण सुखद होता, प्रियतम !
दम्पति भी इसी ओर, देखो, आ रहे, भला, वे हैं, प्रियतम ! 
बाला के दृग खुल गये, पुनः रोना है किंतु उसे, प्रियतम॥८०७॥

आखिर रसभरा स्वप्न यह भी बाला का बदल गया, प्रियतम ! 
थोड़े होते हैं सुख के दिन, है नियम सदा का ही, प्रियतम ! 
है बीज दुःख उस सुख का ही, जो नित्य सनातन है, प्रियतम ! 
पर एक बार तो शूलों से छिद गये प्राण उसके, प्रियतम॥८०८॥
''',
      ),
      BookPage(
        title: 'नवम शतक',
        content: '''आया था कोई दूत एक, जो उस राजा का था, प्रियतम !
थे करद-राज्य अगणित जिसके नीचे, डरते रहते, प्रियतम ! 
वह नृप नृशंस था घोर, कौन जाने क्या कब कर दे, प्रियतम ! 
कौशल से ही संतुष्ट उसे करके सब बच पाते, प्रियतम॥८०९॥

उस कपटी ने मख-उत्सव का आयोजन बृहत् किया, प्रियतम ! 
उस साँवर बालक को भी था बुलवा भेजा उसने, प्रियतम ! 
वह दूत महीपालक का था सन्देश लिये पहुँचा, प्रियतम ! 
जब साँझ हो चुकी थी अशकुन बाला को तभी हुए, प्रियतम॥८१०॥

मुरझा सहसा वे फूल गये, कुन्तल में जो लगते, प्रियतम ! 
अञ्जन जल-सा हो तरल लगा बहने अवनी पर, हे प्रियतम ! 
सुरभित सब भरे विलेपन से वे कनकपात्र ढरके, प्रियतम ! 
नीलम का हार टूटकर वह गिर गया उरस्थल से, प्रियतम॥८११॥

धक-धक कर उठा कलेजा था बालाक का देख इसे, प्रियतम ! 
रोती-सी है बयार वन की, इतने में भान हुआ, प्रियतम ! 
संध्या की वह नीरवता भी इङ्गित कर-सी बैठी, प्रियतम !
उस ओर, बात अनचाही जो होनी थी अभी वहाँ, प्रियतम॥८१२॥

उपवन-परिसर में गृह की थी जो अटा, वहीं वह थी, प्रियतम ! 
संयोग आज ही था, कोई थी पास न सखी वहाँ, प्रियतम ! 
अत्यधिक अमंगलसूचक ये बातें कहने उनसे, प्रियतम ! 
नीचे दौड़ी, दो मिलीं, किंतु अतिशय उदास वे थीं, प्रियतम॥८१३॥

छा गया अँधेरा आँखों के आगे भय से उसकी, प्रियतम !
क्या हुआ अनिष्ट, हाय ! कुछ है प्राणाधिक साँवरका, प्रियतम ! 
इसलिये मलिन मुद्रा इनकी हो गयी अचानक है, प्रियतम ! 
यह सोच, थामकर सिर अपना, गिरती-सी बैठ गयी, प्रियतम॥८१४॥

लेकर भुजबन्धन में उसको, पौढ़ा जो थी उनमें, प्रियतम ! 
कहने कुछ चली, किंतु सम्भव हो सका न कह देना, प्रियतम ! 
दो टूक कलेजा बाला का होता-सा दीख पड़ा, प्रियतम ! 
सुन लेगी, जो वह बात सखी थी छिपा रही उससे, प्रियतम॥८१५॥

दोनों सहचरियों की आँखें कहती अवश्य कुछ थीं, प्रियतम ! 
हैं व्यथा लिये गहरी बाला, पर समझ सकी इतना, प्रियतम ! 
कुम्हलाये नयन-सरोजों से थी देख रही उनको, प्रियतम ! 
दुर-दुर था उर करने लगता पूछे क्या वह उनसे, प्रियतम॥८१६॥

आखिर वह हृदयविदारक जो थी बात सखी-मुखसे, प्रियतम ! 
दृगके उत्तप्त हुए जल से जल-जलकर निकल पड़ी, प्रियतम !
‘साँवर हैं री ! जाने वाले इस वन से दूर वहाँ, प्रियतम ! 
है क्रूर नराधम नरपति वह विख्यात जहाँ रहता।’ प्रियतम॥८१७॥

यह भावी महाप्रलय की ही मानो सूचना मिली, प्रियतम ! 
बाला तो झुलस उठी उसकी लपटों से अबसे ही, प्रियतम ! 
उसकी आँखों की पलकों में कोई भी गति न रही, प्रियतम ! 
वे टँगी दे रही-सी पथ थीं प्राणों को उड़ने का, प्रियतम॥८१८॥

वे प्राण न किंतु उड़े, कैसे उड़ते, अब शक्ति न थी, प्रियतम ! 
ऊपर से उनपर दुख का था इतना भारी बोझा, प्रियतम ! 
जो हिल तक भी न सके तिलभर, पिस-से वे गये वहीं, प्रियतम ! 
उत्क्राम नहीं, ज्यों-के-त्यों लय होने का द्वार बचा, प्रियतम॥८१९॥

ऐसा ही होने चला, किंतु विधि का विधान यह था, प्रियतम !
वे जलें अनेकों वर्षों तक, अतएव न हो पाया, प्रियतम ! 
आ गये तुरंत वहीं साँवर, फिर देश-काल बदले, प्रियतम ! 
बीती रजनी की आठ घड़ी, आयी वह कुञ्जथली, प्रियतम॥८२०॥

लेकर उरमें बाला को थे साँवर उदास बैठे, प्रियतम ! 
आने पर तनिक चेतना जब उसके दृग-नलिन खुले, प्रियतम ! 
यह लगा उसे, जगपालक की सीमा न दया की है, प्रियतम ! 
जाकर मेरे जीवनधन फिर जो लौट यहाँ आये, प्रियतम॥८२१॥

आधे पलतक वह हर्ष-किरण आँखों में भरी रही, प्रियतम ! 
क्या सत्य किंतु था, साँवर की मुखमुद्रा कह बैठी, प्रियतम ! 
बाला उनसे क्या कहती अब, साँवर भी क्या कहते, प्रियतम ! 
चारों लोचन से ही जल की बह चली तप्त धारा, प्रियतम॥८२२॥

हो जाती लुप्त चेतना जब रह-रहकर बाला की, प्रियतम !
साँवर का भी विवेक पूरा कुण्ठित हो जाता था, प्रियतम !
वे तड़प रहे थे रागभरे दो हृदय वेदना से, प्रियतम !
उनको विवेक शीतल कर दे, यह हुआ, न होगा ही, प्रियतम॥८२३॥ 

बाला के दुःख भरे उरका था तापमान इतना, प्रियतम !
जो अहो ! अचेतनता भी थी सह पाती नहीं उसे, प्रियतम !
दो-तीन पलोंमें ही होकर अधजली भाग जाती, प्रियतम !
साँवर निरुपाय उधर आकुल रो रहे निरन्तर थे, प्रियतम॥८२४॥

क्रन्दन की तप्त ऊर्मियों में, मूर्छा की छाया में, प्रियतम ! 
पल-पल बहकर, आगे बढ़कर, रजनी थी बीत रही, प्रियतम ! 
कैसे लूँ विदा प्रियतमा से, साँवर न समझ पाते, प्रियतम ! 
जाना तो था ही, पर सब रस जाने का निकल गया, प्रियतम॥८२५॥

इतने में ही बाला में कुछ परिवर्तन दीख पड़ा, प्रियतम ! 
वह उठी भाव की लहर, जिसे देखी न किसी ने थी, प्रियतम !
‘यह इसीलिये तो प्रश्न बना साँवर के जाने का’, प्रियतम ! 
‘इनको सुख है इसमें फिर मैं होऊँ विघातिनी क्यों ?’ प्रियतम॥८२६॥

संयत-सी होकर, साँवर की ग्रीवा में भुजमाला, प्रियतम ! 
पहनाकर वह बोली,‘क्या सच जा रहे, नाथ ! तुम हो ?’ प्रियतम ! 
‘है हेतु अहो ! क्या, कहो मुझे, मैं सम्मति दे दूँगी’, प्रियतम ! 
‘हूँ नित्य अनादि किंकरी तो इन पद-नलिनों की ही।’ प्रियतम॥८२७॥

रुक गया कण्ठ बाला का बस, कहते-कहते इतना, प्रियतम ! 
अत्यन्त हुए बेहाल उधर साँवर यह कह पाये, प्रियतम ! 
‘हैं इस तनके कुछ कृत्य वहाँ, प्राणों की रानी हे !’ प्रियतम ! 
‘इन पीले पदनखमणि में ही मन तो है नित्य बसा’, प्रियतम॥८२८॥

‘जाओ प्राणाधिक !’ धीमा यह उत्तर में स्वर आया, प्रियतम ! 
केवल इतना-सा ही विनिमय वाणी का हो पाया, प्रियतम ! 
बाकी सब बातें आँखों की उन सजल पुतलियों ने, प्रियतम ! 
भीगी रोमावलि ने कर लीं नीरव उस भाषा में, प्रियतम॥८२९॥

था अन्तिम बार उरःस्थल से उर का जुड़ना कैसा, प्रियतम ! 
क्या कहूँ चेतना खो दोगे तुम सुनते ही उसको, प्रियतम ! 
क्यों हो इतिहास अधूरा यह, होगा न उचित यह तो, प्रियतम ! 
अतएव सुनो आगे जैसे निकले निकुञ्ज से वे, प्रियतम॥८३०॥

गलबाँही दिये हुए ही वे अब भी बाहर आये, प्रियतम ! 
दक्षिण की ओर चले, फिर उस सरिता को पार किया, प्रियतम ! 
आया वह थल भी, प्रतिदिन वे लेते थे विदा जहाँ, प्रियतम ! 
आते ही किंतु वहाँ झिन-झिन लग गये चरण करने, प्रियतम॥८३१॥

क्षमता न रही अब बाला में, रह सके आँख खोले, प्रियतम ! 
वह हटे नील बायें करकी माला, क्यों दृग देखें, प्रियतम ! 
बारह-दस पलके अन्तर से उसकी उघरी पलकें, प्रियतम ! 
साँवर थे दो पद दूर खड़े लोचन में लोर लिये, प्रियतम॥८३२॥

दोनों कर से छाती थामे बाला थी मौन खड़ी, प्रियतम ! 
उसका सिर किंचित् जब हिलता सम्मति की मुद्रा में, प्रियतम ! 
साँवर तब ही रख पाते थे पद एक उस दिशा में, प्रियतम ! 
थी म्लान उषा यह देख रही, रो रहा वनस्थल था, प्रियतम॥८३३॥

साँवर गोपेशपुरी के उस वनमें जब समा गये, प्रियतम !
बाला पगली हो दौड़ चली उनके पीछे-पीछे, प्रियतम !
रोका न उसे सहचरियों ने, वे भी पीछे दौड़ीं, प्रियतम ! 
वह गिर न पडे इतना-सा, पर उनमें था ध्यान बना, प्रियतम॥८३४॥

वनकी कुछ लता उलझती थीं बाला के चरणों में, प्रियतम !
उसके तनकी गर्मी से पर जलने वे लग जातीं, प्रियतम !
इसलिये तुरंत छोड़ देतीं, उसको पथ मिल जाता, प्रियतम ! 
दस पलमें वह जा पहुँची घर साँवर की मैया के, प्रियतम॥८३५॥

भीतर न किंतु जाकर, अड़कर तोरण से बैठ गयी, प्रियतम ! 
सबको प्रत्यक्ष दीखती थी उन्मत्त दशा उसकी, प्रियतम ! 
बिखरे थे केश, ओढ़नी भी गिर गयी खिसक कर थी, प्रियतम ! 
आवरण कञ्चुकी का उर पर केवल था बचा हुआ, प्रियतम॥८३६॥

वे किसी भाँति उसके तन को ढक गयीं सहचरियाँ, प्रियतम ! 
लज्जा क्या अब उसमें रहती, जब तन सुधि ही न रही, प्रियतम ! 
जल रही आग की भट्ठी थी कैसी उसके उरमें, प्रियतम ! 
कैसे थे प्राण बचे फिर भी, यह कह न सकूँगी मैं, प्रियतम॥८३७॥

हो चुकी व्यवस्था प्रायः थी कालोचित सब पूरी, प्रियतम !
जानेवाले भी प्रस्तुत थे साँवर के साथ वहाँ, प्रियतम ! 
गोपेश खड़े थे, सहचर भी शिशु थे तैयार खड़े, प्रियतम !
सँवर एवं उनके अग्रज, इनकी ही देरी थी, प्रियतम॥८३८॥

मैया थी सजा रही उनको, पर कर न काम करते, प्रियतम ! 
वह भूल रही थी रह-रहकर, कैसे क्या है करना, प्रियतम ! 
गिर जाय न एक बूँद भी जल दृगसे, सतर्क पर थी, प्रियतम ! 
जाने के समय नीलमणि के क्यों चिह्न अमंगल हो, प्रियतम॥८३९॥

जैसे-तैसे सब करके वह साँवर को ले आयी, प्रियतम ! 
साँवर अग्रज को साथ लिये रथ पर भी जा बैठे, प्रियतम ! 
बाला यह सब थी देख रही, रहकर कुछ दूर खड़ी, प्रियतम ! 
निस्पन्द पुतरियाँ उसकी थीं प्रस्तर-पुतरी की-सी, प्रियतम॥८४०॥

सहसा वह बोल उठी ऊँचे स्वर से पुकार सबको, प्रियतम ! 
‘भूकम्प हो रहा है, देखो, ये टूट रहे द्रुम हैं’, प्रियतम ! 
‘दौड़ो, सब दौड़ो, इस रथ के पहिये में घुस जाओ’, प्रियतम ! 
‘लो थाम इसे, लो बचा इसे, धरती है घूम रही’, प्रियतम॥८४१॥

उस बड़ी सखी ने अंगुलियाँ उसके मुख पर रख दीं, प्रियतम ! 
पर तब तक तो बाला पर ही आ टिकीं आँख सबकी, प्रियतम ! 
उसकी उस वाणी में ऐसी थी ऊर्मि वेदना की, प्रियतम ! 
जो एक साथ ही क्षणभर तो सबका धीरज टूटा, प्रियतम॥८४२॥

उस विषम परिस्थिति को कातर साँवर की आँखों ने, प्रियतम ! 
बाला की ओर निहार अहो ! सर्वत्र सँभाला था, प्रियतम ! 
उसका सिर अनुमति देता-सा हिल गया तनिक फिर से, प्रियतम ! 
चल पड़ा और रथ घड़-घड़कर धीरे-धीरे आगे, प्रियतम॥८४३॥

था प्राण छेदने वाला रव घड़-घड़ का रूप धरे, प्रियतम !
जो उनके साथ न जा पायीं, उन एक-एक का ही, प्रियतम !
कट-कटकर वे कदली-जैसी क्रमशः गिरती जातीं, प्रियतम ! 
चल पड़ा चक्र अबला-वन में था क्रूर काल-करि का, प्रियतम॥८४४॥

जो काँप-काँपकर किसी तरह उससे कुछ बच पायीं, प्रियतम ! 
उनको समूल उत्पाटित कर मानो ले साथ चला, प्रियतम ! 
वह महाभयानक दुख का था जो झञ्झावात उठा, प्रियतम ! 
बढ़ रहा वेग जिसका था मिल-मिलकर रथ की गति से, प्रियतम॥८४५॥

बाला उनमें ही थी, उसका तन तो उड़ता ही था, प्रियतम ! 
उसके माथे में भी वह था झञ्झा प्रकोप भारी, प्रियतम ! 
वह रथके पीछे-पीछे अब भागती जा रही थी, प्रियतम ! 
‘हा-हा’ कर हँसती, झर-झर थे साँवर के दृग झरते, प्रियतम॥८४६॥

आया वह पेड़ उदुम्बर का, पथ का था मोड़ जहाँ, प्रियतम ! 
बङ्किम उस मुद्रा में साँवर रथ पर उठ खड़े हुए, प्रियतम !
वह नीली ज्योति सत्य मानो दो-सी हो गयी अहो ! प्रियतम ! 
बाला में एक मिली, लेकर दूजी को रथ भागा, प्रियतम॥८४७॥

आधे पल में ओझल दृग से रथ हुआ सघन वन में, प्रियतम ! 
तत्क्षण फिर अट्टहास गूंजा बाला के श्रीमुख का, प्रियतम ! 
ऊपर उठ गयीं भुजाएँ, पद गतिशील हुए उसके, प्रियतम! 
ऐसे मानो हो गया समय उस रासनृत्य का हो, प्रियतम॥८४८॥

‘नाचो-नाचो, बहिनों री ! तुम, मैं नाच सिखाऊँगी, प्रियतम ! 
जय हुई प्रीति की, जय बोलो, मेरी न, अरी ! उनकी’ प्रियतम ! 
इस भाँति अचानक बोल उठी गलने लग गयी धरा, प्रियतम ! 
वह पास पड़ा पत्थर उसकी ज्वाला से पिघल गया, प्रियतम॥८४९॥

आकुल सहचरी सोचती थी, क्या युक्ति करें जिससे, प्रियतम ! 
इसके जीवन की अब आगे हो किसी भाँति रक्षा, प्रियतम ! 
ये प्राण नहीं तो साँवर के सहचर तुरंत होंगे, प्रियतम ! 
आच्छन्न और निरवधि होगा यह विश्व अँधेरे से, प्रियतम॥८५०॥

छाती उसकी फटती थी, पर बोली वह बाला से, प्रियतम ! 
‘री बहिन ! चलें वनमें अब तो, हो गयी बड़ी देरी, प्रियतम ! 
हो सका न सुमन-चयन तक भी, कैसे पूजा होगी ? प्रियतम ! 
साँवर एकाकी खड़े-खड़े होते उदास होंगे।’ प्रियतम॥८५१॥

दृग में प्रफुल्लता कृत्रिम की मुद्रा लेकर वह थी, प्रियतम !
कृत्रिम उल्लास गिरा में भी उसकी था भरा हुआ, प्रियतम !
यों बार-बार बाला का कर झकझोर रही वह थी, प्रियतम !
जैसे-तैसे उसके मन को दे रही भुलावा थी, प्रियतम॥८५२॥
 
दैवी इच्छासे कुछ पल में बाला की वृत्ति फिरी, प्रियतम !
कुछ देर एकटक से उसने उसके मुख को देखा, प्रियतम !
एवं पहचान उसे बोली ‘री ! स्वप्न एक मैंने, प्रियतम !
देखा अत्यन्त भयंकर है, ये प्राण काँपते हैं, प्रियतम॥८५३॥

क्या होनेवाला है सचमुच वैसा ही अभी यहाँ, प्रियतम !
दुःस्वप्नों का परिहार अरी ! कोई अमोघ कह दे, प्रियतम !
मैं करूँ तुरंत उसे पहले, वन में फिर जाऊँगी, प्रियतम !
साँवर हों नित्य सुखी, मेरा जो होना हो सो हो’, प्रियतम॥८५४॥

इतने में रथ के पहियों का दीखा वह चिह्न उसे, प्रियतम ! 
कृत्रिम फुल्लता सखी की वह ठग सकी न अब उसको, प्रियतम ! 
गम्भीर हुई बाला, उर की ज्वाला फिर धधक उठी, प्रियतम ! 
आयी इसबार किंतु बाहर धरकर अभिनव बाना, प्रियतम॥८५५॥

बोली वह-‘अरी ! देख, कौआ कह रहा मुझे कुछ है, प्रियतम !
साँवर सुख से तो पहुँच गये, इतना मैं समझ सकी, प्रियतम ! 
आगे तू पूछ उसे, क्या वह मर गया दनुज राजा ? प्रियतम ! 
चल पड़े यहाँ के लिये तथा साँवर रथ पर कि नहीं ?’ प्रियतम॥८५६॥

दृग लगे पुनः पथराने से उसके इतने में ही, प्रियतम ! 
उसकी यह दशा देख, सखियाँ ‘रे हाय !’ पुकार उठीं, प्रियतम ! 
इसका परिणाम अवश्य हुआ सुन्दर, जो द्वार मिला, प्रियतम ! 
आँखों से उसके दुख को भी बाहर बह चलने का, प्रियतम॥८५७॥

सहसा वह फूट-फूटकर के विह्वल ऐसी रोयी, प्रियतम ! 
जो एक साथ पशु-पक्षीतक रोने लग गये वहाँ, प्रियतम ! 
मानो वह कालकूट विष हो भर गया पवनमें ही, प्रियतम ! 
‘चें-चें’ कर अहो ! लगा खगकुल भद-भद गिरने तरु से, प्रियतम॥८५८॥

नादित उस ओर हुआ क्षणभर वन महाघोर रव से, प्रियतम ! 
एवं गिर गये अचेतन हो सब वन्य चतुष्पद भी, प्रियतम ! 
केवल बाला के, सखियों के क्रन्दन का रव ही था, प्रियतम ! 
पूरित उन सभी दिशाओं में, निस्पन्द् बने तरु थे, प्रियतम॥८५९॥

वैसे ही रोती हुई चली आगे अब वह वनमें, प्रियतम ! 
रथके पहिये की रेखाको पकड़े, रुक-रुक करके, प्रियतम ! 
जितनी-सी व्यथा वारि बनकर बाहर आ जाती थी, प्रियतम ! 
मानो उसका अनुपात लिये पदमें थी गति आती, प्रियतम॥८६०॥

यद्यपि सहेलियाँ उसको थीं वे सतत सँभाल रही, प्रियतम ! 
फिर भी कितनी ही बार गिरी खाकर पछाड़ वह तो, प्रियतम ! 
ग्राहक जब चला गया तनका क्यों फिर वह उसे रखे, प्रियतम ! 
निष्प्राण-सदृश उसको अब तो सखियों को ढोना था, प्रियतम॥८६१॥

पथ वही न जाने कितना था हो गया आज लंबा, प्रियतम !
आता न अन्त उसका था, वह सरिता न दीखती थी, प्रियतम !
उस रत्नशैल को छू-छूकर बहती वह जिस थल से, प्रियतम ! 
बाला जब वहाँ पहुँच पायी, लग रही दुपहरी थी, प्रियतम॥८६२॥

इन घड़ियों में बाला ने था जो करुण विलाप किया, प्रियतम ! 
कितना वह हृदयविदारक था, क्या सखियों पर बीती, प्रियतम ! 
बाला एवं उनमें फिर थे जो-जो संवाद हुए, प्रियतम ! 
इसको सुनकर फिर तुम आगे क्या और सुन सकोगे ? प्रियतम॥८६३॥

अतएव न वह कहकर, नीली कल-कल-निनादिनी की, प्रियतम ! 
लहरों में जैसे अवगाहन बाला ने किया कहूँ, प्रियतम ! 
आकर उस तट पर खड़ी हुई जिस पर गिरिवर अपना, प्रियतम ! 
धो रहा चरण था, बाला ने अपनी अञ्जलि भर ली, प्रियतम॥८६४॥

मस्तक पर वारि बिखेर, अहो ! बोली वह सरिता से, प्रियतम ! 
‘री बहिन ! आज मैं आयी हूँ तेरे समीप रोने, प्रियतम !
देगी तू मुझे उरस्थल की किंचित् शीतलता क्या ? प्रियतम ! 
जल रहे प्राण-तन हैं मेरे, क्षणभर शीतल ये हों, प्रियतम॥८६५॥

मैंने तेरा अपराध किया, मैं गर्व भरी तब थी, प्रियतम !
साँवर को नित्य साथ पाकर फिरती इठलाती थी, प्रियतम !
अधिकार नील तन पर करके मेरी मति बौरायी, प्रियतम !
कितनी ही बार तुझे पद से मैंने ठुकराया है, प्रियतम॥८६६॥

नीला श्रीमुख दृगमें रखकर तेरी परवाह न की, प्रियतम !
नीला कर अहो ! कण्ठ में था गिनती न तुझे मैं थी, प्रियतम !
नीले तन-सौरभ से माती आयी न पास तेरे, प्रियतम ! 
नीले तरु पर समुदित फल का रस पी, न मिली तुझसे, प्रियतम॥८६७॥

नीले मुखका मधुरव सुनती, कल-कल न सुना तेरा, प्रियतम ! 
नीला था अङ्क मिला, तेरी गोदी न सुहाती थी, प्रियतम ! 
नीले कर सेते थे पद को, सेवा न रुची तेरी, प्रियतम ! 
नीली वह अलकावलि हरती श्रमकण, भूली तुझको, प्रियतम॥८६८॥

मेरी निधि वह छिन गयी किंतु, हूँ अब भिखारिणी मैं, प्रियतम ! 
जो सत्य महारानी कल थी इन सब निकुञ्ज वनकी, प्रियतम ! 
मेरा सब गर्व चूर होकर हूँ बनी आज दीना, प्रियतम !
सोने अब आयी हूँ तेरी शीतल गोदी में ही, प्रियतम॥८६९॥

तू मुझे निराश नहीं करना, तू मुझे न ठुकराना, प्रियतम !
मुझसे जो हुआ अनादर है, उसको बिसार देना, प्रियतम !
अपनी अप्रतिम शीलता से निस्सीम अनुग्रह से, प्रियतम !
तू ठौर मुझे देना अपने नीले, शीतल उर में, प्रियतम॥८७०॥

सोने से पहले कुछ बातें मैं और तुझे कह दूँ, प्रियतम !
तू दयामयी है, कर देना मेरी यह सेवा भी, प्रियतम !
मुझसे हों अलग भले साँवर, वे तुझे न छोड़ेंगे, प्रियतम !
तू तो है, बहिन ! वहाँ भी, वे अब जिस नगरीमें हैं, प्रियतम॥८७१॥

आयेंगे वे अवश्य तेरे रस से शीतल होने, प्रियतम !
उनके पदपद्मों की रजसे भूषित मैं हो न सकी, प्रियतम !
मेरी यह अभिलाषा पूरी अब तू ही कर देना, प्रियतम !
मेरे प्राणों में प्राण मिला, उनके पद धो देना, प्रियतम॥८७२॥

कुछ गुप्त हेतुओं से वह सुख उनको मैं दे न सकी, प्रियतम ! 
वे अहो ! तरसते चले गये, होकर निराश मुझसे, प्रियतम ! 
पूरी उमंग देकर उनको ले सकी न मैं उर में, प्रियतम ! 
मेरे प्राणों में प्राण मिला, तू वह सुख दे देना, प्रियतम॥८७३॥

रह गयी सोचती ही मैं तो, उनका अभिषेक करूँ, प्रियतम !
आखिर वे चले गये, अवसर यह किंतु नहीं आया, प्रियतम !
झूलेगी मुखपर कृष्ण-कुटिल अलकावलि वैसी ही, प्रियतम ! 
मेरे प्राणों में प्राण मिला, तू उसे सिक्त करना, प्रियतम॥८७४॥

लोलुप वे सदा बने रहते मेरे मुख-सौरभ के, प्रियतम ! 
उस ओर सदा घेरे रहती अतिशय लज्जा मुझको, प्रियतम ! 
उनका न मनोरथ वह पूरा कर सकी आज तक मैं, प्रियतम ! 
मेरे प्राणों में प्राण मिला, तू ही अब यह करना, प्रियतम॥८७५॥

सोने लगती निकुञ्ज में जब, उनकी इच्छा होती, प्रियतम ! 
ऐसा कोई मैं चित्र लिखूँ जो नित्य नवीन बने, प्रियतम ! 
उनका मुख ही ऐसा था, मैं उर पर लिख भी देती, प्रियतम ! 
मेरे प्राणों में प्राण मिला, तू उसे दिखा देना, प्रियतम॥८७६॥

सुस्पर्श अप्रतिम है क्या वे मुझसे पूछा करते, प्रियतम !
उनके अङ्गों का ही अनुभव मुझको तो होता था, प्रियतम !
वाणी तो नहीं, चपलता यह तन की कह देती थी, प्रियतम !
मेरे प्राणों में प्राण मिला, तू भी बतला देना, प्रियतम॥८७७॥

रजनी के समय सदा वे थे करते विनोद मुझसे, प्रियतम ! 
‘वल्लभे ! कहो तुम, गाती क्या यह गीत वंशिका है ?’ प्रियतम !
मैं कहती – ‘शिव हरि मार बिन्दु मम नाम सम्पुटित है’ प्रियतम ! 
मेरे प्राणोंमें प्राण मिला, तू कल-कलमें कहना, प्रियतम॥८७८॥

प्रति रजनी में था प्रश्न और उत्तर अवश्य होता, प्रियतम ! 
केवल भाषा बदली रहती, ‘है चित्-पीयूष कहाँ ?’ प्रियतम !
दो अरुण नवल पल्लव में ही, तू भी यों ही कहना, प्रियतम ! 
मेरे प्राणों में प्राण मिला, तू यह सेवा करना, प्रियतम॥८७९॥

मेरे उरपर कर-किसलय से कर्पूर-विलेपन वे, प्रियतम !
देने लगते, उनकी आँखें झर-झर झरने लगतीं, प्रियतम !
मैं व्यस्त पोंछती जाती थी, तू भी ऐसे करना, प्रियतम ! 
मेरे प्राणों में प्राण मिला, अपने समीर-कर से, प्रियतम॥८८०॥

प्रातः की बेला में मेरी आँखों में वे आते, प्रियतम !
गो दुहते-से होकर, पलकें उनको ढक लेती थीं, प्रियतम !
गोकुल परितृप्त बने, तबतक तू भी उनको ढकना, प्रियतम !
मेरे प्राणों में प्राण मिला, तट के द्रुमजालों से, प्रियतम॥८८१॥

दिन के दूसरे पहर में वे रहते अरण्य में थे, प्रियतम !
मेरा प्यारा भाई मेरी करता सहायता था, प्रियतम !
प्रेषित मैं एक पत्र करती, तू भी अवश्य करना, प्रियतम !
मेरे प्राणों में प्राण मिला, नलिनों पर लिख करके, प्रियतम॥८८२॥

होती अर्चना दिवाकर की अपराह्नकाल में थी, प्रियतम !
मेरी आशा-वल्लरी हरी क्रमशः होने लगती, प्रियतम !
मैं अर्घ्य तरणि को देती थी, तू भी अवश्य देना प्रियतम !
मेरे प्राणों में प्राण मिला, लहरें उछाल करके, प्रियतम॥८८३॥

संध्या के समय दीखते वे कानन से घर आते, प्रियतम !
मेरे समीप आते ही वे कन्दुक उछाल देते, प्रियतम !
अञ्जलि में उसे पकड़ लेती मैं, तू भी यों करके, प्रियतम !
मेरे प्राणों में प्राण मिला, उनको प्रसन्न करना, प्रियतम॥८८४॥

होता प्रदोष में अनुभव, वे मुझको हैं ढूँढ़ रहे, प्रियतम !
नीली या उजली साड़ी मैं तत्काल पहर लेती, प्रियतम !
संकेत जोहती उनका फिर, तू भी ऐसा करना, प्रियतम !
मेरे प्राणों में प्राण मिला, उनको न खिन्न करना, प्रियतम॥८८५॥

मिलना होता निशीथ में, वे उस समय भूल जाते, प्रियतम ! 
अपना स्वरूप, कहने लगते, ‘मैं रमणी हूँ, रमणी !’ प्रियतम !
मैं चेत कराती थी उनको, तू भी सतर्क रहना, प्रियतम !
मेरे प्राणों में प्राण मिला, उनको सँभाल लेना, प्रियतम॥८८६॥

उस अपररात्र में भावों की आँधी आ जाती थी, प्रियतम !
जिसके प्रवाह में मन उड़ता अत्यन्त दूर उनका, प्रियतम ! 
मैं साथ-साथ उड़ चलती थी, तू भी यों उड़ चलना, प्रियतम ! 
मेरे प्राणों में प्राण मिला, उनको रस में भरना, प्रियतम॥८८७॥ 

लगते ही उषा, परस्पर की पूजा चलने लगती, प्रियतम ! 
होता स्वरूप-विनिमय पूरा, प्राणों का, तन का भी, प्रियतम ! 
क्षण में फिर पहले-सा बनता तू भी बन-बनकर यों, प्रियतम ! 
मेरे प्राणों में प्राण मिला, यह सेवा भी करना, प्रियतम॥८८८॥

सुन्दरी एक-से-एक बढ़ी उनमें अनुरागवती, प्रियतम ! 
इस वनमें बसती थीं अपना सर्वस्व दिये उनको, प्रियतम ! 
मैं सबको अहो ! मिलाती थी, तू भी व्रत ले लेना, प्रियतम ! 
मेरे प्राणों में प्राण मिला, साँवर-सुख-वर्धन का, प्रियतम॥८८९॥

इतना सब कहने का केवल उद्देश्य, बहिन ! यह है, प्रियतम ! 
जो सेवा मैं कर सकी नहीं, जो प्रतिदिन थी करती, प्रियतम ! 
उन सबका भार एक तुझपर हूँ डाल रही अब मैं, प्रियतम ! 
तू भला, अनन्तकाल तक यह कर्तव्य निभा देना प्रियतम॥८९०॥

तुझसे मैं नित्य एक रहकर यह सब देखूँगी ही, प्रियतम ! 
तू किंतु न यह उनको कहना, हूँ मिली हुई तुझमें, प्रियतम ! 
होंगे संकुचित नाथ मेरी प्रच्छन्न उपस्थिति से, प्रियतम ! 
तू सावधान रहना हरदम, लगने न गन्ध देना। प्रियतम॥८९१॥

कोई उपाय कर सके, बहिन ! तो तू अवश्य करना, प्रियतम !
वे मुझे सदा के लिये अहो ! मनसे निकाल पायें, प्रियतम ! 
मैं थी न कभी, मैं हूँ न कभी, होऊँगी मैं न कभी, प्रियतम ! 
उनकी हो चित्तवृत्ति ऐसी, चिन्ता न रहे मेरी, प्रियतम॥८९२॥

मेरे प्राणाधिक सुखी रहें निरवधि, मैं यह देखूँ, प्रियतम ! 
इसके अतिरिक्त नहीं मेरी कोई थी चाह कभी, प्रियतम ! 
है नहीं, न होगी ही, मैं यह हूँ सत्य-सत्य कहती, प्रियतम ! 
तेरे नीले उर पर एवं लिख भी यह देती हूँ, प्रियतम॥८९३॥

कोई न सुने, देखे न इसे क्षणभर भी, क्या इससे, प्रियतम ! 
तू तो सुनती ही है एवं तू देख रही भी है, प्रियतम ! 
तुझसे भी मैं कहती न भला, निरुपाय किन्तु मैं थी, प्रियतम ! 
उनकी सँभाल की चिन्ता थी, अतएव सुना बैठी, प्रियतम॥८९४॥

भावों की लहरों का कोई इतिवृत्त न होता है, प्रियतम ! 
भावों की ये तरंग आती सीमा में हैं न कभी, प्रियतम ! 
जो प्राण एक-से हैं अपने उरमें नीलिमा लिये, प्रियतम ! 
उन-उन में ये संक्रमित अहो ! उन-उनसे होती हैं, प्रियतम॥८९५॥

री बहिन ! नीलिमा है पूरित तेरे तो कण-कण में, प्रियतम ! 
अतएव आज आकुल तुझसे अपना उर खोल गयी, प्रियतम ! 
तू भूल न जीवन में जाना मेरी इन बातों को, प्रियतम ! 
जो लहर विलीन हुई, वह तो आयेगी नहीं कभी।’ प्रियतम॥८९६॥

बाला यों कहकर, कर जोड़े, जलमें पद रख, बैठी, प्रियतम ! 
केवल दो सहचरियोंमें ही प्राणों की क्रिया बची, प्रियतम ! 
उसके थी साथ एक पीछे-पीछे बढ़ती जाती, प्रियतम ! 
थी एक खड़ी तट पर पूरी जड़ होकर देख रही, प्रियतम॥८९७॥

बाला ज्यों-ज्यों आगे बढती, जल था बढ़ता जाता, प्रियतम ! 
डूबी कटि, डूब गया क्रमशः उसका वक्षःस्थल भी, प्रियतम !
उल्लास भरी ऊँचे स्वरमें रह-रहकर वह हँसती, प्रियतम !
उसके श्रीमुख से एवं यह वाणी झरती जाती, प्रियतम॥८९८॥

‘साँवर साँवर ही आगे हैं, साँवर ही पीछे हैं, प्रियतम !
साँवर-साँवर ही दहिने हैं, साँवर ही बायें हैं, प्रियतम !
साँवर-साँवर ही नीचे हैं, साँवर ही ऊपर हैं, प्रियतम !
साँवर-साँवर ही अब केवल सर्वत्र अवस्थित हैं’, प्रियतम॥८९९॥

नीला जल लगा चिबुक छूने चञ्चल हो-हो करके, प्रियतम !
उसके कर-नलिनों की अञ्जलि ऊपर की ओर उठी, प्रियतम ! 
उसके पीछे-पीछे सटकर जो एक जा रही थी, प्रियतम ! 
बालाको उसी सहेली ने भर लिया भुजाओं में, प्रियतम॥९००॥

नीली लहरें अब बाला के सिर पर से प्रसरित थीं, प्रियतम !
वैसी ही वह फिर भी आगे-आगे बढ़ती जाती, प्रियतम ! 
मणिबन्ध-अंश पीली अञ्जलि केवल थी दीख रही, प्रियतम ! 
धीरे-धीरे वह भी नीली लहरों में लीन हुई, प्रियतम॥९०१॥

इतने में प्रगट हुईं अम्बा, गैरिकवसना जो थीं, प्रियतम ! 
फैली चिन्मयी नयी माया, तत्काल दृश्य बदला, प्रियतम ! 
कल-कल-निनादिनी का जल वह घट गया विपल में ही, प्रियतम ! 
बाला को लिये अङ्क में वे आ रही किनारे थीं, प्रियतम॥९०२॥

वह डूबी हुई सखी भी थी उनके पीछे-पीछे, प्रियतम ! 
वे महिमामयी उठीं तट पर, उनके दृग पड़े वहाँ, प्रियतम ! 
सबके प्राणोंमें गति आयी, सबको वे लिये चलीं, प्रियतम ! 
आया सुन्दरी-सरोवर का वह कूल अर्धपल में, प्रियतम॥९०३॥

सबको वे वहाँ विराजित कर करुणा से भरी हुई, प्रियतम !
बोलीं- ‘धीरज, धीरज’ मेरी पुत्रियों ! रखो, देखो। प्रियतम !
इस महादुःख की रजनी का होकर अवसान, उषा, प्रियतम !
आयेगी, साँवर से मिलकर सुखिनी तुम सब होगी।’ प्रियतम॥९०४॥

वे अम्बा इतना ही कहकर अन्तर्हित हुईं तथा, प्रियतम !
रत्नावासों से भरा हुआ वह, गाँव अदृश्य हुआ, प्रियतम !
उसके वन-परिसर पर भी कुछ अभिनव माया फैली, प्रियतम ! 
उसकी सत्ता होती न वहाँ उपलब्ध सभी को थी, प्रियतम॥९०५॥

बाला को, उसकी सखियों को मानो सब भूल गये, प्रियतम ! 
थीं कौन कहाँ बसती वे, थे माँ-बाप कौन उनके, प्रियतम ! 
दैनंदिन जीवन था उनका क्या, कहाँ गयीं अब वे, प्रियतम ! 
आवरण सभी इन बातों पर आया सबके मन में, प्रियतम॥९०६॥

अज्ञात सभी को थी घटना बिरजा की धारा की, प्रियतम !
उस महाभाव की क्रीड़ा का इतिहास अप्रकट था, प्रियतम !
आकुल फिर वनवासीजन थे साँवर के जाने से, प्रियतम !
यह तो विधान ही था विधि का, अतएव हुआ ऐसा, प्रियतम॥९०७॥

था चारों ओर अँधेरा ही, यद्यपि सित रजनी थी, प्रियतम !
यों चार पहरके अन्तर से उग आये दिनकर भी, प्रियतम ! 
वे, किंतु निरन्तर मुँदी हुई बाला की आँखें थीं, प्रियतम !
काली थी उसके लिये निशा अब सौ वर्षों वाली, प्रियतम॥९०८॥

कैसे, प्राणाधिक कहूँ अहो ! उन करुण चरित्रों को, प्रियतम ! 
आगे के, प्राणों में पल-पल चल रही टीस अब है, प्रियतम !
थोड़ा-सा फिर भी कहना है, तुम चाह रहे जो हो, प्रियतम !
ले प्यार नित्य तुमसे ही तो देती हूँ मैं तुमको, प्रियतम॥९०९॥
''',
      ),
      BookPage(
        title: 'दशम शतक',
        content: '''वह उजड़ गया वन था जिसमें बहती रसकी धारा, प्रियतम ! 
था हा-हाकार भरा उसमें असहाय अनाथों का, प्रियतम ! 
ज्वालामय पवन बना रहता जलते प्राणों को छू, प्रियतम !
वे अटके थे, बस, आशा पर आने की साँवर के, प्रियतम॥९१०॥

रञ्जित तमोल से ओठ न थे, चितवन अब वक्र न थी, प्रियतम ! 
घुँघराले कच की लहर न थी बल खाती वेणी की, प्रियतम ! 
झनकार न थी आभूषण की वीणा-जैसे स्वर की, प्रियतम ! 
नीले-पीले परिधानों की थी ज्योति न अब वन में, प्रियतम॥९११॥

अब सिरिस-कुसुम सुकुमार अङ्ग थे नहीं प्रभावाले, प्रियतम ! 
था अस्थिमात्र मानो लिपटा धूमीले वसनों में, प्रियतम ! 
पतला-सा सोता आँखों से हरदम चलता रहता, प्रियतम ! 
मुरछा से वेग कभी उसका थमता, फिर बढ़ जाता, प्रियतम॥९१२॥

थे बने विहङ्गम मूक, गीत गाती न कोकिला थी, प्रियतम ! 
शुक था नीरव रहता, सारी पढ़ती न पाठ अब थी, प्रियतम ! 
‘मिल लो गोपी तुम’, एक नहीं रटता पिरोइयाँ था, प्रियतम ! 
मधुलिह भी भूल गया अब था उड़ना गुन-गुन करना, प्रियतम॥९१३॥

सब सूख गयी थीं वल्लरियाँ, पादप की शाखाएँ, प्रियतम ! 
मुंडित योगी-सा वट विरहित पत्रों से था रोता, प्रियतम ! 
‘साँवर आते प्रतिदिन पहले मेरी ही छायामें’, प्रियतम ! 
‘फिर आ उनसे बाला मिलती’,यह बात याद करके, प्रियतम॥९१४॥

सूनी उदास बैठी रहती गिरिवर की दरी वहाँ, प्रियतम !
कमलों की सूखी शय्या पर आँखें अपनी डाले, प्रियतम !
आकर साँवर ने एक रात बाला को साथ लिये, प्रियतम !
विश्राम किया था इस पर ही, इस चिन्ता में डूबी, प्रियतम॥९१५॥

थे ऊर्मिहीन सर सब वनके, हिम-सा था हृदय जमा, प्रियतम ! 
गहरा था दुःख भरा उनमें, उस सुख के खोने का, प्रियतम !
साँवर आये थे मेरा रस अपनी अञ्जलि में ले, प्रियतम !
आधा बाला के मुख में भर, पी गये शेष फिर वे। प्रियतम॥९१६॥

चलता रवि तप्त हुआ धीरे, साँवर के बिना उसे, प्रियतम ! 
बाला के द्वारा अर्घ्यदान करवा कर कौन कहे, प्रियतम ! 
इनके निमित्त मैं पा तुमको हूँ ऋणी सदा इनका, प्रियतम ! 
संकल्प अतः है, पूजित हों चिरकाल सभी से ये, प्रियतम॥९१७॥

था योग, अहो ! मयंक ने ही आदर पाकर उससे, प्रियतम ! 
साँवर को ब्रह्मनिशा तक सित किरणों से सिक्त किया, प्रियतम ! 
अब वन में उसकी ओर किंतु बाला न देखती थी, प्रियतम !
उठती थी आह अतः उरमें, ठंडापन था न रहा, प्रियतम॥९१८॥


बड़भागी जगत्-प्राण यह है, बाला के अङ्गों के, प्रियतम !
भीतर-बाहरका छू सौरभ, कहकर साँवर हँसते, प्रियतम ! 
वह रसिक न था, अब फूल न थे, बाला तन पर वन में, प्रियतम ! 
बहता सुवास से रहित अतः होकर वह वैरागी, प्रियतम॥९१९॥

साँवर कहते कुछ बाला से, भरते रव मुरली में, प्रियतम ! 
मेरे गुण का था अर्थ तभी सत्ता का इस वन में, प्रियतम !
पर कहाँ गयी ध्वनि अब वह, कुछ था समझ नहीं पाता, प्रियतम !
इसलिये व्योम चिन्तित असङ्ग केवल ‘हा-हा’ करता, प्रियतम॥९२०॥

जो उस अरण्यके अधिवासी, उद्भिज्ज, जरायुज या, प्रियतम !
प्राणी अण्डज थे, उन सबका मन था न रहा तन में, प्रियतम !
उड़कर साँवर के मुखपर था मँडराता चला गया, प्रियतम !
थी छाँह बची केवल उसकी रोने के लिये वहाँ, प्रियतम॥९२१॥

क्या है कैसा सन्मुख अनुभव बाहर का दूर रहे, प्रियतम ! 
होता न किसी को भान वहाँ अपनेपन का भी था, प्रियतम ! 
संसार मिटा, व्यवहार गया, जीवन का चिह्न बचा, प्रियतम ! 
उनमें जो आह, अश्रुधारा निस्सृत होती रहती, प्रियतम॥९२२॥

कैसे लिख दूँ उन चित्रों को वाणी की तूली से, प्रियतम ! 
लिखने बैठी वह, किंतु नहीं चलती इससे आगे, प्रियतम ! 
कानन के कण-कण में जो है वह दुःखभरी जड़िमा, प्रियतम ! 
प्राणों में लगी पुनः भरने कहने से दृग-तनमें, प्रियतम॥९२३॥

जो कहीं ठहर जाऊँ किंचित्, लेकर मनमें इसको, प्रियतम ! 
होगी फिर तो इति अभी यहीं बाला की गाथा की, प्रियतम ! 
रह जायें अहो ! फिर सुन्दरतम बातें आगे की वे, प्रियतम ! 
रोये यह देश, नगर, जिसमें घर था कच्चा उसका, प्रियतम॥९२४॥

अतएव तनिक वन से हटकर, परदेसी की चर्चा, प्रियतम ! 
करती हूँ जो था साँवर का वह दूत नवीन बना, प्रियतम !
सुन्दर था श्याम रंग उसका, भूषित था साँवर-सा, प्रियतम !
कुछ बात वहाँ करने-कहने बाला से था आया, प्रियतम॥९२५॥

प्रेरित हो प्रेरक से उरके कोई बोली दीना, प्रियतम ! 
‘आया क्या वही पुनः, जो था साँवर को ले भागा ?’ प्रियतम ! 
स्वर करुण कण्ठ से ज्यों निकला, वन में वह गूँज उठा, प्रियतम ! 
फिर एक साथ सबकी आँखें खुल गयी अचानक थीं, प्रियतम॥९२६॥

वे लगीं देखने उस पथ को, साँवर थे जिधर गये, प्रियतम !
था समय वही प्रातःका ही, वे बिदा हुए जब थे, प्रियतम ! 
उनके समक्ष था एक खड़ा कोई प्रणाम करके, प्रियतम ! 
चुपचाप हाथ जोड़े, मानो गूँगा हो सत्य अहो ! प्रियतम॥९२७॥

वे देख रही उसको थीं, वह उनको था देख रहा, प्रियतम ! 
कुछ बोल नहीं पाता वह था, दुख की दाझी वे थीं, प्रियतम ! 
जब चार घड़ी थी बीत चुकी, इस भाँति कहा उसने, प्रियतम ! 
‘साँवर का हूँ मैं मित्र, मुझे भेजा उनने ही है।’ प्रियतम॥९२८॥
जैसे स्वर में सम बँधे हुए तन्त्रों के तारों को, प्रियतम !
अर्भक ले छेड़ चपल, सहसा झंकृत होते वे हैं, प्रियतम !
वैसे ही ‘साँवर’ नाम बना उनके श्रवणों में जा, प्रियतम !
उद्बुद्ध रागिणी भावों की करने में हेतु बना, प्रियतम॥९२९॥ 

कितना सम्मान मिला उनसे साँवर के सहचर को, प्रियतम !
अन्तस्तल से उनके निकला था स्नेह-उत्स कैसा, प्रियतम !
अभिषेक हुआ जिससे उसका, है उचित नहीं कहना, प्रियतम !
प्राणों में झाँक देख लेना वह खेल पुनः अपना, प्रियतम॥९३०॥

सुनना कुछ चाह रहे हो पर, फिर से जब मुझ से ही, प्रियतम ! 
इतिवृत्त महा है गोपनीय, किंचित् तथापि कह दूँ, प्रियतम ! 
दीपक की लौ-सी है रस की गति, जो मिट जाती है, प्रियतम ! 
हिलने लगती है या बाहर आकर समीर को छू, प्रियतम॥९३१॥

जो हो, विलाप के शुचि जलसे पद धुले दूत के थे, प्रियतम ! 
दौड़ी फिर अर्घ्य लिये वह थी मूर्छा दासी उनकी, प्रियतम ! 
आने पर होश सिसकियों ने आचमन कराया था, प्रियतम ! 
विधि रचित वारि-आसन से फिर हो सका समर्हण था, प्रियतम॥९३२॥

विस्फरित आँखों से बैठा वह दूत विमूढ़ हुआ, प्रियतम ! 
था देख रहा, वे सब उसकी करती प्रदक्षिणा थीं. प्रियतम !
दो घड़ी पुनः जब बीत गयी अद्भुत इस अर्चा में, प्रियतम ! 
थी प्रश्न कुशल का करने वह आ सकी गिरा खिन्ना, प्रियतम॥९३३॥

क्रमशः उमड़ा फिर भाव, लगीं सब वे कहने चरसे, प्रियतम ! 
साँवर कानन में थे कैसे रहते, क्या-क्या करते, प्रियतम ! 
साधारण-से-साधारण भी अतिशय नगण्य-सी थी, प्रियतम !
साँवर की दिनचर्या की जो घटना कहकर रोती, प्रियतम॥९३४॥

सुनकर सब बात दुःख उनका हरने वह दूत चला, प्रियतम ! 
खुल गयी ज्ञान की पेटी वह साँवर ने जो दी थी, प्रियतम ! 
सुन्दर सुबोध नवशैली से साँवर की व्यापकता, प्रियतम ! 
प्रतिपादन कर उनसे उनकी वह उक्ति कही उसने, प्रियतम॥९३५॥

‘मन रमा रहे तुम सबका ही केवल जिससे मुझमें, प्रियतम ! 
होकर नयनों का तारा मैं हूँ दूर बसा तुमसे’, प्रियतम ! 
सुनते ही लोचन बंद हुए कमलों-से उन सबके, प्रियतम ! 
आवेश एक उनमें आया अप्रतिम दिव्य सहसा, प्रियतम॥९३६॥

बाला उनसे घिर कर बैठी भावों में थी डूबी, प्रियतम ! 
आया है एक दूत केवल इतना थी जान सकी, प्रियतम ! 
आँखें न खुलीं, न हिली वह थी, अब तक इन बातों को, प्रियतम ! 
कितना सुन पायी, सुन न सकी अथवा, यह कौन कहे, प्रियतम॥९३७॥

सत्कृत अतुलित था दूत हुआ उसकी सखियों से ही, प्रियतम ! 
बाला की संनिधि में ही पर सब बात हुई यह थी, प्रियतम ! 
वह था तड़ाग का तीर अमल, जिस पर थी जुड़ी सभा, प्रियतम ! 
उत्तर की ओर किये मुख थीं बाला एवं सब वे, प्रियतम॥९३८॥

मुँह फेर दूत से, मान-राग-पूरित हो सहचरियाँ, प्रियतम ! 
मानो विस्मृत करके यह भी, है पुरुष यहाँ श्रोता, प्रियतम ! 
कुछ बात लगीं अपनी-अपनी बाला से बतलाने, प्रियतम ! 
साँवरके साथ हुई उनकी जो कुञ्जनिभृत में थीं, प्रियतम॥९३९॥

जब एक बोल कर पगली-सी हँसती या रो देती, प्रियतम ! 
हँसना-रोना उसका थमता, कहती थी अन्य तभी, प्रियतम ! 
जैसे कोई भीतरसे सच कहवाता हो उनसे, प्रियतम !
यों एक-एक कर सब-की-सब बोली जो थीं, सुन लो, प्रियतम॥९४०॥

ललितायाः उक्तिः -
साँवर अब भूल गये हैं री ! वह बात पान वाली, प्रियतम ! 
तू अर्ध दाँत से कर, मेरे अधरों पर रख बैठी, प्रियतम ! 
पीछे से आये, झटक लिया, खा गये और बोले, प्रियतम ! 
‘हो गया क्रीत मैं नित्यदास इस हिस्से के बदले’, प्रियतम ॥

अहो ! पश्य अस्माकं दुर्दैवं सम्प्रति क्रीतदासोऽपि निजस्वामिनीं प्रति ईदृशः ज्ञान-सन्देशप्रेषको भवति इत्युक्त्वा उन्मत्तेव हसति॥९४१॥

विशाखायाः उक्तिः -
क्यों याद करें, साँवर परिवा भादों कृष्णा की थी, प्रियतम !
थी केश सँवार रही तेरे, छिपकर वे कह भागे, प्रियतम ! 
‘जिनके कच हैं, करती जो है रचना, वे नित्य बसें, प्रियतम ! 
मेरे उरमें, निर्बाध करूँ उनके पद की सेवा’, प्रियतम॥९४२॥

चित्रायाः उक्तिः –
अब समझ गयीं, साँवर कहते कुछ हैं, करते कुछ हैं, प्रियतम ! 
तुझसे प्रेषित दिन में थी री ! मैं मिली, कहा उनने, प्रियतम ! 
‘परिशोध नहीं तुम दोनोंके ऋणका कर पाऊँगा, प्रियतम ! 
जैसे कह दोगी, जीवन भर, करके, संतोष करूँ’ प्रियतम ॥ 

जयतु वञ्चकशिरोमणिः नन्दनन्दनः इति निगद्य उन्मत्तेव अट्टहासः॥९४३॥

इन्दुलेखायाः उक्तिः -
थी रात अँधेरी, साँवर थे अञ्चल से उलझे-से, प्रियतम !
लज्जामें डूबी, बचनबद्ध तुझसे, पर मैं चुप थी, प्रियतम !
पड़कर चरणों में स्वीकृति वे मेरी थे चाह रहे, प्रियतम !
थी सन्धि हुई जिन शर्तों पर, हैं जला रही अब वे, प्रियतम॥९४४॥

चम्पकलतायाः उक्तिः -
भौंरा है, 'नहीं-नहीं, भौंरी', वह वाग्युद्ध-सा था, प्रियतम !
वे हार गये, मैं जीत गयी, तू ही थी पंच बनी, प्रियतम !
बन्धन वह अहो ! कुन्तलों से हाथों का कैसा था, प्रियतम !
क्या आशा थी सपने में भी, इतने झूठे वे हैं ? प्रियतम॥९४५॥

रंगदेव्याः उक्ति-
हेमन्तनिशा थी बीत चुकी, षष्ठी कृष्णा पहली, प्रियतम ! 
री ! मैं सपने में देवी की कर रही अर्चना थी, प्रियतम ! 
उस समय चपल हो बोले वे,‘हूँ नित्य बँधा मैं तो’, प्रियतम ! 
तत्क्षण मैं जगी, उक्ति सच थी, पर अब सब सपने की, प्रियतम॥९४६॥

तुङ्गविद्यायाः उक्तिः -
ऋतुराज-शिशिर की सन्धि हुई दो दिन पहले ही थी, प्रियतम ! 
मैं खड़ी अटारी पर थी, रवि थे क्षितिज छू रहे-से, प्रियतम ! 
री ! तू जाने, भ्रम हुआ मुझे या सत्य पधारे वे, प्रियतम ! 
उनका दुकूल बन्धक रखना, पर अर्थहीन अब है, प्रियतम॥९४७॥

सुदेव्याः उक्तिः -
दुपहरी ग्रीष्म की तपती थी, मेरा उर था तपता, प्रियतम ! 
तेरे प्रति री ! लखकर उनकी सुस्पष्ट वंचनाएँ, प्रियतम ! 
चन्दन-विलेप देकर वे थे हर रहे ताप तेरा, प्रियतम ! 
उस तालवृन्त पर के अक्षर उनके मिथ्या सब हैं, प्रियतम॥९४८॥

मञ्जुश्यामायाः उक्तिः -
री बहिन ! अङ्क से तेरे थी लग कर सोयी-जैसे, प्रियतम ! 
कैसे क्या था सब हुआ, उसे तू याद तनिक कर ले, प्रियतम !
तब से हूँ देख रही, मेरे उर में हरदम तू है, प्रियतम !
हैं नित्य बसे फिर वे तुझमें, रोती तथापि मैं हूँ, प्रियतम॥ 
भगिनि ! ममेयं भ्रान्तिः अथवा सत्यानुभूतिः इति न ज्ञायते त्वं तु यदा रोदिषि तर्हि अस्माकं प्रियतमः प्राणाधिकः प्राणेश्वरः प्राणवल्लभः नित्यनवनिकुञ्जेश्वरः नित्यवृन्दावनेश्वरः नन्दनन्दनः सम्प्रति मधुपुर्यां एव वसति इति निश्चीयते इति भगिनीं सम्बोध्य भगिन्याः अङ्के शिरः निधाय फूत्कारपूर्वकं क्रन्दनम्॥९४९॥

मधुमत्याः उक्तिः -
नीरस मेरा स्वर था, अब भी नीरस यह तो है ही, प्रियतम ! 
री ! पड़ती थी मधुमय तेरे स्वर की इस पर छाया, प्रियतम ! 
थे बिके सदा के लिये अतः वे मेरे हाथ भला, प्रियतम ! 
क्यों चले गये बहका मुझको, इसको वे ही जानें, प्रियतम॥९५०॥

विमलायाः उक्तिः -
मेरा गोरापन था प्यारा इतना कि एक दिन तो, प्रियतम !
वे खो बैठे स्वस्मृति तक भी मुझको निहारते ही, प्रियतम !
छुटा न रंग मेरे तन का, मन का, पर वे बदले, प्रियतम !
अपना ही साथ न देता है प्रतिबिम्ब अँधेरे में, प्रियतम॥९५१॥

श्यामलायाः उक्ति: -
था छिपा कलंकी शशि काले बादलकी ओट लिये, प्रियतम ! 
शङ्कित हो गृह-फुलवारी में मैं बाट जोहती थी, प्रियतम ! 
तेरी ही री ! सहचरी बनी अभिसारकारयित्रि, प्रियतम ! 
अर्पण युग कुड्मल करने का था मिलना लाभ यही, प्रियतम॥९५२॥

पालिकायाः उक्तिः -
थी नीलवारिधर ने ही यह यौवनवल्ली सींची, प्रियतम ! 
जब फूल लगे, सौरभ आया इसमें, तब चला गया, प्रियतम ! 
बोली थी यह,‘ठगना मत’, तब उसने था कहा, भला, प्रियतम ! 
‘सम्बन्ध टूटता है क्या, जो प्राणों का होता है ?’ प्रियतम॥९५३॥

भद्रायाः उक्तिः -
आँखें झप जाती थीं मेरी, मिलना वह था पहला, प्रियतम !
नीली किरणों का स्वागत कर पायी जैसे-तैसे, प्रियतम ! 
उनका था शील कि मेरा री ! विश्वास कर सकी जो, प्रियतम !
भादों सित तेरस की छट्ठी-पूजन की पद्धति में, प्रियतम॥९५४॥

धन्यायाः उक्तिः -
कितने युग तबसे बीत गये, कम्पन है वैसा ही, प्रियतम ! 
मेरे कर-पदमें सृष्ट हुआ जो उनके छूने से, प्रियतम ! 
उल्लास एक था, किंचित् सुख दे सकी कभी तुझको, प्रियतम ! 
वह मिटा, बात धोखा ही थी पूनो चैती निशि की, प्रियतम॥९५५॥

तारिकायाः उक्तिः: -
उस दिन ऐसी तन्मयता थी मेरे प्रति बढ़ी हुई, प्रियतम ! 
जो मेरी साँस चित्र उनके उरमें लिख देती थी, प्रियतम ! 
जब हुआ ज्ञान-रवि से ब्रजका भावित शशि नीला भी, प्रियतम ! 
तारक की आभा में तब है क्या भरी वही शोभा, प्रियतम॥९५६॥

रूपमञ्जर्याः उक्तिः -
‘लावण्य अरी ! त्रिभुवन में है अप्रतिम नित्य तेरा, प्रियतम ! 
हो रहा अनादिकाल से हूँ न्योछावर इसपर मैं’ प्रियतम ! 
है उक्ति निरर्थक उनकी यह भादों सित परिवा की, प्रियतम ! 
विश्वास करूँ किसका, कपटी जब हुए कुञ्जराजा, प्रियतम॥९५७॥

लवङ्गमञ्जर्याः उक्तिः -
लगते वसन्त की रजनी थी अँधियारी नवमी की, प्रियतम ! 
तेरे समीप उनको लेकर केवल मैं पहुँच सकी, प्रियतम ! 
किसका मुख-सौरभ वासित है करता निकुञ्जथल को, प्रियतम !
उनके उस रसमय कौतुक का है पर्यवसान यहाँ, प्रियतम॥९५८॥

चन्दनमञ्जर्याः उक्तिः -
है पारिजात सुरभित या ये तेरी कुञ्जित अलकें, प्रियतम !
निर्णय जैसे जो हुआ, उसे तू एक जानती है, प्रियतम !
पड़ गयी भुलावे में, तेरी ममता से दबी हुई, प्रियतम !
क्या पता मुझे था, उनकी यह झूठी अधीनता थी, प्रियतम॥९५९॥

कर्पूरमञ्जर्याः उक्तिः -
देकर उरका कण-कण उनकी मैंने रुचि थी रख दी, प्रियतम ! 
आषाढ़ी दूज असित का दिन कैसे मैं भूलूँगी, प्रियतम ! 
‘इस भाँति नित्य तेरे प्रति भी मैं नेह निभाऊँगा’ प्रियतम ! 
आशा यह जिसने दी थी, दी उसने ही तोड़ उसे, प्रियतम॥९६०॥

रतिमञ्जर्याः उक्तिः -
आमों में बौर लगा था, वे मुझसे थे पूछ रहे, प्रियतम ! 
अर्चन की विधि, मैं क्या उत्तर इसका देती उनको, प्रियतम ! 
मेरी वह किंतु मूक मुद्रा बन गयी धरोहर थी, प्रियतम ! 
उनकी ही वाणी में, पर अब समझी, वह चकमा था, प्रियतम॥९६१॥

गुणमञ्जर्याः उक्तिः -
विजयादशमी थी, उनकी भी जय हुई अनोखी थी, प्रियतम ! 
हारे-ही-हारे नित्य अरी ! तुझसे अबतक वे थे, प्रियतम ! 
उस दिन पर खिसक गयी कटि से, किङ्किणी अचानक ही, प्रियतम ! 
वे जीत गये, यह आज मिला है पुरस्कार मुझको, प्रियतम॥९६२॥

केलिमञ्जर्याः उक्तिः -
अञ्जन अनामिका से लेकर वे चले आँजने थे, प्रियतम !
तेरे लोचन, इतने में कर दोनों काँपे उनके, प्रियतम !
बायें को तू सँभालती थी, सुखमय अवलम्बन दे, प्रियतम !
दहिने को मैंने थामा था, उसका बदला यह है, प्रियतम॥९६३॥

विलासमञ्जर्याः उक्तिः -
शत-सहस निहोरों से दबकर, साहस बटोर पायी, प्रियतम ! 
नाची थी दस पल, नीरज-मुख उनका यह देख खिला, प्रियतम ! 
राका-शशि को साखी रखकर मेरे कर उर में ले, प्रियतम ! 
जो दान दिया था मुझे, मोल है रखता इतना ही, प्रियतम॥९६४॥

लासिकायाः उक्तिः -
‘कैसी होती है कविता यह, तुझमें मैं देख सका, प्रियतम ! 
अब निरवधि रस भरती रहना इन कर्णपुटों में तूँ' प्रियतम ! 
उनके मुख से निकला था यह, सुनकर वर्णन मेरा, प्रियतम ! 
तेरे दृग का, फूली मैं, पर थे भाल-लेख ऐसे, प्रियतम॥९६५॥

प्रेममञ्जर्याः उक्तिः -
तेरस आषाढ़ी शुक्ला का अपराह्नकाल वह था, प्रियतम !
आठों कुञ्जों में घूम-घूम अत्यन्त थकी मैं थी, प्रियतम ! 
प्रस्वेद भरा था गालों पर मेरे, समीर चुप था, प्रियतम !
उस समय मिले थे वे, पर यह सर्वथा भूल बैठे, प्रियतम॥९६६॥

कुन्दमञ्जर्याः उक्तिः -
मेरा हँसना उनको इतना प्रिय था कि हाथ रखते, प्रियतम ! 
मेरे चरणों पर, फिर भी जब मैं रोक हँसी लेती, प्रियतम ! 
कैसी-कैसी मुद्रा रचते, आखिर मैं हँस पड़ती, प्रियतम !
वह समझ न पायी, क्रन्दन की बन रही भूमिका थी, प्रियतम॥९६७॥

मञ्जुलीलायाः उक्तिः -
भूली-सी बैठी सोच रही थी, सत्य कौन मैं हूँ, प्रियतम ! 
फागुन शुक्ला षष्ठी का था मध्याह्न हुआ न अभी, प्रियतम ! 
पीयूष-सरित था, सागर था उमड़ा क्षणभर सहसा, प्रियतम ! 
है बड़वानल पर उसमें भी, जाकर अब समझ सकी, प्रियतम॥९६८॥

मदनसुन्दर्याः उक्तिः -
वह तेरे सरस सरोवर का मध्यस्थ कुञ्जथल था, प्रियतम ! 
श्यामा थी मेरे साथ, और मिलने आये वे थे, प्रियतम ! 
उनकी उस अतुल रसिकता का, फिर आज विरसता का, प्रियतम ! 
दोनों ही चित्र सामने हैं री ! हँसूँ कि रोऊँ मैं, प्रियतम॥९६९॥

पद्ममञ्जर्याः उक्तिः -
‘स्वर्णिम मृदुला इस वेली के उपयुक्त नीलतरु है, प्रियतम ! 
द्रुम यह निसर्ग का भी स्वभाव जब नहीं छोड़ता है, प्रियतम ! 
वे तो फिर अविचल हैं ही’, मैं बोली, वे भी बोले, प्रियतम ! 
था ‘एवमस्तु’ पर वह झूठा सावन सित बारस का, प्रियतम॥९७०॥

अशोकमञ्जर्याः उक्तिः -
सुन्दर अशोक की छाया में निर्मित निकुञ्ज वह था, प्रियतम ! 
री ! तेरे और साँवरी के वे बीच अवस्थित थे, प्रियतम ! 
‘हो नित्यसुहागिन तुम सब तो’, है उक्ति सत्य उनकी, प्रियतम ! 
सिन्दूर माँग पर हुतभुक्-सा जल रहा किंतु यह है, प्रियतम॥९७१॥

सुधामञ्जर्याः उक्तिः -
अनुरूप नामके ही तेरे है सुधाभरी तुझमें प्रियतम ! 
वे कहते थे, मैं भोली थी, यह सत्य मान बैठी, प्रियतम ! 
अतएव फुल्ल हो कह देती मैं मधुर खरी-खोटी, प्रियतम ! 
गजदन्त दिखाने-खाने के हैं दो, अब समझी हूँ, प्रियतम॥९७२॥

मोदिन्याः उक्तिः -
करती है जो गठबन्धन, वह लेती है नेग, भला' प्रियतम !
बोली मैं अभिनय में थी, फिर उनका उत्तर यह था, प्रियतम !
‘प्रियतमा नित्य तेरी हैं ही, मैं भी अब हूँ तेरा’, प्रियतम ! 
ऐसा ही अबतक लगा, किंतु है खेल खेल ही तो, प्रियतम॥९७३॥

माधव्याः उक्तिः -
उस दिन की आँखमिचौनी में तू निर्णय दे बैठी, प्रियतम !
अस्पृश्य हुए माधव हैं, ली छू लता माधवी ने, प्रियतम !
दो पल का वह वियोग उनको अखरा, बोले मुझसे, प्रियतम !
‘तू मुझे बचा ले और कीन ले’, क्या वह सपना था, प्रियतम॥९७४॥

शशिरेखायाः उक्तिः -
कानन मयंक-किरणोंसे था भूषित, मैं बैठी थी, प्रियतम !
वे राग भरे लोचन से थे मुझको ही देख रहे, प्रियतम !
‘तेरा अधरस्मित उज्ज्वल है सुन्दर शशिकर से भी’, प्रियतम 
उनका कहना दृगका झरना, कोरा मेरा भ्रम था, प्रियतम॥९७५॥

हारहीरायाः उक्तिः -
अवगाहन कर तू सर से थी निकली, जल-बूँदें थीं, प्रियतम !
तेरे कुन्तल से झरती, यह मैं देख कह उठी थी, प्रियतम !
‘है भरी कृष्णता जिसमें भी, चूता है रस उससे’, प्रियतम !
‘रीता पर फिर हो जाता है’, बोले वे, सच वह है, प्रियतम॥९७६॥

सुकेश्याः उक्तिः -
'इस शारदीय पूनो निशि में, उस इन्द्रनीलमणि को, प्रियतम ! 
मैं जडूँ जम्बुसरितावाली इस पुरट-अँगूठी में, प्रियतम ! 
कीमत मैंने यह चाही थी कुन्तल सँवारने की, प्रियतम !
‘ऐसा ही हो’ वे बोले, क्या था यही अर्थ उसका, प्रियतम॥९७७॥

कुन्दलतायाः उक्तिः -
मैं साध अनादि लिये यह थी मेरे उस परिणय का, प्रियतम ! 
उनके प्रच्छन्न पाणिधारण वाले उस अभिनय का, प्रियतम ! 
हो पर्यवसान नित्य तेरे, उनके सुखवर्धन में, प्रियतम ! 
था वचन दिया उनने भी, पर है सारहीन आशा, प्रियतम॥९७८॥

सौदामिन्याः उक्तिः–
उनके उत्तरको अब समझी, मैंने था प्रश्न किया, प्रियतम ! 
‘क्यों अहो ! प्रीति की गति सीधी होती है नहीं कभी’, प्रियतम ! 
‘साँचे के ही अनुरूप वस्तु रस की ढल जाती है’, प्रियतम ! 
‘टेढ़ा मैं हूँ, छू मुझे नित्य टेढ़ी चलती यह है’, प्रियतम॥९७९॥

हंसिन्याः उक्तिः -
‘मिलनेसे पहले अमिलन का रहता है दुःख बड़ा, प्रियतम ! 
मिलते ही किन्तु न रहता है दो-पन का भेद वहाँ’, प्रियतम !
जीवन की धारा ऐसी ही समझे बैठी मैं थी, प्रियतम ! 
अब पता लगा, शिक्षा उनकी वंचना भरी यह थी, प्रियतम॥९८०॥

सुलोचनायाः उक्तिः –
आँखों में तन्द्रा-सी आयी उनकी, मैंने देखा, प्रियतम ! 
विश्राम करें, जग-जगकर अब हो गये श्रमित ये हैं, प्रियतम ! 
अतएव बहाना कर अपने लोचन मैंने मूँदे, प्रियतम ! 
री ! तत्कालीन उक्ति उनकी क्या वह बनावटी थी, प्रियतम॥९८१॥

मञ्जुलायाः उक्तिः -
लोचन भर-भर आते उनके, पुलकित थे अङ्ग सभी, प्रियतम !
वे लिखते, पुनः मिटाते थे मृगमद के चित्रों को, प्रियतम ! 
केवल वक्षःस्थल चित्रण में पूरी हो गयी निशा, प्रियतम ! 
उल्लास दृगों का उस दिन का उनके क्या कृत्रिम था, प्रियतम॥९८२॥

चारुशीलायाः उक्ति: –
तेरी ग्रीवा में सुमनों का वे पदक धराते थे, प्रियतम ! 
मैं भूल गयी अपने को ही, होकर तन्मय उसमें, प्रियतम ! 
लौटी जब फिर इस तन में थी, हो चुकी दुपहरी थी, प्रियतम ! 
उनका मुझको उरमें भर वह सब कहना ठगना था, प्रियतम॥९८३॥

विद्युन्मालायाः उक्तिः -
‘है तड़ितपना तुझमें, मेरा है रंग नीलघन का, प्रियतम ! 
‘तेरा घर मेरा उर ही है, तू आ छिप जा इसमें’, प्रियतम ! 
उनने था कहा निशा में यह भादों सित षष्ठी की, प्रियतम ! 
मैं तो वैसी-की-वैसी हूँ, बदला पयोद नीला, प्रियतम॥९८४॥

सरोजिन्याः उक्तिः -
थी साँझ, महावर लगा रहे वे थे तेरे पद  में, प्रियतम ! 
उनका, मेरा मन डूब गया उस चिह्न सरोरुह में, प्रियतम !
जागे जब हम शशि चला गया, रवि लगा झाँकने था,प्रियतम ! 
था एक समय वह भी, अब है यह दिवस आज का भी, प्रियतम॥९८५॥

मदनालसायाः उक्तिः -
कोई क्या भाँप सकी अबतक, ऐसा होता क्यों था, प्रियतम ! 
आती जब तुझे जँभाई, दृग मीलित होते उनके, प्रियतम ! 
अपनी भावना सरस उनने थी कही एक मुझसे, प्रियतम ! 
पर थी विडम्बना मेरी वह सच होती, क्यों जाते, प्रियतम॥९८६॥

इन्दिरायाः उक्तिः -
दो घड़ी शेष रजनी थी, तू, मैं, वे-थे तीन जने, प्रियतम ! 
तू लेट गयी दृग बन्द किये, बैठी मैं थी, वे थे, प्रियतम ! 
रेखा है ऊर्ध्व वाम पद में तेरे जो, फल उसका, प्रियतम ! 
कह रहे कान में थे मेरे, झूठा क्या है वह भी, प्रियतम॥९८७॥

मनोहरायाः उक्तिः: -
हेमन्त-अष्टमी उजियारी थी प्रथम मासवाली, प्रियतम ! 
हिमकर निकुञ्जलतिका की ले था ओट नमन करता, प्रियतम ! 
संदेश तुझे कुछ देता था, अनुमति लेता-लेता, प्रियतम ! 
उस समय कह उठे थे वे जो मुझसे, कैसे भूलूँ, प्रियतम॥९८८॥

अवशिष्टानां सहचरीणां उक्तिः -
वैशाखी सित नवमी थी, यह देवी का स्वप्न हुआ, प्रियतम !
बहुकाल पुनीत उसी व्रत के परिणाम सभी हम हैं, प्रियतम !
साँवरने हमें जगाया था, लेकर भुजबन्धन में, प्रियतम ! 
बोले,‘इस नित्य मिलन की ही यह नित्यभूमिका है।’ प्रियतम॥९८९॥

सहसा सब सहचरियाँ क्रन्दन कर उठीं करुण इतना, प्रियतम ! 
जो बात दूत की दूर, विकल हो नीर सरोवर का, प्रियतम ! 
बढ़कर कूलों को प्लावित कर, छूकर कटि तक उनको, प्रियतम ! 
बह चला वनस्थल के द्रुम की मूलों से उलझ गया, प्रियतम॥९९०॥
 
‘साँवर का किंकर हूँ, ज्ञाता मैं परमतत्त्व का भी’, प्रियतम !
जो दूत लिये मन में यह था अभिमान, जला उसमें, प्रियतम ! 
साँवर से जुड़ा हुआ जीवन कैसा हो जाता है, प्रियतम !
वह आज तनिक-सा देख सका बाला की सखियों में, प्रियतम॥९९१॥ 

खुल गया द्वार अब अन्तर का, आलोक मिला सच्चा, प्रियतम ! 
लोचनके आगे छाया था जो तिमिर अनादि मिटा, प्रियतम ! 
साँवर हैं क्या ? बाला है क्या ? रस है क्या ? तत्त्व सही, प्रियतम ! 
यह मिला किसी को जिधर, वही पथ आज मिला उसको, प्रियतम॥९९२॥

बाला पुतली-सी बैठी थी, आँखों से रेखा-सी, प्रियतम ! 
अविराम भावना हृत्तल की विगलित हो थी आती, प्रियतम ! 
हो निर्निमेष वह दूत लगा भरने अपने दृग में, प्रियतम ! 
थोड़ी-सी भरते ही उसको अनुभूति विचित्र हुई, प्रियतम॥९९३॥

मानो बिजली-सी चमक गयी, पीला पट फहर उठा, प्रियतम ! 
साँवर का जो पहने वह थी लहँगा नीला, उसमें, प्रियतम ! 
फिर पीले अम्बर के अन्दर नीली साड़ी उसकी, प्रियतम ! 
थी स्यूत हुई, था भरा पुनः पीताभ चीर उसमें, प्रियतम॥९९४॥

नीले-पीले वसनों का क्रम निर्धारित हो जैसे, प्रियतम ! 
तह-पर-तह बने अतुल सज्जित अगणित अनन्त वे थे, प्रियतम ! 
फिर उसी तरह पदपृष्ठों की कोमल अंगुलियों की, प्रियतम ! 
स्वर्णिम छवि में घन था, घन में फिर थीं पिङ्गल लहरें, प्रियतम॥९९५॥

कटि से ऊपर आँखें जब थीं उठती, तब था लगता, प्रियतम ! 
बाला में हैं साँवर पूरित, साँवर में है बाला, प्रियतम ! 
भीतर, फिर भीतर, वैसे ही ज्यों-ज्यों दृग थे बढ़ते, प्रियतम ! 
क्रमशः असंख्य थे साँवर, थी क्रम से बाला उनमें, प्रियतम॥९९६॥

जब लगा दीखने था ऐसे उस दूत मनीषी को, प्रियतम ! 
हो गया भ्रमित, साँवर हैं या बाला सन्मुख मेरे, प्रियतम ! 
‘अधिदेवि ! पाहि हे, पाहि सदा साँवर के प्राणों की, प्रियतम ! 
देवी के देव ! पाहि’ कहकर ली मूँद आँख उसने, प्रियतम॥९९७॥

सुन पड़ी मधुरतम वंशी की इतने में तान उसे, प्रियतम ! 
जो निकट, निकटतर उसके थी क्रमशः होती जाती, प्रियतम ! 
मादकता भरी हुई उसमें ऐसी थी, जो न कहीं, प्रियतम ! 
थी मिली कभी उसको, मोहित होकर वह झूम उठा, प्रियतम॥९९८॥

लोचन बरबस खुल गये तथा दीखा सुन्दर वन है, प्रियतम !
गो-चारण कर धीरे-धीरे साँवर हैं लौट रहे, प्रियतम !
आ गये समीप, रही दूरी जब दो हाथों की ही, प्रियतम !
हँस पड़े और बोले,‘भैया ! मेरा घर तो यह है।’ प्रियतम॥९९९॥

‘देखो प्रस्तुत कर नीराजन, वह बाट देखती है, प्रियतम ! 
मेरी मैया आकुल,‘मेरा साँवर आता होगा’, प्रियतम !
केवल हैं तीन पहर बीते, लेकर अपनी गायें, प्रियतम ! 
मैं था अरण्यमें घूम रहा, चिन्ता में है जननी।’ प्रियतम॥१०००॥

दीखी प्रवाहिणी कृष्णा फिर लहराती थी बहती, प्रियतम ! 
शोभित निकुञ्ज सद्मों की थी अवली तट पर उसके, प्रियतम ! 
बाला के दक्षिण कंधे पर कर रखकर, साँवर थे, प्रियतम !
उससे कहते कुछ, थी बाला आँखों में प्यार लिये, प्रियतम॥१००१॥

दोनों हँसते फिर चले गये, आगे उसने क्या-क्या, प्रियतम ! 
देखा, कैसे कह दूँ सब कुछ, है बात बड़ी लम्बी, प्रियतम ! 
इतनी-सी कह देती हूँ, वह अनुभव कर धन्य हुआ, प्रियतम !
बाला को लेकर नित्य यहीं साँवर हैं खेल रहे, प्रियतम॥१००२॥

हो गये दिवस कितने उसको आये इस कानन में, प्रियतम ! 
हो गयी उसे विस्मृति इसकी, डूबा रहता रस में, प्रियतम ! 
बाला की सहचरियाँ जो कुछ कहतीं, सुनता रहता, प्रियतम ! 
बालाके सन्मुख जाकर तो केवल रोने लगता, प्रियतम॥१००३॥

किसलिये, अचानक भान हुआ, आया था यहाँ सही, प्रियतम ! 
निकली मन से फिर बात वहीं साँवर के रहने  की, प्रियतम ! 
ले रहा हिलोरें सागर था दुख का, जिसमें सब थीं, प्रियतम ! 
वे डूब रही, था पास खड़ा वह, याद रही इतनी, प्रियतम॥१००४॥

‘हूँ निपट अनधिकारी इनका दर्शन कर लेने का, प्रियतम !
सपने में भी’ अनुभव ऐसा अब दूत लगा करने, प्रियतम !
‘मौखिक शरणागति से ही वे साँवर ढर जाते हैं, प्रियतम !
अतएव दया कर दी उनने, मुझको ही भेज दिया, प्रियतम॥१००५॥

जाना है किंतु यहाँ से अब, मेरे-जैसा कोई, प्रियतम !
कैसे रह सकता है पद की छाया में बाला के, प्रियतम ! 
आँसू से जो सींचूँ उर को, चिरकाल रहे वर्षा, प्रियतम !
आशा मेरी वह एक कहीं अंकुरित भले तब हो, प्रियतम॥१००६॥

सुन सका न बाला की वाणी मेरा यह भाग कहाँ ? प्रियतम !
विनती करने का भी मुझको अधिकार नहीं, सच है, प्रियतम !
जो स्वतः कहीं कह दे कुछ यह, जीवन अनन्ततक का, प्रियतम !
सम्बल मिल जाय मुझे, फिर तो कोई न मिले मुझ-सा’,प्रियतम॥१००७॥

टप-टपझर कर दृग थे उसके अवनी गीली करते, प्रियतम !
मन-ही-मन विनय सुनाता था अत्यन्त अधीर हुआ, प्रियतम !
‘हे साँवर नाथ ! दया मुझपर इतनी-सी और करो’, प्रियतम !
‘ये श्रवण सदाके लिये तृषित रह जायँ नहीं मेरे।’ प्रियतम॥१००८॥

बाला की एक बहिन उससे छोटी जो थी श्यामा, प्रियतम !
करुणा की धारा से स्वर में कह उठी नहायी-सी, प्रियतम !
‘री बहिन, दूत अब जाता है साँवर की सेवा में’, प्रियतम !
‘उनका संदेश लिये यह था आया, तू भी दे-दे।’ प्रियतम॥१००९॥

सागर के नील अतल तल से ऊपर वह उठ आयी, प्रियतम !
अपनी उस बहिन कनिष्ठा की ठोड़ी को छू करके, प्रियतम !
रोती कुछ देर रही अतिशय विह्वल भरकर सुबकी, प्रियतम !
धीरज समयोचित धर उसकी फिर लाड़ चली रखने, प्रियतम॥१०१०॥
''',
      ),
      BookPage(
        title: 'एकादश शतक',
        content: '''अञ्चल से पोछ अश्रु, बोली बाला, लेकर माला, प्रियतम !
साँवर ने जो पहनायी थी जाते-जाते उसको, प्रियतम ! 
क्या दूँ संदेश, भला, उनको, अच्छा, कहना उनसे, प्रियतम !
सुख से रहना, सपने में भी छूये न शोक तुमको, प्रियतम॥१०११॥

है कुञ्ज हृदय यह बना हुआ, जिसमें रहते तुम हो, प्रियतम !
भ्रम होता है या सदा मुझे, मैं जान नहीं पायी, प्रियतम ! 
दो बनकर हो तुम खेल रहे या हूँ दीवानी मैं, प्रियतम ! 
निर्णय इसका अब कौन करे, कर लेना तुम मनमें, प्रियतम॥१०१२॥

सचमुच ही हो यदि चले गये दासी को छोड़ यहाँ, प्रियतम ! 
है उचित किया तुमने, तब तो पाओगे सुख इससे, प्रियतम !
सुन्दर तुम हो, दृग में, उर में, निर्मल अनुराग लिये, प्रियतम ! 
मुझमें सुन्दरता का भ्रम था हो गया अतः तुमको, प्रियतम॥१०१३॥

सद्गुण है मुझमें एक नहीं, दोषों की हूँ प्रतिमा, प्रियतम ! 
रीझे तुम थे फिर भी केवल मुझ पर, सबको भूले, प्रियतम !
लज्जा में गड़ जाती जब तुम देकर सर्वस्व मुझे, प्रियतम !
‘प्राणेश्वरि !’ कह उरमें भरते गुण-रूप-विरहिता को, प्रियतम॥१०१४॥

जब रूप नहीं, गुण-लेश नहीं, भ्रम दूर करूँ कैसे, प्रियतम ! 
कैसे समझाऊँ मैं तुमको, थी समझ नहीं पाती, प्रियतम ! 
फिर भी प्रतिदिन तुमसे इसका संकेत किया करती, प्रियतम !
थक जाती, जब लेती सँवार अपने इन अङ्गों को, प्रियतम॥१०१५॥

हो जाऊँ तनिक कदाचित् मैं सुन्दर सँवारने से, प्रियतम ! 
ये कहीं बसन-भूषण-चन्दन मेरा कुरूप ढक दें, प्रियतम !
आदर्श गुणों से भूषित जो सहचरियाँ हैं मेरी, प्रियतम ! 
उनको करती थी याद कहीं छू लूँ छाया उनकी, प्रियतम॥१०१६॥

होता था किंतु सदा ही यह अनुभव न, बनी मैं हूँ, प्रियतम !
गुणवती, सुरूपा, जिसको तुम दे दो सब कुछ अपना, प्रियतम !
इतने पर भी था प्यार मिला मुझको तुमसे ऐसा, प्रियतम ! 
जो ले न सकी अबतक कोई, आगे तुम ही जानो, प्रियतम॥१०१७॥

अतएव सत्य ही हो यदि तुम मुझसे अब विलग हुए, प्रियतम !
उस राजा की नगरी में जा बस गये कहीं पर हो, प्रियतम ! 
मिल गयी संगिनी हो तुमको कोई मनभायी-सी, प्रियतम ! 
है भाग खुला तब तो मेरा, सुखिया हूँ आज हुई, प्रियतम॥१०१८॥

विधि ने मेरी विनती सुन ली, आखिर तुम चेत सके, प्रियतम !
मेरे प्रति जो था मोह महा, छूटा फंदा उसका, प्रियतम !
प्राणाधिक ! भूल सके हो यदि सचमुच इस दासीको प्रियतम !
दे प्यार किसी को, नाथ ! अहा ! कितने सुख में होगे, प्रियतम॥१०१९॥

दे रही कल्पना ही जब यह सुख है अपार मुझको, प्रियतम ! 
हो जाय कहीं यह सत्य, भला, फिर तो क्या है कहना, प्रियतम !
लगता है किंतु असंभव यह, तुम भूल सको मुझको, प्रियतम ! 
है पता अनादिकाल से कुछ तुम हो कैसे, मेरे प्रियतम॥१०२०॥

जो दूत बना है, उससे, या अनुताप लिये उरमें, प्रियतम ! 
कहती है जो मुझसे री ! ‘वे हैं चले गये’ उससे, प्रियतम !
कहती हूँ, अच्छा सुनो तनिक, पर मत कहना सबसे, प्रियतम !
जीवन है क्या, जाकर देखो उनका, जुड़कर मुझसे, प्रियतम॥१०२१॥

वक्षःस्थल की धड़कन में है, बस, नाम भरा मेरा, प्रियतम !
आँखोंकी काली पुतली में हूँ भरी हुई मैं ही, प्रियतम ! 
उनके प्रत्येक रोम में हूँ परिपूरित केवल मैं, प्रियतम ! 
उनकी प्रत्येक वृत्ति में है इस दासीका मुख ही, प्रियतम॥१०२२॥

कोई है छिपी शक्ति उनमें, जिससे कोई उनको, प्रियतम !
पहचान नहीं पाता, तुम भी भोले हो या भोली, प्रियतम !
उनका मेरा वियोग होना सम्भव है नहीं कभी, प्रियतम ! 
रोते-रोते धुलकर आँखें यह सत्य सुलभ होगा, प्रियतम॥१०२३॥

रोती क्यों हूँ फिर मैं, इसका कुछ मर्म बताती हूँ, प्रियतम !
संकोच नहीं है तनिक मुझे इसके कह देने में, प्रियतम ! 
क्रन्दन अनादि यह है मेरा, होगा न अन्त इसका, प्रियतम !
तुम समझ सको तो लो समझो जीवन यह है मेरा, प्रियतम॥१०२४॥

है प्रेम-पाठशाला उरमें, पढ़ती थी, हूँ पढ़ती, प्रियतम ! 
है प्रथम पाठ, उच्चारण कर लिखना उन वर्णों को, प्रियतम !
खड़ियामिट्टी से नहीं, अश्रु भीतर से आता है, प्रियतम ! 
गोली-सी काँचमयी बनकर, अक्षर लिख जाता है, प्रियतम॥१०२५॥

अक्षर का बोध हुआ जिसको, लिखती है शब्दों को, प्रियतम !
सीधे-सीधे रजताभ तनिक, उन वारि-बिन्दुओं से, प्रियतम !
संयुक्त हुए फिर आते हैं बनकर सरसीले वे, प्रियतम !
आँखों की स्वर्णकणावलिसे लिखकर पढ़ती वह है, प्रियतम॥१०२६॥

अब है विधेय-उद्देश्यमयी वह भावपंक्ति आती, प्रियतम !
रहता है गूढ़ अर्थ निरुपम अज्ञात किंतु उसका, प्रियतम !
जो है विशुद्ध वह सत्वमयी अविराम नयनधारा, प्रियतम !
लिखते-लिखते उससे सबकी ताली मिल जाती है, प्रियतम॥१०२७॥

है हेतुरहित जो सूक्ष्म, अमल, वह महाभाव विद्या, प्रियतम !
प्रतिपल है जो बढ़ती, अखण्ड, सीमाविहीन जो है, प्रियतम !
वस्तुतः अनिर्वचनीय सदा अनुभवमय है गहरी, प्रियतम !
अभिनव सुन्दर ‘अथ’ है उसका कहनेके लिये यही, प्रियतम॥१०२८॥

आगे क्या है कोई भी क्या कह सकती है इसको, प्रियतम !
आगे जाकर जो डूब गयी, फिरती है क्या पीछे ! प्रियतम !
कहती है जो जितना कुछ भी, है बात इधर की ही, प्रियतम !
कहनेवाली मुझ-सी सचमुच है डूबी हुई नहीं, प्रियतम॥१०२९॥

इतना कहती-कहती बाला आकुल हो दौड़ चली, प्रियतम ! 
श्यामल तमाल की शाखा को करमें लेकर बोली, प्रियतम !
‘जीवनधन ! चलो वहाँ अब तुम, है जहाँ स्रोत नीला, प्रियतम !
दी थी तुमने जो यह तुमको पहनाऊँगी माला’, प्रियतम॥१०३०॥

हूँ आर्द्र किये रहती इसको नयनों की बूँदों से, प्रियतम !
मुरझा न उठे यह किंचित् भी, इस भय से भीत हुई, प्रियतम !
हूँ सीख सकी अबतक मैं यह केवल इतना-सा ही, प्रियतम !
‘जो वस्तु मिले तुमसे उसको वैसी ही है रखनी’, प्रियतम॥१०३१॥

पर नाथ ! मुझे लेकर तुमको जाना है इस वनसे, प्रियतम ! 
ठहरी क्यों हूँ फिर मैं, अच्छा, कह देती हूँ यह भी, प्रियतम ! 
यह माला ही बन्धन है, मैं देकर किसको जाऊँ, प्रियतम ! 
कोई न मिली मुझको ऐसी, करपर जिसके रख दूँ, प्रियतम॥१०३२॥

है नहीं फेंक देना सम्भव इसको, न साथ लेना, प्रियतम !
इसमें, तुममें है भेद नहीं, थी जुड़ी उरस्थल से, प्रियतम !
मैंने देखा, हूँ देख रही, कण-कण में तुम इसके, प्रियतम !
हो भरे हुए तुम ही हो या यह बनकर खेल रहे, प्रियतम॥१०३३॥

हूँ सोच रही इनकी ही यदि वह उक्ति सत्य निकले, प्रियतम !
फिर भी तुम तो आओगे ही, आकर पर जो देखो, प्रियतम !
माना था प्राणेश्वरी जिसे, है फेंक दिया उसने, प्रियतम ! 
वह हार बना था जो मैं ही, आकुल कितने होगे, प्रियतम॥१०३४॥

‘पगली थी, भोली थी दुखिया’ कहकर कुछ ऐसे ही, प्रियतम !
तुम लौट चले जाने वाले होते यदि पुनः कभी, प्रियतम ! 
होती न मुझे इसकी चिन्ता, जाती मैं चली कभी, प्रियतम !
रोओगे पर तुम तो ऐसा, फट जाय हृदय नभ का, प्रियतम॥१०३५॥

मुरझा जब धूल सनी माला अवनी परपड़ी हुई, प्रियतम ! 
कह देगी मेरी बात बिदा हो जाने की तुमसे, प्रियतम ! 
मानिनी हुई इन कुञ्जों में हूँ छिपी नहीं अब मैं, प्रियतम ! 
अब दूर, दूर, अत्यन्त दूर जा चुकी अकेली हूँ, प्रियतम॥१०३६॥

उस ओर जिधर जाकर कोई है लौट नहीं पायी, प्रियतम ! 
है कहीं नहीं इतिहासों में ऐसा वर्णन मिलता, प्रियतम ! 
जीवित रह जाओगे क्या तुम रहने के लिये यहाँ, प्रियतम ! 
उस महाप्रलय को भ्रमसे भी मैं सोच नहीं सकती, प्रियतम॥१०३७॥

कोई कह दे,‘फिर भोली री ! क्यों साथ न ले जाती ?’ प्रियतम !
वह समझ नहीं पाता कुछ भी रस-रीति अतः कह ले, प्रियतम ! 
है नहीं कभी उसने देखा मेरा मिलना तुमसे, प्रियतम ! 
होता है निरावरण कैसा राका की रजनी में, प्रियतम॥१०३८॥

अपनी ग्रीवा में जबतक तुम, माला को थे पहने, प्रियतम ! 
थे सभी कुसुम अविकृत इसके आवरणहीन हँसते, प्रियतम !
अपनी इस दासी को तुमने पहना दी, इससे ही, प्रियतम ! 
मैं थी जैसी, ये फूल बने, पड़कर छाया मेरी, प्रियतम॥१०३९॥

जो देख रहे तुमको थे वे प्रतिबिम्ब-गृहीत हुए, प्रियतम !
परछाँही अधिक लगी प्यारी, भूला स्वरूप उनको, प्रियतम !
अभिमान भरी मैं तुमसे थी आराधन करवाती, प्रियतम ! 
अपने शरीर का दोष अतः इनमें ही वह आया, प्रियतम॥१०४०॥

अब उसी उरःस्थल पर इनको है मुझे झुला लेना, प्रियतम !
मिलकर तुमसे ये पुनः मुझे, तुमको पहचानेंगे, प्रियतम ! 
एवं उस धागे को, जिसमें सब नित्य पिरोये हैं, प्रियतम ! 
रोकर हँसकर फिर हम दोनों खेलेंगे खेल नया, प्रियतम॥१०४१॥

इस वन में नहीं, उधर आगे, आगे-से-आगे जा, प्रियतम ! 
है नित्य रसोदधि नील जहाँ क्रमशः गहरा-गहरा, प्रियतम ! 
है सदा एक-से-एक ऊर्मि ऊँची उठती रहती, प्रियतम ! 
जो है अनादि एवं अनन्त, उसमें क्रीड़ा होगी, प्रियतम॥१०४२॥

इतना कहकर फिर छोड़ चली द्रुम की डाली बाला, प्रियतम !
आगे कुछ और बढ़ी, मुड़कर हँसती-हँसती बोली, प्रियतम !
‘हो प्राणनाथ ! तुम ? नहीं, नहीं, यह है मयूर बैठा, प्रियतम !
बिगड़ी है बुद्धि अहो ! मेरी, है कृष्ण मधुप यह तो, प्रियतम॥१०४३॥

कुछ सोच रहा है, जैसे वे गम्भीर कभी होते, प्रियतम ! 
प्रायः है रंग-ढंग इसका मिलता-जुलता उनसे, प्रियतम ! 
है म्लान दीखता किंतु हाय ! इस समय न जाने क्यों, प्रियतम !
सम्भव है यह मेरा प्रलाप सुनकर है खिन्न हुआ, प्रियतम॥१०४४॥

मैं देख न हाय ! सकी, दृग हैं बह रहे सतत इसके, प्रियतम !
भौंरा प्यारे ! रोओ मत तुम, कह दो सब कुछ मुझसे, प्रियतम !
जो कुछ भी लिये हृदयमें हो, संकोच न तनिक करो, प्रियतम !
मैं हूँ उनकी प्यारी दासी, जो चाहोगे, दूँगी, प्रियतम॥१०४५॥

है कोष पूर्ण, सर्वदा अतुल, अक्षय, असीम उनका, प्रियतम !
स्वामिनी किंतु यह है दासी सर्वदा सदा उसकी, प्रियतम !
उज्ज्वल तारों की यह कुंजी प्राणाधिक ने मेरे, प्रियतम ! 
देखो बाँधी अपने कर से हँसकर है अञ्चल में, प्रियतम॥१०४६॥

अतएव असम्भव भी सम्भव करके दूँगी तुमको, प्रियतम ! 
विश्वास करो, उनकी दासी है सत्य सदा कहती, प्रियतम ! 
है भौंर ! कठिन कीमत देनी आँखों की बूँदों की, प्रियतम !
अनमोल, भला, ये हैं, इनका प्रतिदान नहीं होता, प्रियतम॥१०४७॥

कोई विरला होता है, जो लेता है समझ इसे, प्रियतम ! 
खोता न कभी इनको वह है बाहर लाकर दृग से, प्रियतम !
मिटकर शरीर की सुधि, बरबस गिर पड़ती हैं जब ये, प्रियतम !
लेती हूँ बीन दौड़कर मैं, पाऊँ जो देख कहीं, प्रियतम॥१०४८॥

फिर हार बना, जीवनधन के उरपर रख देती हूँ, प्रियतम !
हँसकर, उरमें भर फिर मुझको पहना रोते वे हैं, प्रियतम ! 
उनके करतल पर सिर रखकर रो उठती हूँ अब मैं, प्रियतम ! 
है सुख अचिन्त्य हम दोनों के हँसने, उस रोने का, प्रियतम॥१०४९॥

इसलिये मिलिन्द ! कहो, देकर यह भेंट अनूप मुझे, प्रियतम !
लेने की क्या अभिलाषा है, सब कुछ हूँ लिये खड़ी, प्रियतम !
देने में ही सुख है मुझको लेने से अधिक कहीं, प्रियतम ! 
उनका, मेरा स्वभाव कुछ है चिरकाल एक-सा ही, प्रियतम॥१०५०॥

वाणी बाला की रुद्ध हुई, लज्जा में समा गयी, प्रियतम ! 
कहती-कहती कह दी उसने, जो बात न थी कहनी, प्रियतम !
होकर कुछ सावधान-सी फिर बोली,‘मधुकर तुम हे !’ प्रियतम ! 
‘बचना छाया से भी मेरी, भ्रम से भी मत छूना, प्रियतम॥१०५१॥

है मुझे प्रशंसा प्रिय अपनी, कर गयी स्वयं मैं हूँ, प्रियतम !
निर्मल मति हो, इससे इसपर विश्वास किया तुमने, प्रियतम !
हो गये प्रभावित ठगिनी की ठग-भरी सरलता से, प्रियतम ! 
फिर चले पकड़ने चरण महामलिना इस अधमा के, प्रियतम॥१०५२॥

है सुधासिन्धु में, छिल्लर की कणिका में अन्तर जो, प्रियतम !
रवि-शशिके किरण-दान में, फिर जुगनू के उड़नेमें, प्रियतम !
चिन्तामणि में, उस छिन्न काँच मलपूरित में जो है, प्रियतम !
इतना पृथकत्व शील का है उनके एवं मेरे, प्रियतम॥१०५३॥

लेती-लेती न थकी मैं, वे हारे न कभी दे-दे, प्रियतम ! 
‘क्या मिला ?’ सदा बोली मैं, वे ‘दे कुछ न सका’ बोले, प्रियतम ! 
थी गर्व लिये ‘स्वाहा सब कुछ करके जीती मैं हूँ’ प्रियतम !
‘न्योछावर मैं न हुआ, धिक् है जीवन’, कहते वे थे, प्रियतम॥१०५४॥

इतने पर भी लज्जाहीना समता करने बैठी, प्रियतम !
उनसे अपनी अलि हे रसविद् ! भारी अपराध हुआ, प्रियतम !
करती थी दम्भ सदा मैं हूँ, करती रहती अब भी, प्रियतम ! 
दे प्यार नहीं पायी क्षणभर सपने में भी उनको। प्रियतम॥१०५५॥

रो उठी विकल बाला, कहकर अब ‘साँवर ! साँवर ! हे प्रियतम ! 
देना वरदान, न हो मुझसे अपमान किसी का भी, प्रियतम !
दूँ भौंरे को छूने कैसे, ये किंतु चरण अपने, प्रियतम !
जिनको रसमत्त हुए तुमने पोंछा था अलकों से, प्रियतम॥१०५६॥

थे अभी क्षितिज के पार हुए दिनकर समेट किरणें, प्रियतम !
लहरें श्यामा सरिता की थीं कहतीं मुझसे, ‘ठहरो’, प्रियतम ! 
पर तुम कहते, ‘प्रियतमे ! चलो, यह रात अँधेरी है’, प्रियतम !
‘वन घोर, गहन है सम्मुख का, पथ भी टेढ़ा कुछ है’, प्रियतम॥१०५७॥

भारी असमंजस में अब थी, कैसे क्या करूँ, अहो ! प्रियतम ! 
थी त्वरा भरी तुममें, दृग में मनुहार लहर के थी, प्रियतम !
अनसुनी करूँ उसकी विनती या और तनिक ठहरूँ, प्रियतम !
हँसते थे तुम, मैं चिन्तित थी कुछ रुककर फिर बोली, प्रियतम॥१०५८॥

जल्दी क्या है ? तुम ठगते हो, शुक्ला रजनी यह है, प्रियतम !
देखो शशधर है प्राची में, बस, आनेवाला ही, प्रियतम ! 
वह आये, मत आये, श्यामल मुख ही प्रकाश देगा, प्रियतम !
जब हो तुम मेरे साथ सदा, क्या भय है इस वनका, प्रियतम॥१०५९॥

रस से पूरित मीठी बातें कहकर हँसते चलना, प्रियतम ! 
ग्रीवा में देकर मेरी यह कर वाम मृदुल अपना, प्रियतम ! 
वनदेवी कर देगी रचना सुन्दर नवीन पथ की, प्रियतम ! 
पहुँचेंगे सीधे हम दोनों अपने निकुञ्जगृह में, प्रियतम॥१०६०॥

मानो डर हो मनमें, ऐसे बोले अब तुम मुझसे, प्रियतम !
‘मेरे प्राणों की रानी हे ! अहि, एक भयंकर है, प्रियतम !
हम दोनों खड़े जहाँ अब हैं, बस उसी गगनतल में, प्रियतम !
रहता है छिपकर वह अथवा धरणी में धँसा हुआ, प्रियतम॥१०६१॥

ऐसा मायावी है जिसको विरला ही जीत सके, प्रियतम ! 
वह इसी समय पीने पानी आता है इधर, यहीं, प्रियतम ! 
छाया भी पड़ते ही उसकी आती है बेहोशी, प्रियतम ! 
ऐसी न मिटे, जो कोटि मरें पचहार हकीम भले, प्रियतम॥१०६२॥

उसके आने से पहले ही तटिनी को छोड़ चलें, प्रियतम !
देखेंगे खेल कभी फिर यह सुन्दर इन लहरों का, प्रियतम ! 
क्यों व्यर्थ विकट झगड़ा भारी लें मोल अभी इससे, प्रियतम !
डर जाओगी तुम देख उसे डसने जो दौड़ पड़े’, प्रियतम॥१०६३॥

मैं सदा हठीली जो ठहरी, बोली,‘अच्छा, देखूँ’, प्रियतम ! 
‘कैसा है बतला दो केवल, पूरब से, पश्चिम से, प्रियतम !
‘उत्तर से या दक्षिण, नीचे अथवा वह ऊपर से’, प्रियतम !
‘आयेगा तृषा बुझाने या सुख यह हरने मेरा’, प्रियतम॥१०६४॥

कहकर, हँसकर मैं बैठ गयी, हँसते तुम खड़े रहे, प्रियतम !
बङ्किम चितवन से उत्तर की फिर धरा दिखा करके, प्रियतम !
यह कहा,‘जीवनेश्वरि ! देखो फटती सी यह कुछ है’, प्रियतम !
‘संभव है इस पथ से आये’, इतनेमें दीख पड़ा, प्रियतम॥१०६५॥

सचमुच अतिशय काला विषधर फन काढ़े निकल पड़ा, प्रियतम ! 
डरकर मैं तुमसे चिपट गयी, बोले तुम,‘भय न करो’, प्रियतम !
‘छू छाँह नहीं सकता, मेरे प्राणों की देवी की’, प्रियतम !
‘चञ्चलता, प्राणाधिके ! नहीं करना पर यहाँ भला’, प्रियतम॥१०६६॥

यह देख रंग काला मेरा, ‘है परपक्षी कोई’, प्रियतम !
ऐसा है सोच रहा कपटी, डरता है इससे ही, प्रियतम !
‘काले-टेढ़े को होता है भय काले-टेढ़े से’, प्रियतम !
‘गोरी-सरला तुम हो, मुझसे अतएव जुड़ी रहना’, प्रियतम॥१०६७॥

मैं भूल नहीं पाती जल से पूरित उन नयनों को, प्रियतम !
‘गोरी-सरला’ कहकर मुझको तुम देख रहे जब थे, प्रियतम !
प्राणों के संवेदन ऐसे केवल निधि हैं मेरी, प्रियतम !
कैसे कितने सुन्दर वे हैं किस भाँति कहूँ तुमसे, प्रियतम॥१०६८॥

जो हो, अपलक होकर अब मैं थी देख रही अहिको, प्रियतम !
सहसा उसके मुखमें प्रतीति, ऐसी हो गयी मुझे, प्रियतम !
यह चिरपरिचित मुसकान सदा जो लिये अधरपर हो, प्रियतम !
मानो है छिपी वहाँ भी, बस, विकसित होगी क्षणमें, प्रियतम॥१०६९॥

इतनेमें उसकी आँखों में काली परछाँही-सी, प्रियतम !
दीखी त्रिभङ्ग इन अङ्गों की मुद्रा अनुपम लोनी, प्रियतम !
फिर तो उस विषधर के तनके सारे अवयव में ही, प्रियतम !
भासित तुम एक लगे होने चञ्चल झलमल करते, प्रियतम॥१०७०॥

अत्यन्त अचम्भित थी, कैसे संघटित हुआ यह था,प्रियतम !
क्षण एक उसे, फिर बार-बार तुमको थी देख रही, प्रियतम !
उस महाउरग-उरमें तुम तो प्रत्यक्ष खड़े ही थे,प्रियतम !
मैं सोच रही थी, है सच यह, अद्भुत है या सपना, प्रियतम॥१०७१॥

‘मेरे प्राणों के प्राण ! सुनो, अब कहा पुनः तुमने, प्रियतम !
क्रीड़ा देखो हँस-हँसकर, पर आगे मत बढ़ जाना’, प्रियतम !
दुर्दमन कहीं झपटे, डस ले विषमय दो दाँतों से, प्रियतम !
मेरे जीवनका क्या होगा, अनुमान तनिक कर लो, प्रियतम॥१०७२॥

हो गयी विमूढ़ा, कौतुक था यह भूल भुलैया-सा, प्रियतम !
आखिर तुमसे कह गयी, मुझे जैसे था दीख रहा, प्रियतम !
तुम हँसे, कहा,‘प्रियतमे ! दया तुमने मुझपर की है, प्रियतम !
दृगपुतरी में हो नित्य मुझे रखती, फल है उसका’, प्रियतम॥१०७३॥

‘पर भाग चलें अब तो, विषधर हो गया बली मुझ-सा, प्रियतम !
आँखें डालीं तुमने इस पर, भर दिया मुझे इसमें, प्रियतम !
बल मेरा चला गया इसमें, दुर्धर्ष हुआ यह है,प्रियतम !
इसलिये चलो अविलम्ब, अहो ! कहना मेरा मानो’, प्रियतम॥१०७४॥

‘अब तो छद्मी पीछे से ही हमपर जो टूट पड़े, प्रियतम !
कर पाऊँगा क्या मैं इसका, की भूल बड़ी तुमने, प्रियतम !
अतएव अङ्कमें लेकर मैं तुमको भागूँ ऐसा, प्रियतम !
जो छू न सके हम दोनों को, यह है उपाय इतना’, प्रियतम॥१०७५॥

चिन्तित अब हुई, कदाचित् यह फिर भी न पिण्ड छोड़े, प्रियतम !
दुर्दैव-योगवश तेज अधिक गति बने सर्प की ही, प्रियतम !
क्षत नील पीठपर ही कर दे धीरे से, रच माया, प्रियतम !
मैं जान न पाऊँगी, तुम तो कहने से रहे इसे, प्रियतम॥१०७६॥

थी बात बहुत-सी सोच रही, इतने में कानों में, प्रियतम !
आयी फुफकार, भयंकर-सी ध्वनि, सिहर उठी मैं थी, प्रियतम !
बोले तुम,‘मेरे प्रति ही अब है रोष हुआ इसको’, प्रियतम !
‘तुमने कर दी कुछ देर अतः भिड़ना ही है इससे’, प्रियतम॥१०७७॥

कहकर दुकूल कटि में तुम थे कसते जाते, हँसते, प्रियतम !
सहसा मन में आया देखूँ, कितना बल है अहि में,प्रियतम !
अबला हूँ, किंतु नित्य मेरे भीतर-बाहर तुम हो,प्रियतम !
क्या सर्प सकेगा कर, इसपर मैं ही जो लपक पडूँ, प्रियतम॥१०७८॥

मेरे ही द्वारा मिला इसे बल है, कहते ये हैं, प्रियतम !
फिर भले मुझे भ्रम हो, पर हैं ये-ही-ये दीख रहे,प्रियतम !
कह देने पर तो रोक मुझे लेंगे अवश्य ही ये,प्रियतम !
चुपचाप अचानक जा समीप देखूँ क्या है कैसा, प्रियतम॥१०७९॥

अन्तर था सात हाथ का ही, क्षणभर नीरज-मुख को, प्रियतम !
मैं देख वेग चपला का ले उछली उसके आगे, प्रियतम !
बोली एवं,‘कर ले तू जो चाहे, सन्मुख मैं हूँ’, प्रियतम !
‘है सर्प सही तो काट मुझे, भ्रमजाल नहीं तो है’, प्रियतम॥१०८०॥

क्षण एक मुँदी आँखें मेरी, तुम तो पीछे थे ही, प्रियतम !
भर लिया भुजाओं में मुझको, अनुभूति हुई ऐसी, प्रियतम !
दृग खोल तुरंत चकित होकर बोली,‘वह कहाँ गया ?’ प्रियतम !
बैठे मेरे कच सींच रहे तुम थे लोचन-जल से, प्रियतम॥१०८१॥

उस समय अहो ! हम दोनों का कैसा था हाल हुआ, प्रियतम !
तुम याद उसे कर लेना, मैं रख लेती हूँ मन में, प्रियतम !
क्या है कहना किससे, भौंरा समझेगा क्या इसको, प्रियतम !
दे प्राण मिला तुममें, मुझमें तो जान भले ही ले, प्रियतम॥१०८२॥

रोता है पर यह इसीलिये कुछ तो कहना ही है, प्रियतम !
लज्जित हूँ बहुत अधिक यद्यपि उतना भी कहने में, प्रियतम !
जो काल परे कलना से है, कितना था बीत चुका, प्रियतम !
तुम ही जानो, समाधि जब थी टूटी, तुम यों बोले, प्रियतम॥१०८३॥

‘जिन महाभावमय नयनों में हूँ बसा सदा ही मैं’, प्रियतम !
‘जाता है उपल पिघल जिनसे पावक होता हिम है’, प्रियतम !
‘जो हैं अतीत फिर वर्तमान, भावीके दृश्यों में’, प्रियतम !
‘सागर रसमय उच्छलित, नित्य भरती स्वभाव से ही, प्रियतम॥१०८४॥

‘उन आँखों में ही सना हुआ उनसे ही प्रेषित मैं,प्रियतम !
था हुआ, अतः गल गया उरग, अचरज इसमें क्या है ? प्रियतम !
बच रहा रंग काला उरमें भरनेके लिये वहाँ, प्रियतम !
प्रियतमे ! कहूँ क्या, मेरी है हो रही रुद्ध वाणी’ प्रियतम॥१०८५॥

प्रक्षालित किये तरंगों ने फिर पद हम दोनों के, प्रियतम !
व्याकुल होकर आ चिपट गयी रेणुका किंतु अमला,प्रियतम !
‘क्यों छोड़ चले तुम मुझे यहीं, दम्पति हे !’ थी कहती, प्रियतम !
उज्ज्वल वितान था तान रहा ऊपर हिमकर, कर से, प्रियतम॥१०८६॥

मनमें मैं व्यथित हुई-सी थी कह गयी,‘न छोडूँगी’, प्रियतम !
‘कोई भी हो, कैसी भी हो, जो जुड़ी तनिक-सी है’, प्रियतम !
‘आशा उसकी मैं क्यों तोडूँ, साँवर तो हैं मेरे’, प्रियतम !
‘दूँगी कह जो, कर लेंगे, फिर यह तो है पद थामे।’ प्रियतम॥१०८७॥

‘कितनी मृदुला, कितनी हलकी, कितनी उजली यह है, प्रियतम !
जड़ बनी अपनपौ खोकर, है मेरे ही लिये पड़ी, प्रियतम !
साँवर की यह दासी इसकी निष्ठा कैसे भूले, प्रियतम !
हे धूलि ! परम मंगल हो, ये स्वीकार करें तुमको।’ प्रियतम॥१०८८॥

हे प्राणनाथ ! हो गयी देर, अब चलो कुञ्ज में, हे प्रियतम !
हे श्यामचन्द्र ! किरणों का हूँ स्वागत करती कहती, प्रियतम !
‘देते रहना शीतलता ही अविराम यहाँ सबको’, प्रियतम !
फिर रास दिखाऊँगी तुमको, कह चली, चले तुम भी, प्रियतम॥१०८९॥

कुछ बात बताकर तुम हँसते, बन जाती फूल हँसी, प्रियतम !
मेरे आगे बन जाता था सुन्दर पथ सुमनों का, प्रियतम !
रखते पर पद तुम रज में थे, कुसुमों को बचा-बचा, प्रियतम !
था हेतु बताया,‘प्यारी ! हैं प्राणोपम रजकणिका।’ प्रियतम॥१०९०॥

‘जब दयामयी तुमने इच्छा कर ली, ये साथ चलें, प्रियतम !
त्यागूँ कैसे इनको फिर मैं, हूँ जहाँ, रहेंगी ये,प्रियतम !
मेरे प्राणों की रानी के पद में जो चिपक गयीं,प्रियतम !
उनको क्या दे सकता हूँ मैं, ऋणिया हूँ नित्य बना’, प्रियतम॥१०९१॥

रो उठी बात सुनकर मैं थी, जैसे-तैसे पहुँची,प्रियतम !
तटिनी निकुञ्ज में शय्या थी पद्मों की बिछी हुई,प्रियतम !
मैं लेट गयी, तुम जा बैठे मेरे ही पदतल में, प्रियतम !
हो गद्गद बोले,‘दान महा प्रियतमे ! मुझे यह दो।’ प्रियतम॥१०९२॥

‘हूँ लिये लालसा मैं भी यह, अपने केशों से ही,प्रियतम !
ये पोंछ चरण असमोर्ध्व रहूँ बड़भागी, सुखी सदा, प्रियतम !
मेरा ही स्वत्व रहे, इनपर, केवल छूएँ वे ही,प्रियतम !
जिनका मन बुद्धि अहं काला जलदाभ बने मुझ-सा।’ प्रियतम॥१०९३॥

‘जैसे सुख हो तुमको, करलो, उसमें ही हूँ सुखिनी, प्रियतम !
जीवनधन ! अहो ! कभी तुमको मैं म्लान नहीं देखूँ, प्रियतम !
अस्तित्व रहे बस कण-कण का, मेरे मनके, तनके, प्रियतम !
देनेके लिये नित्य तुमको प्रतिपल नवीन सुख ही, प्रियतम॥१०९४॥

भावित इस भाँति हुई मेरी पलकों से अनुमति ले, प्रियतम !
लालित सुरभित कुन्तल से तुम कर रहे चरण ये थे, प्रियतम !
था भान न हुआ हमें यह भी, कब बीत गयी रजनी, प्रियतम !
‘हे मधुप ! अतः छूना मत तुम मेरा पद, है विनती’, प्रियतम॥१०९५॥

‘हो गयी निमीलित बाला की उत्पल-दल-सी आँखें, प्रियतम !
कहती जाती यद्यपि अब भी वह बात रसीली थी’, प्रियतम !
सुन सकीं उसे पर वे जो थीं स्वाहा सर्वस्व किये, प्रियतम !
मोहित जो था जल-बुद्बुद् से या हैं, सुन लें कैसे, प्रियतम॥१०९६॥

‘पाटल-से होठोंका हिलना देखा दिनकर ने है, प्रियतम !
निर्लिप्त, किंतु फिर भी विमुग्ध आकाश लिये ध्वनि है, प्रियतम !
छूकर है उसे अनिल चञ्चल, है नीर सरस उससे, प्रियतम !
उसकी सहिष्णुता की सुगन्ध ली छिपा मेदिनी ने’, प्रियतम॥१०९७॥

दो दण्ड वहाँ सब ओर रही छायी नीरवता-सी, प्रियतम !
केवल थी स्वगत बात करती वह भावमयी पुतली, प्रियतम !
मानो फिर लहर लगी उठने उसमें नवीन सहसा, प्रियतम !
बोली खिन्ना-सी, किंतु मधुर तारों से भी स्वरमें, प्रियतम॥१०९८॥

‘बक गयी अनर्गल मैं क्या-क्या, विक्षिप्त हुई मति है, प्रियतम !
रोता है दीन हुआ षटपकद्, मैं कथा लगी कहने, प्रियतम !
बतला दो, बतला दो, अलि हे ! हर लूँगी सभी व्यथा, प्रियतम !
कहती ध्यानस्थ हुई क्षण कुछ, कह उठी पुनः पगली’, प्रियतम॥१०९९॥

‘हे भृङ्ग ! न जब तुम कहते हो, हूँ पूछ रही उनसे, प्रियतम !
‘देंगे कह वे।’ पलभर रुककर, रच दी रस की सरिता, प्रियतम !
'मैं गुप्त मनोरथ जान गयी, जो लिये हुए तुम हो, प्रियतम !
वह तो दे ही देती हूँ, फिर किंचित् अपनी रुचि से।’ प्रियतम॥११००॥

द्रुमलता तथा भुजलता बनो उनकी इस दासी की, प्रियतम !
सुख-संग मिले उनका तुमको, खण्डित न काल से हो, प्रियतम !
मेरी इस अरुण कञ्चुकी के बंदों में बँधी हुई, प्रियतम !
अनुरक्ति नित्य सहचरी रहे सौरभ देती तुमको, प्रियतम॥११०१॥

गिर गयी धरापर कहकर यह, तन-सुधि खोकर बाला, प्रियतम !
सहचरी बड़ी जो उससे थी दुखिया उसके दुख से, प्रियतम !
उसका सिर गोदी में अपनी लेकर बोली रोती, प्रियतम !
हे दूत ! विरह में उनके है क्या दशा हुई इसकी, प्रियतम॥११०२॥

‘दीखे क्षणभर तुम थे इसको, बोला कुछ फिर भूला, प्रियतम !
अनुभव तमाल को कर साँवर, कर गयी बात उस से, प्रियतम !
आँखें जब पुनः पड़ी तुमपर, थी भ्रमित हुई तुमसे, प्रियतम !
हैं वे, है मोर, नहीं भौंरा, उर खोल गयी अलि से।’ प्रियतम॥११०३॥

‘वरदान दिया है मधुकर को इसने, तथापि मानो, प्रियतम !
अपने ही लिये इसे तुम हे ! साँवरके दूत सखा, प्रियतम !
अक्षरशः होगा सत्य सदा, कहती मैं हूँ ललिता, प्रियतम !
उनसे कहना, जो है देखा या सुना यहाँ तुमने।’ प्रियतम॥११०४॥

कहकर मुरछित हो गयी सखी वह भी वैसी दीना, प्रियतम !
वह दूत बहाता जल दृग से दोनों की पदरज में, प्रियतम !
दो दण्ड लोटकर चला गया उन्मत्त हुआ वन से, प्रियतम !
हैं ज्ञात सभी बातें तुमको, कह गयी तनिक फिर भी, प्रियतम॥११०५॥

जब जगी स्वप्न से थी बाला उस पादप के नीचे, प्रियतम !
पीये मद-सी उठ पड़ी, चली, पग थे डगमग उसके, प्रियतम !
फिर भान हुआ, साँवर आये, दे गलबाँही बोले, प्रियतम !
‘प्रियतमे ! चलो लीला देखें धारामय उस सर की’, प्रियतम॥११०६॥

अब पुनः वही बाला बैठी ललिता निकुञ्ज में है, प्रियतम !
तुम भी हो साथ, किंतु मानो है देख रही सपना, प्रियतम !
पीपर है, ऊपर है जिसकी जड़, है शाखा नीचे, प्रियतम !
उसके नीचे अर्चन कर है संथा देती तरु से, प्रियतम॥११०७॥

है तत्त्व बताया तुमने ही, तुम-ही-तुम हो मेरे, प्रियतम !
है या केवल राधा-राधा, फिर नित्य युगल भी हो, प्रियतम !
यह मैं प्रतिबिम्बित है प्रतिमा राधाकी मायामें, प्रियतम !
है किंतु बिम्बसे भिन्न कहाँ सत्ता छायाकी, हे प्रियतम॥११०८॥

राधिकारमण निरवधि जय, जय, जय अम्बुजनयन सदा, प्रियतम !
जय सतत नन्दनन्दन जय, जय, जय नाथ निरंतर, हे प्रियतम !
गोपिकाप्राण सर्वदा तथा जय मन्मथमथन अहो, प्रियतम !
चिरकाल विश्वरञ्जन जय, जय, जय कृष्ण अहर्निश, हे प्रियतम ! ॥११०९॥

जय राधावन कुञ्जविहारिन्, कुञ्चित कुन्तल मुरलीधारिन् ! 
प्राणेश्वरीनयनसृतिकारिन् जय विहारिणी भावविनोदिन्
नाची रसना, रसराज इसे जैसे जब नचा गये, प्रियतम !
गँठजोड़ अनन्तकाल तक यह इसका उनसे ही है, प्रियतम !
वे चाहेंगे, वैसी होगी यह महाभावलीला, प्रियतम !
जय अहो ! यशोदानन्दन जय मोहन जय वनमाली, प्रियतम॥१११०॥

प्राणाधिक जय कृष्ण, जय कुञ्जजनेश्वर !
कुञ्जेश्वरि राधे जय प्राणेश्वरि हि राधिके॥११११-क॥

दूसरा पाठ-
हे प्राणाधिक श्रीकृष्ण, जय कुञ्जजनेश्वरः !
हे प्राणाधिक मत्कृष्ण, जय कुञ्जजनेश्वरः॥११११-ख॥
''',
      ),
    ],
  );

