Chant it in the morning with the rising sun,
Chant it at night before you sleep.

—  —  ✦  —  —

हनुमान जी ने जब राम-नाम जपा,
पर्वत हिल गए, सागर कँप उठा।
एक साधारण व्यक्ति भी इस नाम से,
